//! Offline static finding foundation for GovFuzz.
//!
//! This crate intentionally starts with a small fixture rule set. The
//! important part for M20 #312 is the stable finding schema, baseline
//! comparison, suppression handling, and SARIF export path.

use finding_rules::Rule;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet, VecDeque};
use std::fs;
use std::io::{BufRead, BufReader, BufWriter, ErrorKind, Read, Write};
use std::path::{Path, PathBuf};

mod taint_spec;

pub const STATIC_SCHEMA_VERSION: &str = "govfuzz.static.v1";
pub const SUPPRESSIONS_SCHEMA_VERSION: &str = "govfuzz.static.suppressions.v1";
pub const CALL_GRAPH_SCHEMA_VERSION: &str = "govfuzz.static.call_graph.v1";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StaticScanOptions {
    pub root: PathBuf,
    pub out_dir: PathBuf,
    pub suppressions_path: Option<PathBuf>,
    pub baseline_path: Option<PathBuf>,
    pub policy_path: Option<PathBuf>,
    pub enabled_rules: BTreeSet<String>,
    pub disabled_rules: BTreeSet<String>,
    pub emit_sarif: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StaticScanSummary {
    pub json_path: PathBuf,
    pub markdown_path: PathBuf,
    pub sarif_path: Option<PathBuf>,
    pub findings_count: usize,
    pub suppressed_count: usize,
    pub resolved_count: usize,
    pub by_severity: BTreeMap<String, usize>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct StaticScanReport {
    pub schema_version: &'static str,
    pub root: String,
    pub counts: StaticCounts,
    pub findings: Vec<StaticFinding>,
    /// Findings grouped by ROOT CAUSE: one cluster per distinct data-flow (a taint
    /// source → sink flow collapses its N sink sites into one issue), so a reviewer
    /// sees one row per defect, not per site (#8 taint-slice clustering).
    #[serde(default)]
    pub issues: Vec<IssueCluster>,
    pub suppressed: Vec<SuppressedFinding>,
    pub analysis_gaps: Vec<AnalysisGap>,
    pub baseline: BaselineReport,
}

/// A root-cause cluster: the findings that share one underlying defect.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct IssueCluster {
    pub issue_key: String,
    pub cwe: String,
    pub rule_id: String,
    pub severity: String,
    pub representative_id: String,
    pub finding_ids: Vec<String>,
    pub count: usize,
    /// Composite triage priority 0.0–10.0 (#10): exploitability class (from the
    /// CWE) × confidence × reachability verdict — one number for a triage queue,
    /// finer than High/Med/Low. Higher = fix first.
    pub priority_score: f32,
    pub priority_factors: PriorityFactors,
    /// One concrete remediation step for this class of defect (#8).
    pub remediation: String,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct PriorityFactors {
    /// 0.0–10.0 base impact from the rule's CWE class (RCE > injection > info).
    pub exploitability: f32,
    /// 0.5/0.75/1.0 for low/medium/high finding confidence.
    pub confidence: f32,
    /// 0.4 blocked/lab-only · 0.85 unknown · 1.0 attacker-reachable.
    pub reachability: f32,
}

#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize)]
pub struct StaticCounts {
    pub findings: usize,
    pub suppressed: usize,
    pub new: usize,
    pub unchanged: usize,
    pub resolved: usize,
    pub analysis_gaps: usize,
    /// Distinct root-cause issues (clusters) — one per underlying defect.
    #[serde(default)]
    pub issues: usize,
    pub by_language: BTreeMap<String, usize>,
    pub by_rule: BTreeMap<String, usize>,
    pub by_severity: BTreeMap<String, usize>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct StaticFinding {
    pub id: String,
    pub rule_id: String,
    pub rule_slug: String,
    /// The CWE for this finding's rule (e.g. `"CWE-120"`), sourced from
    /// [`finding_rules::by_id`]. Surfaced top-level on every finding so the primary
    /// `static-report.json` carries per-finding CWE (parity with bandit/gosec/
    /// semgrep) rather than exposing it only in SARIF tags and the auto CSV. Empty
    /// only if the rule id has no `finding_rules` entry.
    pub cwe: String,
    /// A concrete one-line remediation for this finding's rule class, from
    /// [`remediation_for`]. Gives the JSON report the "what to do" fix text that
    /// semgrep (`help`) and bandit (`more_info`) ship; also mirrored into SARIF
    /// `help.text`.
    pub remediation: String,
    pub language: String,
    pub severity: String,
    pub confidence: String,
    pub baseline_status: BaselineStatus,
    pub message: String,
    pub location: SourceLocation,
    pub fingerprint: String,
    /// #09 durable finding identity — a line-INDEPENDENT id (rule + file + content
    /// key + a hash of the normalized code, never the line number). It survives
    /// unrelated edits that shift the finding's position, so a baseline still
    /// recognizes the same defect across refactors. `fingerprint` stays the primary
    /// (line-based) baseline key for backward compatibility; `identity` is the
    /// resilient secondary key.
    pub identity: String,
    pub evidence: Vec<StaticEvidence>,
    pub analysis: StaticAnalysis,
    pub triage: TriageMetadata,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum BaselineStatus {
    New,
    Unchanged,
}

