fn scan_qt_webengine_sandbox_disabled_config(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if config_fixture_path(path) {
        return;
    }
    for (line_index, line) in source.lines().enumerate() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        if let Some(column) = config_qt_webengine_sandbox_disabled_column(line) {
            push_pattern(
                findings,
                root,
                path,
                line_index,
                column + 1,
                "GF-530",
                "config",
                "qt-webengine-sandbox-disabled",
                "Qt WebEngine sandboxing is disabled",
                "sandbox",
                "Qt WebEngine is configured to disable Chromium renderer or plugin sandboxing.",
                t,
            );
        }
    }
}

struct KubernetesServiceAccountUsageCandidate<'a> {
    has_api_version: bool,
    kind: Option<String>,
    kind_line_index: usize,
    kind_column: usize,
    kind_snippet: &'a str,
    has_root_spec: bool,
    has_template_spec: bool,
    service_account_set: bool,
    automount_token_disabled: bool,
}

fn scan_kubernetes_default_service_account_usage(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    let lines = source.lines().collect::<Vec<_>>();
    let mut document_start = 0;
    for index in 0..=lines.len() {
        if index == lines.len() || lines[index].trim() == "---" {
            scan_kubernetes_default_service_account_document(
                root,
                path,
                lines.as_slice(),
                document_start,
                index,
                findings,
            );
            document_start = index + 1;
        }
    }
}

fn scan_kubernetes_default_service_account_document(
    root: &Path,
    path: &Path,
    lines: &[&str],
    start: usize,
    end: usize,
    findings: &mut Vec<StaticFinding>,
) {
    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    let mut candidate = KubernetesServiceAccountUsageCandidate {
        has_api_version: false,
        kind: None,
        kind_line_index: start,
        kind_column: 1,
        kind_snippet: "",
        has_root_spec: false,
        has_template_spec: false,
        service_account_set: false,
        automount_token_disabled: false,
    };

    for (line_index, line) in lines.iter().enumerate().take(end).skip(start) {
        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if config.path == "apiversion" && !trim_config_scalar(config.value).is_empty() {
            candidate.has_api_version = true;
        }
        if config.path == "kind" {
            let kind = trim_config_scalar(config.value);
            if !kind.is_empty() {
                candidate.kind = Some(kind.to_ascii_lowercase());
                candidate.kind_line_index = line_index;
                candidate.kind_column = config.value_column + 1;
                candidate.kind_snippet = config.snippet;
            }
        }
        if config.path == "spec" {
            candidate.has_root_spec = true;
        }
        if config.path == "spec.template.spec" || config.path.ends_with(".template.spec") {
            candidate.has_template_spec = true;
        }
        if kubernetes_service_account_path(config.path.as_str())
            && !kubernetes_config_null_or_empty(trim_config_scalar(config.value))
        {
            candidate.service_account_set = true;
        }
        if kubernetes_podspec_service_account_token_automount_disabled(
            config.path.as_str(),
            config.value,
        ) {
            candidate.automount_token_disabled = true;
        }
    }

    let Some(kind) = candidate.kind.as_deref() else {
        return;
    };
    if !candidate.has_api_version
        || !kubernetes_workload_kind_has_podspec(
            kind,
            candidate.has_root_spec,
            candidate.has_template_spec,
        )
        || candidate.service_account_set
        || candidate.automount_token_disabled
    {
        return;
    }

    push_pattern(
        findings,
        root,
        path,
        candidate.kind_line_index,
        candidate.kind_column,
        "GF-503",
        "config",
        "kubernetes-default-service-account",
        "Kubernetes workload uses the default service account",
        "kubernetes",
        "A Kubernetes workload omits serviceAccountName, so Kubernetes assigns the namespace default service account.",
        candidate.kind_snippet,
    );
}

fn kubernetes_workload_kind_has_podspec(
    kind: &str,
    has_root_spec: bool,
    has_template_spec: bool,
) -> bool {
    match kind {
        "pod" => has_root_spec,
        "cronjob"
        | "daemonset"
        | "deployment"
        | "job"
        | "replicaset"
        | "replicationcontroller"
        | "statefulset" => has_template_spec,
        _ => false,
    }
}

#[derive(Default)]
struct TerraformSecurityGroupIngressCandidate<'a> {
    ingress: bool,
    protocol_all: bool,
    from_port: Option<i64>,
    to_port: Option<i64>,
    public_line_index: Option<usize>,
    public_column: usize,
    public_snippet: &'a str,
}

fn scan_terraform_public_admin_security_group_ingress(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if !terraform_config_path(path) {
        return;
    }
    let lines = source.lines().collect::<Vec<_>>();
    let mut index = 0;
    while index < lines.len() {
        let line = terraform_code_line(lines[index]);
        let Some(resource_type) = terraform_resource_type(line.as_str()) else {
            index += 1;
            continue;
        };
        let start = index;
        let mut end = index;
        let mut depth = terraform_brace_delta(line.as_str());
        while depth > 0 && end + 1 < lines.len() {
            end += 1;
            depth += terraform_brace_delta(terraform_code_line(lines[end]).as_str());
        }
        scan_terraform_security_group_resource(
            root,
            path,
            lines.as_slice(),
            start,
            end,
            resource_type.as_str(),
            findings,
        );
        index = end + 1;
    }
}

fn scan_terraform_security_group_resource(
    root: &Path,
    path: &Path,
    lines: &[&str],
    start: usize,
    end: usize,
    resource_type: &str,
    findings: &mut Vec<StaticFinding>,
) {
    match resource_type {
        "aws_security_group_rule" => {
            let mut candidate = TerraformSecurityGroupIngressCandidate::default();
            for (index, line) in lines.iter().enumerate().take(end + 1).skip(start) {
                terraform_update_security_group_ingress_candidate(&mut candidate, line, index);
            }
            terraform_push_public_admin_ingress(root, path, findings, &candidate);
        }
        "aws_vpc_security_group_ingress_rule" => {
            let mut candidate = TerraformSecurityGroupIngressCandidate {
                ingress: true,
                ..Default::default()
            };
            for (index, line) in lines.iter().enumerate().take(end + 1).skip(start) {
                terraform_update_security_group_ingress_candidate(&mut candidate, line, index);
            }
            terraform_push_public_admin_ingress(root, path, findings, &candidate);
        }
        "aws_security_group" => {
            let mut index = start + 1;
            while index <= end {
                let line = terraform_code_line(lines[index]);
                if terraform_ingress_block_start(line.as_str()) {
                    let block_start = index;
                    let mut block_end = index;
                    let mut depth = terraform_brace_delta(line.as_str());
                    while depth > 0 && block_end < end {
                        block_end += 1;
                        depth +=
                            terraform_brace_delta(terraform_code_line(lines[block_end]).as_str());
                    }
                    let mut candidate = TerraformSecurityGroupIngressCandidate {
                        ingress: true,
                        ..Default::default()
                    };
                    for (candidate_index, line) in lines
                        .iter()
                        .enumerate()
                        .take(block_end + 1)
                        .skip(block_start)
                    {
                        terraform_update_security_group_ingress_candidate(
                            &mut candidate,
                            line,
                            candidate_index,
                        );
                    }
                    terraform_push_public_admin_ingress(root, path, findings, &candidate);
                    index = block_end + 1;
                } else {
                    index += 1;
                }
            }
        }
        _ => {}
    }
}

fn terraform_update_security_group_ingress_candidate<'a>(
    candidate: &mut TerraformSecurityGroupIngressCandidate<'a>,
    line: &'a str,
    line_index: usize,
) {
    let code = terraform_code_line(line);
    let Some((key, value, value_column)) = config_key_value(code.trim_start(), 0) else {
        return;
    };
    let key = key.to_ascii_lowercase();
    let value = value.trim();
    match key.as_str() {
        "type" if trim_config_quotes(value).eq_ignore_ascii_case("ingress") => {
            candidate.ingress = true;
        }
        "protocol" | "ip_protocol" if trim_config_quotes(value) == "-1" => {
            candidate.protocol_all = true;
        }
        "from_port" => {
            candidate.from_port = terraform_i64_literal(value);
        }
        "to_port" => {
            candidate.to_port = terraform_i64_literal(value);
        }
        "cidr_blocks" | "ipv6_cidr_blocks" | "cidr_ipv4" | "cidr_ipv6"
            if terraform_value_has_public_cidr(value) =>
        {
            candidate.public_line_index = Some(line_index);
            candidate.public_column = value_column + 1;
            candidate.public_snippet = line.trim();
        }
        _ => {}
    }
}

fn terraform_push_public_admin_ingress(
    root: &Path,
    path: &Path,
    findings: &mut Vec<StaticFinding>,
    candidate: &TerraformSecurityGroupIngressCandidate<'_>,
) {
    let Some(line_index) = candidate.public_line_index else {
        return;
    };
    if !candidate.ingress || !terraform_candidate_exposes_admin_port(candidate) {
        return;
    }
    push_pattern(
        findings,
        root,
        path,
        line_index,
        candidate.public_column,
        "GF-504",
        "config",
        "terraform-aws-public-admin-ingress",
        "Terraform AWS security group exposes admin ingress to the internet",
        "terraform",
        "An AWS security group ingress rule allows SSH or RDP from 0.0.0.0/0 or ::/0.",
        candidate.public_snippet,
    );
}

fn terraform_candidate_exposes_admin_port(
    candidate: &TerraformSecurityGroupIngressCandidate<'_>,
) -> bool {
    if candidate.protocol_all {
        return true;
    }
    let (Some(from_port), Some(to_port)) = (candidate.from_port, candidate.to_port) else {
        return false;
    };
    let low = from_port.min(to_port);
    let high = from_port.max(to_port);
    (low <= 22 && 22 <= high) || (low <= 3389 && 3389 <= high)
}

fn terraform_config_path(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(|ext| ext.eq_ignore_ascii_case("tf"))
}

fn terraform_resource_type(line: &str) -> Option<String> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with("resource ") {
        return None;
    }
    terraform_quoted_labels(trimmed).into_iter().next()
}

fn terraform_quoted_labels(line: &str) -> Vec<String> {
    let mut labels = Vec::new();
    let mut rest = line;
    while let Some(start) = rest.find('"') {
        let after_start = &rest[start + 1..];
        let Some(end) = after_start.find('"') else {
            break;
        };
        labels.push(after_start[..end].to_owned());
        rest = &after_start[end + 1..];
    }
    labels
}

fn terraform_ingress_block_start(line: &str) -> bool {
    let trimmed = line.trim_start();
    trimmed.starts_with("ingress") && trimmed.contains('{') && !trimmed.contains('=')
}

fn terraform_i64_literal(value: &str) -> Option<i64> {
    trim_config_quotes(value.trim()).parse::<i64>().ok()
}

fn terraform_value_has_public_cidr(value: &str) -> bool {
    value.contains("\"0.0.0.0/0\"")
        || value.contains("'0.0.0.0/0'")
        || value.contains("\"::/0\"")
        || value.contains("'::/0'")
}

fn terraform_code_line(line: &str) -> String {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    for (index, ch) in line.char_indices() {
        match ch {
            '\'' if !in_double && !escaped => in_single = !in_single,
            '"' if !in_single && !escaped => in_double = !in_double,
            '/' if !in_single && !in_double && line[index..].starts_with("//") => {
                return line[..index].to_owned();
            }
            _ => {}
        }
        escaped = ch == '\\' && !escaped;
    }
    line.to_owned()
}

fn terraform_brace_delta(line: &str) -> i32 {
    let without_strings = strip_simple_quoted_strings(line);
    without_strings.chars().fold(0, |depth, ch| match ch {
        '{' => depth + 1,
        '}' => depth - 1,
        _ => depth,
    })
}

struct ConfigLineEntry<'a> {
    path: String,
    value: &'a str,
    value_column: usize,
    snippet: &'a str,
    dotted_key: bool,
}

fn config_line_entry<'a>(
    line: &'a str,
    yaml_stack: &mut Vec<(usize, String)>,
) -> Option<ConfigLineEntry<'a>> {
    let trimmed = line.trim_start();
    let indent = line.len() - trimmed.len();
    if let Some((value, value_column)) = config_sequence_value(trimmed, indent) {
        while yaml_stack
            .last()
            .is_some_and(|(stack_indent, _)| *stack_indent > indent)
        {
            yaml_stack.pop();
        }
        let path = yaml_stack
            .iter()
            .map(|(_, key)| key.as_str())
            .collect::<Vec<_>>()
            .join(".");
        if path.is_empty() {
            return None;
        }
        return Some(ConfigLineEntry {
            path,
            value,
            value_column,
            snippet: line.trim(),
            dotted_key: false,
        });
    }

    let (key, value, value_column) = config_key_value(trimmed, indent)?;

    while yaml_stack
        .last()
        .is_some_and(|(stack_indent, _)| *stack_indent >= indent)
    {
        yaml_stack.pop();
    }

    let key_lower = key.to_ascii_lowercase();
    let dotted_key = key_lower.contains('.');
    let path = if dotted_key {
        key_lower
    } else if value.is_empty() {
        let prefix = yaml_stack
            .iter()
            .map(|(_, key)| key.as_str())
            .collect::<Vec<_>>()
            .join(".");
        let path = if prefix.is_empty() {
            key_lower.clone()
        } else {
            format!("{prefix}.{key_lower}")
        };
        yaml_stack.push((indent, key_lower));
        path
    } else {
        let prefix = yaml_stack
            .iter()
            .map(|(_, key)| key.as_str())
            .collect::<Vec<_>>()
            .join(".");
        if prefix.is_empty() {
            key_lower
        } else {
            format!("{prefix}.{key_lower}")
        }
    };

    Some(ConfigLineEntry {
        path,
        value,
        value_column,
        snippet: line.trim(),
        dotted_key,
    })
}

fn config_sequence_value(line: &str, base_indent: usize) -> Option<(&str, usize)> {
    let rest = line.strip_prefix('-')?;
    let value = rest.trim_start();
    if value.is_empty() || value.contains(':') {
        return None;
    }
    let value_column = base_indent + 1 + rest.len() - value.len();
    Some((value, value_column))
}

fn config_key_value(line: &str, base_indent: usize) -> Option<(&str, &str, usize)> {
    let split = match (line.find('='), line.find(':')) {
        (Some(eq), Some(colon)) => eq.min(colon),
        (Some(eq), None) => eq,
        (None, Some(colon)) => colon,
        (None, None) => return None,
    };
    let key = line[..split]
        .trim()
        .strip_prefix("- ")
        .unwrap_or_else(|| line[..split].trim())
        .trim_start();
    if key.is_empty() {
        return None;
    }
    let raw_value = &line[split + 1..];
    let value = raw_value.trim();
    let value_column = base_indent + split + 1 + raw_value.len() - raw_value.trim_start().len();
    Some((key, value, value_column))
}

fn config_value_is_wildcard(value: &str) -> bool {
    let value = trim_config_quotes(value.trim());
    value
        .split(',')
        .any(|part| trim_config_quotes(part.trim()) == "*")
}

fn spring_actuator_unsanitized_values(path: &str, value: &str) -> bool {
    matches!(
        path,
        "management.endpoint.env.show-values"
            | "management.endpoint.configprops.show-values"
            | "management.endpoint.quartz.show-values"
    ) && trim_config_quotes(value.trim()).eq_ignore_ascii_case("always")
}

fn config_qt_webengine_local_content_file_access(path: &str, value: &str) -> bool {
    let path = path.to_ascii_lowercase();
    matches!(
        path.as_str(),
        "content.local_content_can_access_file_urls"
            | "content.local_content_can_access_file_urls.default"
    ) && config_value_is_true(value)
}

fn scan_qt_webengine_local_file_access_config(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if config_fixture_path(path) {
        return;
    }
    let mut local_file_block_indent: Option<usize> = None;
    for (line_index, line) in source.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.trim().is_empty() {
            continue;
        }
        let indent = line.len() - trimmed.len();
        if local_file_block_indent.is_some_and(|block_indent| indent <= block_indent) {
            local_file_block_indent = None;
        }
        if config_qt_webengine_local_file_access_block_start(trimmed) {
            local_file_block_indent = Some(indent);
            continue;
        }
        if local_file_block_indent.is_some() {
            if let Some(column) = config_qt_webengine_local_file_access_default_true_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    line_index,
                    column + 1,
                    "GF-539",
                    "config",
                    "qt-webengine-local-content-file-access",
                    "Qt WebEngine local content can access local files",
                    "webengine_origin",
                    "Qt WebEngine is configured to default local content file URL access on.",
                    line.trim(),
                );
            }
        }
    }
}

fn config_qt_webengine_local_file_access_block_start(trimmed_line: &str) -> bool {
    trimmed_line.eq_ignore_ascii_case("content.local_content_can_access_file_urls:")
}

fn config_qt_webengine_local_file_access_default_true_column(line: &str) -> Option<usize> {
    let trimmed = line.trim_start();
    let indent = line.len() - trimmed.len();
    let (key, value, value_column) = config_key_value(trimmed, indent)?;
    (key.eq_ignore_ascii_case("default") && config_value_is_true(value)).then_some(value_column)
}

fn github_actions_write_all_token_permissions(
    file_path: &Path,
    config_path: &str,
    value: &str,
) -> bool {
    github_actions_workflow_file(file_path)
        && (config_path == "permissions" || config_path.ends_with(".permissions"))
        && trim_config_scalar(value).eq_ignore_ascii_case("write-all")
}

struct GithubActionsJobPermissionsCandidate<'a> {
    line_index: usize,
    column: usize,
    snippet: &'a str,
    has_permissions: bool,
    has_runs_on: bool,
    has_steps: bool,
    reusable_workflow_call: bool,
}

fn scan_github_actions_missing_job_permissions(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if !github_actions_workflow_file(path) {
        return;
    }
    let lines = source.lines().collect::<Vec<_>>();
    let mut document_start = 0;
    for index in 0..=lines.len() {
        if index == lines.len() || lines[index].trim() == "---" {
            scan_github_actions_missing_job_permissions_document(
                root,
                path,
                lines.as_slice(),
                document_start,
                index,
                findings,
            );
            document_start = index + 1;
        }
    }
}

fn scan_github_actions_missing_job_permissions_document(
    root: &Path,
    path: &Path,
    lines: &[&str],
    start: usize,
    end: usize,
    findings: &mut Vec<StaticFinding>,
) {
    let mut has_workflow_trigger = false;
    let mut has_workflow_permissions = false;
    let mut jobs: BTreeMap<String, GithubActionsJobPermissionsCandidate<'_>> = BTreeMap::new();
    let mut yaml_stack: Vec<(usize, String)> = Vec::new();

    for (line_index, line) in lines.iter().enumerate().take(end).skip(start) {
        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };

        if github_actions_workflow_trigger_path(config.path.as_str()) {
            has_workflow_trigger = true;
        }
        if config.path == "permissions" {
            has_workflow_permissions = true;
        }

        let Some(job_id) = github_actions_job_id_from_path(config.path.as_str()) else {
            continue;
        };
        let is_job_root = config.path == format!("jobs.{job_id}");
        let entry =
            jobs.entry(job_id.to_owned())
                .or_insert_with(|| GithubActionsJobPermissionsCandidate {
                    line_index,
                    column: github_actions_job_location_column(line, job_id, config.value_column),
                    snippet: config.snippet,
                    has_permissions: false,
                    has_runs_on: false,
                    has_steps: false,
                    reusable_workflow_call: false,
                });
        if is_job_root {
            entry.line_index = line_index;
            entry.column = github_actions_job_location_column(line, job_id, config.value_column);
            entry.snippet = config.snippet;
        }
        if github_actions_job_relative_path(config.path.as_str(), job_id, "permissions") {
            entry.has_permissions = true;
        }
        if github_actions_job_relative_path(config.path.as_str(), job_id, "runs-on") {
            entry.has_runs_on = true;
        }
        if github_actions_job_relative_path(config.path.as_str(), job_id, "steps") {
            entry.has_steps = true;
        }
        if github_actions_job_relative_path(config.path.as_str(), job_id, "uses") {
            entry.reusable_workflow_call = true;
        }
    }

    if !has_workflow_trigger || has_workflow_permissions {
        return;
    }
    for job in jobs.values() {
        if job.has_runs_on && job.has_steps && !job.has_permissions && !job.reusable_workflow_call {
            push_pattern(
                findings,
                root,
                path,
                job.line_index,
                job.column,
                "GF-500",
                "config",
                "github-actions-missing-job-permissions",
                "GitHub Actions job inherits default token permissions",
                "github-actions",
                "A GitHub Actions job has local steps but no explicit permissions block.",
                job.snippet,
            );
        }
    }
}

fn github_actions_workflow_trigger_path(config_path: &str) -> bool {
    config_path == "on" || config_path.starts_with("on.")
}

fn github_actions_job_id_from_path(config_path: &str) -> Option<&str> {
    let rest = config_path.strip_prefix("jobs.")?;
    let job_id = rest.split('.').next()?;
    if job_id.is_empty() {
        None
    } else {
        Some(job_id)
    }
}

fn github_actions_job_relative_path(config_path: &str, job_id: &str, field: &str) -> bool {
    let exact = format!("jobs.{job_id}.{field}");
    config_path == exact || config_path.starts_with(&format!("{exact}."))
}

fn github_actions_job_location_column(line: &str, job_id: &str, fallback_column: usize) -> usize {
    line.find(job_id)
        .map(|column| column + 1)
        .unwrap_or(fallback_column + 1)
}

fn github_actions_workflow_file(path: &Path) -> bool {
    let path = path_string(path).to_ascii_lowercase();
    (path.contains("/.github/workflows/") || path.starts_with(".github/workflows/"))
        && (path.ends_with(".yml") || path.ends_with(".yaml"))
}

#[derive(Clone, Copy, Default)]
struct GithubActionsWorkflowContext {
    pull_request: bool,
    pull_request_target: bool,
    issue_comment: bool,
    actions_checkout: bool,
    untrusted_pr_head_checkout: bool,
}

fn github_actions_workflow_context_by_line(
    path: &Path,
    source: &str,
) -> Vec<GithubActionsWorkflowContext> {
    let lines = source.lines().collect::<Vec<_>>();
    if !github_actions_workflow_file(path) {
        return vec![GithubActionsWorkflowContext::default(); lines.len()];
    }
    let mut contexts = vec![GithubActionsWorkflowContext::default(); lines.len()];
    let mut start = 0;
    for index in 0..lines.len() {
        if lines[index].trim() == "---" {
            fill_github_actions_context(lines.as_slice(), start, index, contexts.as_mut_slice());
            start = index + 1;
        }
    }
    fill_github_actions_context(
        lines.as_slice(),
        start,
        lines.len(),
        contexts.as_mut_slice(),
    );
    contexts
}

fn github_actions_untrusted_pr_head_checkout_jobs(path: &Path, source: &str) -> BTreeSet<String> {
    if !github_actions_workflow_file(path) {
        return BTreeSet::new();
    }
    let mut jobs = BTreeSet::new();
    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    for line in source.lines() {
        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if github_actions_pr_head_checkout_ref(config.path.as_str(), config.value)
            || github_actions_issue_comment_pr_head_checkout_ref(config.path.as_str(), config.value)
        {
            if let Some(job_id) = github_actions_job_id(config.path.as_str()) {
                jobs.insert(job_id.to_owned());
            }
        }
    }
    jobs
}

fn github_actions_job_id(config_path: &str) -> Option<&str> {
    let rest = config_path.strip_prefix("jobs.")?;
    let (job_id, _) = rest.split_once('.')?;
    if job_id.is_empty() {
        None
    } else {
        Some(job_id)
    }
}

fn fill_github_actions_context(
    lines: &[&str],
    start: usize,
    end: usize,
    contexts: &mut [GithubActionsWorkflowContext],
) {
    let mut context = GithubActionsWorkflowContext::default();
    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    for line in &lines[start..end] {
        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if github_actions_pull_request_trigger(config.path.as_str(), config.value) {
            context.pull_request = true;
        }
        if github_actions_pull_request_target_trigger(config.path.as_str(), config.value) {
            context.pull_request_target = true;
        }
        if github_actions_issue_comment_trigger(config.path.as_str(), config.value) {
            context.issue_comment = true;
        }
        if trim_config_scalar(config.value)
            .to_ascii_lowercase()
            .starts_with("actions/checkout@")
        {
            context.actions_checkout = true;
        }
        if github_actions_pr_head_checkout_ref(config.path.as_str(), config.value)
            || github_actions_issue_comment_pr_head_checkout_ref(config.path.as_str(), config.value)
        {
            context.untrusted_pr_head_checkout = true;
        }
    }
    for item in &mut contexts[start..end] {
        *item = context;
    }
}

fn github_actions_pull_request_target_trigger(config_path: &str, value: &str) -> bool {
    config_path == "on.pull_request_target"
        || config_path.ends_with(".on.pull_request_target")
        || config_path == "on" && config_sequence_contains(value, "pull_request_target")
}

fn github_actions_pull_request_trigger(config_path: &str, value: &str) -> bool {
    config_path == "on.pull_request"
        || config_path.ends_with(".on.pull_request")
        || config_path == "on" && config_sequence_contains(value, "pull_request")
}

fn github_actions_issue_comment_trigger(config_path: &str, value: &str) -> bool {
    config_path == "on.issue_comment"
        || config_path.ends_with(".on.issue_comment")
        || config_path == "on" && config_sequence_contains(value, "issue_comment")
}

fn github_actions_pr_head_checkout_ref(config_path: &str, value: &str) -> bool {
    (config_path == "ref"
        || config_path.ends_with(".ref")
        || config_path == "repository"
        || config_path.ends_with(".repository"))
        && github_actions_pr_head_expression(value)
}

fn github_actions_pr_head_expression(value: &str) -> bool {
    let value = trim_config_scalar(value).to_ascii_lowercase();
    value.contains("github.event.pull_request.head")
        || value.contains("github.head_ref")
        || value.contains("github.event.number")
}

fn github_actions_issue_comment_pr_head_checkout_ref(config_path: &str, value: &str) -> bool {
    if !(config_path == "ref" || config_path.ends_with(".ref")) {
        return false;
    }
    let value = trim_config_scalar(value).to_ascii_lowercase();
    value.contains("github.event.issue.number")
        && (value.contains("refs/pull")
            || value.contains("/head")
            || value.contains("pull/")
            || value.contains("format("))
}

fn github_actions_cache_write_action(config_path: &str, value: &str) -> bool {
    if !(config_path == "uses" || config_path.ends_with(".uses")) {
        return false;
    }
    let value = trim_config_scalar(value).to_ascii_lowercase();
    value.starts_with("actions/cache@") || value.starts_with("actions/cache/save@")
}

fn github_actions_untrusted_pr_context_for_self_hosted_runner(
    config_path: &str,
    context: GithubActionsWorkflowContext,
    untrusted_checkout_jobs: &BTreeSet<String>,
) -> bool {
    if context.pull_request {
        return true;
    }
    if !context.pull_request_target && !context.issue_comment {
        return false;
    }
    github_actions_job_id(config_path)
        .is_some_and(|job_id| untrusted_checkout_jobs.contains(job_id))
}

fn github_actions_self_hosted_runner(config_path: &str, value: &str) -> bool {
    (config_path == "runs-on" || config_path.ends_with(".runs-on"))
        && config_sequence_contains(value, "self-hosted")
}

fn github_actions_pr_target_oidc_token_permission(config_path: &str, value: &str) -> bool {
    (config_path == "permissions.id-token" || config_path.ends_with(".permissions.id-token"))
        && trim_config_scalar(value).eq_ignore_ascii_case("write")
}

fn github_actions_pr_target_contents_write_permission(config_path: &str, value: &str) -> bool {
    (config_path == "permissions.contents" || config_path.ends_with(".permissions.contents"))
        && trim_config_scalar(value).eq_ignore_ascii_case("write")
}

struct GithubActionsArtifactDownloadCandidate<'a> {
    line_index: usize,
    column: usize,
    step_indent: usize,
    snippet: &'a str,
    has_path: bool,
}

fn scan_github_actions_workflow_run_artifact_download(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if !github_actions_workflow_file(path) {
        return;
    }
    let lines = source.lines().collect::<Vec<_>>();
    let mut document_start = 0;
    for index in 0..=lines.len() {
        if index == lines.len() || lines[index].trim() == "---" {
            scan_github_actions_workflow_run_artifact_download_document(
                root,
                path,
                lines.as_slice(),
                document_start,
                index,
                findings,
            );
            document_start = index + 1;
        }
    }
}

fn scan_github_actions_workflow_run_artifact_download_document(
    root: &Path,
    path: &Path,
    lines: &[&str],
    start: usize,
    end: usize,
    findings: &mut Vec<StaticFinding>,
) {
    if !github_actions_document_has_workflow_run(lines, start, end) {
        return;
    }

    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    let mut candidate: Option<GithubActionsArtifactDownloadCandidate<'_>> = None;
    for (line_index, line) in lines.iter().enumerate().take(end).skip(start) {
        let trimmed = line.trim_start();
        let indent = line.len() - trimmed.len();
        if candidate.as_ref().is_some_and(|item| {
            indent <= item.step_indent && trimmed.starts_with("- ") && !trimmed.is_empty()
        }) {
            push_github_actions_artifact_download_candidate(root, path, findings, candidate.take());
        }

        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if let Some(item) = candidate.as_mut() {
            if github_actions_artifact_download_path_input(config.path.as_str(), config.value) {
                item.has_path = true;
            }
        }
        if github_actions_artifact_download_action(config.path.as_str(), config.value) {
            push_github_actions_artifact_download_candidate(root, path, findings, candidate.take());
            candidate = Some(GithubActionsArtifactDownloadCandidate {
                line_index,
                column: config.value_column + 1,
                step_indent: indent,
                snippet: config.snippet,
                has_path: false,
            });
        }
    }
    push_github_actions_artifact_download_candidate(root, path, findings, candidate);
}

fn github_actions_document_has_workflow_run(lines: &[&str], start: usize, end: usize) -> bool {
    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    for line in &lines[start..end] {
        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if github_actions_workflow_run_trigger(config.path.as_str(), config.value) {
            return true;
        }
    }
    false
}

fn github_actions_workflow_run_trigger(config_path: &str, value: &str) -> bool {
    config_path == "on.workflow_run"
        || config_path.ends_with(".on.workflow_run")
        || config_path == "on" && config_sequence_contains(value, "workflow_run")
}

fn github_actions_artifact_download_action(config_path: &str, value: &str) -> bool {
    if !(config_path == "uses" || config_path.ends_with(".uses")) {
        return false;
    }
    let value = trim_config_scalar(value).to_ascii_lowercase();
    value.starts_with("actions/download-artifact@")
        || value.starts_with("dawidd6/action-download-artifact@")
}

fn github_actions_artifact_download_path_input(config_path: &str, value: &str) -> bool {
    (config_path == "with.path" || config_path.ends_with(".with.path"))
        && !trim_config_scalar(value).is_empty()
}

fn push_github_actions_artifact_download_candidate(
    root: &Path,
    path: &Path,
    findings: &mut Vec<StaticFinding>,
    candidate: Option<GithubActionsArtifactDownloadCandidate<'_>>,
) {
    let Some(candidate) = candidate else {
        return;
    };
    if candidate.has_path {
        return;
    }
    push_pattern(
        findings,
        root,
        path,
        candidate.line_index,
        candidate.column,
        "GF-492",
        "config",
        "github-actions-workflow-run-artifact-download-workspace",
        "GitHub Actions workflow_run downloads artifacts into the workspace",
        "github-actions",
        "A workflow_run workflow downloads artifacts without an isolated path.",
        candidate.snippet,
    );
}

struct GithubActionsHiddenArtifactUploadCandidate<'a> {
    line_index: usize,
    column: usize,
    step_indent: usize,
    snippet: &'a str,
    include_hidden_files: bool,
    broad_path: bool,
}

fn scan_github_actions_hidden_file_artifact_upload(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if !github_actions_workflow_file(path) {
        return;
    }

    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    let mut candidate: Option<GithubActionsHiddenArtifactUploadCandidate<'_>> = None;
    let mut path_block_indent: Option<usize> = None;
    for (line_index, line) in source.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.is_empty() {
            continue;
        }
        let indent = line.len() - trimmed.len();

        if candidate.as_ref().is_some_and(|item| {
            indent <= item.step_indent && trimmed.starts_with("- ") && !trimmed.is_empty()
        }) {
            push_github_actions_hidden_artifact_upload_candidate(
                root,
                path,
                findings,
                candidate.take(),
            );
            path_block_indent = None;
        }

        if let (Some(item), Some(block_indent)) = (candidate.as_mut(), path_block_indent) {
            if indent > block_indent {
                if github_actions_artifact_upload_broad_workspace_path(trimmed) {
                    item.broad_path = true;
                }
                continue;
            }
            path_block_indent = None;
        }

        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if let Some(item) = candidate.as_mut() {
            if github_actions_artifact_upload_include_hidden_files_input(
                config.path.as_str(),
                config.value,
            ) {
                item.include_hidden_files = true;
            }
            if github_actions_artifact_upload_path_input(config.path.as_str()) {
                let value = trim_config_scalar(config.value);
                if matches!(value, "|" | ">" | "|-" | ">-" | "|+" | ">+") {
                    path_block_indent = Some(indent);
                } else if github_actions_artifact_upload_broad_workspace_path(value) {
                    item.broad_path = true;
                }
            }
        }
        if github_actions_artifact_upload_action(config.path.as_str(), config.value) {
            push_github_actions_hidden_artifact_upload_candidate(
                root,
                path,
                findings,
                candidate.take(),
            );
            candidate = Some(GithubActionsHiddenArtifactUploadCandidate {
                line_index,
                column: config.value_column + 1,
                step_indent: indent,
                snippet: config.snippet,
                include_hidden_files: false,
                broad_path: false,
            });
            path_block_indent = None;
        }
    }
    push_github_actions_hidden_artifact_upload_candidate(root, path, findings, candidate);
}

fn github_actions_artifact_upload_action(config_path: &str, value: &str) -> bool {
    if !(config_path == "uses" || config_path.ends_with(".uses")) {
        return false;
    }
    trim_config_scalar(value)
        .to_ascii_lowercase()
        .starts_with("actions/upload-artifact@")
}

fn github_actions_artifact_upload_path_input(config_path: &str) -> bool {
    config_path == "with.path" || config_path.ends_with(".with.path")
}

fn github_actions_artifact_upload_include_hidden_files_input(
    config_path: &str,
    value: &str,
) -> bool {
    (config_path == "with.include-hidden-files"
        || config_path.ends_with(".with.include-hidden-files"))
        && config_value_is_true(value)
}

fn github_actions_artifact_upload_broad_workspace_path(value: &str) -> bool {
    let path = trim_config_scalar(value);
    if path.is_empty() || path.starts_with('!') {
        return false;
    }

    let normalized = path
        .replace('\\', "/")
        .to_ascii_lowercase()
        .chars()
        .filter(|ch| !ch.is_whitespace())
        .collect::<String>();
    let normalized = normalized.as_str();
    if matches!(
        normalized,
        "." | "./" | "./." | "*" | "**" | "**/*" | "./*" | "./**" | "./**/*"
    ) {
        return true;
    }

    [
        "${{github.workspace}}",
        "$github_workspace",
        "${github_workspace}",
    ]
    .iter()
    .any(|root| {
        normalized == *root
            || normalized
                .strip_prefix(root)
                .is_some_and(|rest| matches!(rest, "/" | "/." | "/*" | "/**" | "/**/*"))
    })
}

fn push_github_actions_hidden_artifact_upload_candidate(
    root: &Path,
    path: &Path,
    findings: &mut Vec<StaticFinding>,
    candidate: Option<GithubActionsHiddenArtifactUploadCandidate<'_>>,
) {
    let Some(candidate) = candidate else {
        return;
    };
    if !candidate.include_hidden_files || !candidate.broad_path {
        return;
    }
    push_pattern(
        findings,
        root,
        path,
        candidate.line_index,
        candidate.column,
        "GF-498",
        "config",
        "github-actions-hidden-file-artifact-upload",
        "GitHub Actions artifact upload includes hidden workspace files",
        "github-actions",
        "A GitHub Actions artifact upload includes hidden files from the workspace root.",
        candidate.snippet,
    );
}

#[derive(Clone, Copy)]
struct GithubActionsGithubScriptStep {
    step_indent: usize,
}

fn scan_github_actions_github_script_injection(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    if !github_actions_workflow_file(path) {
        return;
    }

    let mut yaml_stack: Vec<(usize, String)> = Vec::new();
    let mut github_script_step: Option<GithubActionsGithubScriptStep> = None;
    let mut script_block_indent: Option<usize> = None;
    for (line_index, line) in source.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.is_empty() {
            continue;
        }
        let indent = line.len() - trimmed.len();

        if github_script_step.as_ref().is_some_and(|step| {
            indent <= step.step_indent && trimmed.starts_with("- ") && !trimmed.is_empty()
        }) {
            github_script_step = None;
            script_block_indent = None;
        }

        if let (Some(_), Some(block_indent)) = (github_script_step, script_block_indent) {
            if indent > block_indent {
                if let Some(column) = github_actions_untrusted_context_expression_column(line) {
                    push_github_actions_github_script_injection(
                        findings,
                        root,
                        path,
                        line_index,
                        column + 1,
                        line.trim(),
                    );
                }
                continue;
            }
            script_block_indent = None;
        }

        let Some(config) = config_line_entry(line, &mut yaml_stack) else {
            continue;
        };
        if github_actions_github_script_action(config.path.as_str(), config.value) {
            github_script_step = Some(GithubActionsGithubScriptStep {
                step_indent: indent,
            });
            script_block_indent = None;
            continue;
        }
        if github_script_step.is_none() || !github_actions_github_script_input(config.path.as_str())
        {
            continue;
        }

        let scalar = trim_config_scalar(config.value);
        if matches!(scalar, "|" | ">" | "|-" | ">-" | "|+" | ">+") {
            script_block_indent = Some(indent);
            continue;
        }
        if let Some(expression_column) = github_actions_untrusted_context_expression_column(scalar)
        {
            push_github_actions_github_script_injection(
                findings,
                root,
                path,
                line_index,
                config.value_column + expression_column + 1,
                config.snippet,
            );
        }
    }
}

fn github_actions_github_script_action(config_path: &str, value: &str) -> bool {
    if !(config_path == "uses" || config_path.ends_with(".uses")) {
        return false;
    }
    let value = trim_config_scalar(value).to_ascii_lowercase();
    let action = value.split('@').next().unwrap_or(value.as_str()).trim();
    action == "actions/github-script"
}

fn github_actions_github_script_input(config_path: &str) -> bool {
    config_path == "with.script" || config_path.ends_with(".with.script")
}

fn push_github_actions_github_script_injection(
    findings: &mut Vec<StaticFinding>,
    root: &Path,
    path: &Path,
    line_index: usize,
    column: usize,
    snippet: &str,
) {
    push_pattern(
        findings,
        root,
        path,
        line_index,
        column,
        "GF-499",
        "config",
        "github-actions-github-script-injection",
        "GitHub Actions github-script interpolates untrusted event context",
        "github-actions",
        "An actions/github-script step interpolates attacker-controlled event context directly into JavaScript.",
        snippet,
    );
}

