fn github_actions_ai_agent_action(config_path: &str, value: &str) -> bool {
    if !(config_path == "uses" || config_path.ends_with(".uses")) {
        return false;
    }
    let value = trim_config_scalar(value).to_ascii_lowercase();
    let action = value.split('@').next().unwrap_or(value.as_str()).trim();
    const KNOWN_AI_ACTIONS: &[&str] = &[
        "anthropics/claude-code-action",
        "anthropics/claude-code-base-action",
        "openai/codex",
        "openai/codex-action",
        "google-github-actions/run-gemini-cli",
        "google-gemini/gemini-cli-action",
        "qodo-ai/pr-agent",
        "coderabbitai/ai-pr-reviewer",
        "coderabbitai/coderabbit-action",
        "sweepai/sweep",
        "aider-ai/aider-action",
        "all-hands-ai/openhands-resolver",
        "openhands/openhands-resolver",
        "github/ai-inference",
    ];
    KNOWN_AI_ACTIONS
        .iter()
        .any(|known| action.starts_with(known))
        || action.contains("claude")
        || action.contains("codex")
        || action.contains("gemini")
        || action.contains("pr-agent")
        || action.contains("ai-pr-reviewer")
        || action.contains("coderabbit")
        || action.contains("openhands")
        || action.contains("sweepai")
        || action.contains("aider")
}

fn github_actions_ai_agent_input_path(config_path: &str) -> bool {
    config_path.contains(".with.") || config_path.contains(".env.")
}

