fn docker_compose_host_device_mapping(value: &str) -> bool {
    let scalar = trim_config_scalar(value);
    if scalar.contains('$') || scalar.contains('{') || scalar.contains('}') {
        return false;
    }
    let host_path = scalar.split_once(':').map_or(scalar, |(source, _)| source);
    let host_path = trim_config_scalar(host_path);
    host_path == "/dev" || host_path.starts_with("/dev/")
}

