fn docker_compose_privileged_service(path: &str, value: &str) -> bool {
    docker_compose_service_field_path(path, "privileged") && config_value_is_true(value)
}

fn docker_compose_service_field_path(path: &str, field: &str) -> bool {
    let mut segments = path.split('.');
    matches!(segments.next(), Some("services"))
        && segments.next().is_some()
        && matches!(segments.next(), Some(segment) if segment == field)
        && segments.next().is_none()
}

