fn javascript_line_contains_cors_config(line: &str) -> bool {
    javascript_cors_config_column(line).is_some()
        || javascript_cors_header_allows_any_origin(line)
        || javascript_cors_credentials_header_enabled(line)
}

fn javascript_cors_allows_any_origin(compact: &str) -> bool {
    [
        "origin:'*'",
        "origin:\"*\"",
        "origin:true",
        "origin:/.*/",
        "origin:/^.*$/",
        "origin:/./",
        "originpatterns:'*'",
        "originpatterns:\"*\"",
    ]
    .iter()
    .any(|needle| compact.contains(needle))
        || compact.contains("access-control-allow-origin")
            && (compact.contains("'*'")
                || compact.contains("\"*\"")
                || compact.contains("req.headers.origin")
                || compact.contains("request.headers.origin")
                || compact.contains("ctx.headers.origin")
                || compact.contains("ctx.request.headers.origin"))
}

fn javascript_cors_credentials_enabled(compact: &str) -> bool {
    compact.contains("credentials:true")
        || compact.contains("access-control-allow-credentials")
            && (compact.contains("'true'")
                || compact.contains("\"true\"")
                || compact.contains(",true"))
}

fn push_javascript_cors_header_pair_finding(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    let lines: Vec<&str> = source.lines().collect();
    for (i, line) in lines.iter().enumerate() {
        if !javascript_cors_credentials_header_enabled(line) {
            continue;
        }
        if javascript_nearest_cors_origin_header_allows_any(&lines, i) {
            let lower = line.to_ascii_lowercase();
            let col = lower
                .find("access-control-allow-credentials")
                .or_else(|| {
                    first_code_match(line, &["setHeader(", ".setHeader(", ".header(", ".set("])
                })
                .unwrap_or(0);
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-439",
                "javascript",
                "permissive-cors-with-credentials",
                "CORS allows any origin with credentials",
                "cors",
                "JavaScript response headers allow any or reflected origin with credentials.",
                line.trim(),
            );
        }
    }
}

fn javascript_nearest_cors_origin_header_allows_any(
    lines: &[&str],
    credentials_line: usize,
) -> bool {
    let start = credentials_line.saturating_sub(8);
    for line in lines[start..=credentials_line].iter().rev() {
        if javascript_cors_header_mentions_origin(line) {
            return javascript_cors_header_allows_any_origin(line);
        }
    }
    let end = (credentials_line + 9).min(lines.len());
    for line in &lines[credentials_line + 1..end] {
        if javascript_cors_header_mentions_origin(line) {
            return javascript_cors_header_allows_any_origin(line);
        }
    }
    false
}

fn javascript_cors_header_mentions_origin(line: &str) -> bool {
    let compact = compact_ascii_lower(line);
    first_code_match(line, &["setHeader(", ".setHeader(", ".header(", ".set("]).is_some()
        && compact.contains("access-control-allow-origin")
}

fn javascript_cors_header_allows_any_origin(line: &str) -> bool {
    let compact = compact_ascii_lower(line);
    javascript_cors_header_mentions_origin(line)
        && (compact.contains("'*'")
            || compact.contains("\"*\"")
            || compact.contains("req.headers.origin")
            || compact.contains("request.headers.origin")
            || compact.contains("ctx.headers.origin")
            || compact.contains("ctx.request.headers.origin"))
}

fn javascript_cors_credentials_header_enabled(line: &str) -> bool {
    let compact = compact_ascii_lower(line);
    first_code_match(line, &["setHeader(", ".setHeader(", ".header(", ".set("]).is_some()
        && compact.contains("access-control-allow-credentials")
        && (compact.contains("'true'") || compact.contains("\"true\"") || compact.contains(",true"))
}

fn call_argument_has_wildcard(compact: &str, call: &str) -> bool {
    compact.find(call).is_some_and(|at| {
        let args = &compact[at + call.len()..];
        let args = args.split(')').next().unwrap_or(args);
        args.contains("\"*\"") || args.contains("'*'")
    })
}

#[derive(Clone)]
struct PythonCorsSetting {
    enabled: bool,
    line_index: usize,
    column: usize,
    snippet: String,
}

fn push_python_cors_settings_finding(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    let mut any_origin: Option<PythonCorsSetting> = None;
    let mut credentials: Option<PythonCorsSetting> = None;
    for (i, line) in source.lines().enumerate() {
        let Some((name, enabled, column)) = python_cors_bool_setting(line) else {
            continue;
        };
        let setting = PythonCorsSetting {
            enabled,
            line_index: i,
            column,
            snippet: line.trim().to_owned(),
        };
        match name {
            "CORS_ALLOW_ALL_ORIGINS" | "CORS_ORIGIN_ALLOW_ALL" => any_origin = Some(setting),
            "CORS_ALLOW_CREDENTIALS" => credentials = Some(setting),
            _ => {}
        }
    }

    let (Some(any_origin), Some(credentials)) = (any_origin, credentials) else {
        return;
    };
    if !any_origin.enabled || !credentials.enabled {
        return;
    }

    push_pattern(
        findings,
        root,
        path,
        credentials.line_index,
        credentials.column,
        "GF-439",
        "python",
        "permissive-cors-with-credentials",
        "CORS allows any origin with credentials",
        "cors",
        "Django CORS settings allow all origins and credentialed cross-origin requests.",
        &credentials.snippet,
    );
}

fn python_cors_bool_setting(line: &str) -> Option<(&'static str, bool, usize)> {
    let trimmed = line.trim_start();
    let column = line.len() - trimmed.len() + 1;
    for name in [
        "CORS_ALLOW_ALL_ORIGINS",
        "CORS_ORIGIN_ALLOW_ALL",
        "CORS_ALLOW_CREDENTIALS",
    ] {
        let Some(rest) = trimmed.strip_prefix(name) else {
            continue;
        };
        let Some(value) = rest.trim_start().strip_prefix('=') else {
            continue;
        };
        let value = value.trim_start();
        if value.starts_with("True") {
            return Some((name, true, column));
        }
        if value.starts_with("False") {
            return Some((name, false, column));
        }
    }
    None
}

/// GF-546 (CWE-703): a Python `except` clause whose ENTIRE body is a single
/// `pass` or `...` statement silently swallows the caught exception — the Python
/// mirror of the Ada `when others => null` rule (GF-402). Precise by construction:
/// we require the `except` header line to end in `:` (no inline suite), then the
/// next non-blank line to be exactly `pass`/`...` at a deeper indent, and the line
/// after that to NOT be part of the same suite (so `except: pass\n log()` — where
/// the handler does more — never fires). A one-line `except X: pass` is also
/// flagged. Comments are already stripped upstream.
fn push_python_broad_except_findings(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    let lines: Vec<&str> = source.lines().collect();
    for (i, raw) in lines.iter().enumerate() {
        let trimmed = raw.trim_start();
        if !trimmed.starts_with("except") {
            continue;
        }
        // Must be an `except` clause: `except`, `except X`, `except X as e`,
        // `except (A, B):` — the keyword followed by a boundary, not `excepting`.
        let after = &trimmed["except".len()..];
        if !after.is_empty() && !after.starts_with(':') && !after.starts_with(char::is_whitespace) {
            continue;
        }
        let except_indent = raw.len() - trimmed.len();
        // Inline suite: `except ...: pass` / `except ...: ...`
        if let Some(colon) = trimmed.find(':') {
            let suite = trimmed[colon + 1..].trim();
            if !suite.is_empty() {
                if suite == "pass" || suite == "..." {
                    let column = except_indent + 1;
                    push_broad_except(root, path, findings, i, column, raw.trim());
                }
                // Any other inline body (`except X: log()`) is not a swallow.
                continue;
            }
        } else {
            // No colon on the header line (continuation across lines) — skip; too
            // ambiguous to classify precisely.
            continue;
        }
        // Block form: find the next non-blank line — it is the first body stmt.
        let Some((body_idx, body_raw)) = lines
            .iter()
            .enumerate()
            .skip(i + 1)
            .find(|(_, l)| !l.trim().is_empty())
            .map(|(idx, l)| (idx, *l))
        else {
            continue;
        };
        let body_trimmed = body_raw.trim_start();
        let body_indent = body_raw.len() - body_trimmed.len();
        // The body must be indented deeper than the `except` header, otherwise the
        // suite is empty (syntactically invalid, but be safe).
        if body_indent <= except_indent {
            continue;
        }
        let body_stmt = body_trimmed.trim_end();
        if body_stmt != "pass" && body_stmt != "..." {
            continue;
        }
        // The `pass`/`...` must be the SOLE statement of the suite: the next
        // non-blank line must dedent out of the body (indent <= except_indent, or
        // == except_indent for a sibling clause), i.e. the handler does nothing
        // else. If a deeper/equal-body-indent statement follows, the handler has
        // real logic and this is not a silent swallow.
        let next_stmt = lines
            .iter()
            .enumerate()
            .skip(body_idx + 1)
            .find(|(_, l)| !l.trim().is_empty());
        if let Some((_, next_raw)) = next_stmt {
            let next_trimmed = next_raw.trim_start();
            let next_indent = next_raw.len() - next_trimmed.len();
            if next_indent >= body_indent {
                continue;
            }
        }
        let column = body_indent + 1;
        push_broad_except(root, path, findings, body_idx, column, body_raw.trim());
    }
}

fn push_broad_except(
    root: &Path,
    path: &Path,
    findings: &mut Vec<StaticFinding>,
    line_index: usize,
    column: usize,
    snippet: &str,
) {
    findings.push(static_finding(
        root,
        path,
        line_index,
        column,
        "GF-546",
        "python",
        "python-broad-exception-suppression",
        "Python except handler silently swallows the exception",
        StaticEvidence {
            kind: "handler".to_owned(),
            detail: "An except handler whose only body is pass/... discards the caught exception."
                .to_owned(),
            snippet: snippet.to_owned(),
        },
    ));
}

fn scan_python(root: &Path, path: &Path, source: &str, findings: &mut Vec<StaticFinding>) {
    scan_obfuscated_dynamic_exec(root, path, source, "python", findings);
    push_python_broad_except_findings(root, path, source, findings);
    push_python_cors_settings_finding(root, path, source, findings);
    push_python_weak_password_hasher_findings(root, path, source, findings);
    let suppress_python_clickjacking = python_framework_fixture_path(path);
    let suppress_python_csrf_framework_forms = python_framework_fixture_path(path);
    let suppress_python_nosniff_setting = python_framework_fixture_path(path);
    let suppress_python_referrer_policy_setting = python_framework_fixture_path(path);
    let suppress_python_hsts_setting =
        python_framework_fixture_path(path) || python_django_global_settings_path(path);
    let suppress_python_ssl_redirect_setting =
        python_framework_fixture_path(path) || python_django_global_settings_path(path);
    let suppress_python_csrf_cookie_secure =
        python_framework_fixture_path(path) || python_django_global_settings_path(path);
    let suppress_python_qt_webengine_sandbox = python_framework_fixture_path(path);
    let suppress_python_qt_webengine_local_file_access = python_framework_fixture_path(path);
    let suppress_generic_hardcoded_secret = generic_hardcoded_secret_fixture_path(path);
    let jwt_decode_aliases = python_jwt_decode_aliases(source);
    let tarfile_module_aliases = python_tarfile_module_aliases(source);
    let tarfile_open_aliases = python_tarfile_open_aliases(source, &tarfile_module_aliases);
    let tarfile_handle_aliases =
        python_tarfile_handle_aliases(source, &tarfile_module_aliases, &tarfile_open_aliases);
    let tarfile_safe_filter_handles = python_tarfile_safe_filter_handles(source);
    let tarfile_validated_member_aliases = python_tarfile_validated_member_aliases(source);
    let template_render_string_aliases = python_template_render_string_aliases(source);
    let jinja_template_aliases = python_jinja_template_aliases(source);
    let jinja_environment_aliases = python_jinja_environment_aliases(source);
    let jinja_environment_handle_aliases =
        python_jinja_environment_handle_aliases(source, &jinja_environment_aliases);
    let untrusted_template_aliases = python_untrusted_template_aliases(source);
    let session_cookie_secure_enabled = python_session_cookie_secure_enabled(source);
    let ssl_redirect_default_false_env_names =
        python_bool_env_schema_default_false_names(source, "ssl_redirect");
    if !suppress_python_qt_webengine_local_file_access {
        push_python_qt_webengine_local_file_access_findings(root, path, source, findings);
    }
    for (i, line) in source.lines().enumerate() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        push_insecure_tls(findings, root, path, i, line, "python");
        push_insecure_transport(findings, root, path, i, line, "python");
        push_insecure_random(findings, root, path, i, line, "python");
        for cookie in insecure_sensitive_cookie_flag_matches(line, "python") {
            push_pattern(
                findings,
                root,
                path,
                i,
                cookie.column,
                cookie.rule_id,
                "python",
                cookie.slug,
                cookie.message,
                "cookie",
                cookie.detail,
                t,
            );
        }
        for cookie in
            python_framework_session_cookie_flag_matches(line, session_cookie_secure_enabled)
        {
            push_pattern(
                findings,
                root,
                path,
                i,
                cookie.column,
                cookie.rule_id,
                "python",
                cookie.slug,
                cookie.message,
                "cookie",
                cookie.detail,
                t,
            );
        }
        if !suppress_python_csrf_cookie_secure {
            if let Some(col) = python_csrf_cookie_secure_disabled_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-443",
                    "python",
                    "sensitive-cookie-secure-disabled",
                    "Sensitive cookie has Secure disabled",
                    "cookie",
                    "Django CSRF cookie configuration explicitly disables Secure.",
                    t,
                );
            }
        }
        if let Some(col) = python_framework_request_size_limit_disabled_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-436",
                "python",
                "uncontrolled-allocation-size",
                "Python request size limit is disabled",
                "request-size",
                "Flask or Django request parsing limits are explicitly disabled, allowing large request bodies or multipart forms to exhaust memory or worker resources.",
                t,
            );
        }
        // CWE-942: any-origin CORS combined with credentials/cookies.
        if let Some(col) = permissive_cors_with_credentials_column(line, "python") {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-439",
                "python",
                "permissive-cors-with-credentials",
                "CORS allows any origin with credentials",
                "cors",
                "Wildcard/regex CORS origins are combined with credentialed requests.",
                t,
            );
        }
        // CWE-352: explicit CSRF protection bypass/disable.
        if let Some(col) =
            python_csrf_protection_disabled_column(line, !suppress_python_csrf_framework_forms)
        {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-446",
                "python",
                "csrf-protection-disabled",
                "CSRF protection is disabled",
                "csrf",
                "Framework CSRF protection is explicitly exempted or disabled.",
                t,
            );
        }
        // CWE-1021: explicit anti-clickjacking frame-protection bypass.
        if !suppress_python_clickjacking {
            if let Some(col) = clickjacking_protection_disabled_column(line, "python") {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-447",
                    "python",
                    "clickjacking-protection-disabled",
                    "Clickjacking protection is disabled",
                    "clickjacking",
                    "Django clickjacking protection is explicitly exempted for this view.",
                    t,
                );
            }
        }
        // CWE-347: JWT signature verification explicitly disabled.
        if let Some(col) = jwt_signature_verification_disabled_column(line, "python") {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-448",
                "python",
                "jwt-signature-verification-disabled",
                "JWT signature verification is disabled",
                "jwt",
                "PyJWT is configured to skip signature verification or accept unsigned JWTs.",
                t,
            );
        }
        // CWE-613: JWT expiration validation explicitly disabled.
        if let Some(col) =
            python_jwt_expiration_verification_disabled_column(line, &jwt_decode_aliases)
        {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-518",
                "python",
                "jwt-expiration-verification-disabled",
                "JWT expiration verification is disabled",
                "jwt",
                "PyJWT is configured to skip exp claim validation, allowing expired tokens to remain valid.",
                t,
            );
        }
        // CWE-489: active web debug mode left enabled.
        if let Some(col) = python_web_debug_enabled_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-449",
                "python",
                "python-web-debug-enabled",
                "Python web debug mode is enabled",
                "debug",
                "Flask/Django debug mode is explicitly enabled.",
                t,
            );
        }
        if !suppress_python_ssl_redirect_setting {
            if let Some(col) = python_django_ssl_redirect_disabled_column(
                line,
                &ssl_redirect_default_false_env_names,
            ) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-541",
                    "python",
                    "django-ssl-redirect-disabled",
                    "Django HTTPS redirect is disabled",
                    "transport",
                    "Django SECURE_SSL_REDIRECT is explicitly false or defaults false, so SecurityMiddleware will not redirect HTTP requests to HTTPS.",
                    t,
                );
            }
        }
        if !suppress_python_qt_webengine_sandbox {
            if let Some(col) = python_qt_webengine_sandbox_disabled_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-530",
                    "python",
                    "qt-webengine-sandbox-disabled",
                    "Qt WebEngine sandboxing is disabled",
                    "sandbox",
                    "Qt WebEngine is configured to disable Chromium renderer or plugin sandboxing.",
                    t,
                );
            }
        }
        // CWE-346: Host header allowlist disabled with wildcard/None hosts.
        if let Some(col) = python_host_allowlist_disabled_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-450",
                "python",
                "python-host-allowlist-disabled",
                "Python host header allowlist allows any host",
                "host_header",
                "Django ALLOWED_HOSTS or Flask TRUSTED_HOSTS disables host header validation.",
                t,
            );
        }
        // CWE-346: proxy-origin HTTPS marker trusts plaintext requests as secure.
        if let Some(col) = python_django_proxy_ssl_header_plaintext_marker_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-520",
                "python",
                "django-proxy-ssl-header-plaintext-marker",
                "Django proxy SSL header trusts a plaintext marker",
                "proxy_ssl",
                "Django SECURE_PROXY_SSL_HEADER treats an HTTP forwarded protocol marker as secure, confusing HTTPS and CSRF decisions behind a proxy.",
                t,
            );
        }
        // CWE-693: MIME-sniffing protection explicitly disabled.
        if !suppress_python_nosniff_setting {
            if let Some(col) = python_django_content_type_nosniff_disabled_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-521",
                    "python",
                    "django-content-type-nosniff-disabled",
                    "Django content type nosniff header is disabled",
                    "security_header",
                    "Django SECURE_CONTENT_TYPE_NOSNIFF is explicitly disabled, preventing SecurityMiddleware from adding X-Content-Type-Options: nosniff.",
                    t,
                );
            }
        }
        // CWE-200: unsafe referrer policy leaks full URLs cross-origin.
        if !suppress_python_referrer_policy_setting {
            if let Some(col) = python_django_referrer_policy_unsafe_url_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-522",
                    "python",
                    "django-referrer-policy-unsafe-url",
                    "Django referrer policy leaks full URLs",
                    "security_header",
                    "Django SECURE_REFERRER_POLICY is set to unsafe-url, which can send full paths and query strings as referrers to insecure or cross-origin destinations.",
                    t,
                );
            }
        }
        // CWE-319: HSTS disabled leaves future visits open to HTTPS downgrade.
        if !suppress_python_hsts_setting {
            if let Some(col) = python_django_hsts_zero_seconds_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-523",
                    "python",
                    "django-hsts-zero-seconds",
                    "Django HSTS max age is disabled",
                    "security_header",
                    "Django SECURE_HSTS_SECONDS is set to 0, preventing SecurityMiddleware from emitting Strict-Transport-Security for HTTPS responses.",
                    t,
                );
            }
        }
        // CWE-78: OS command execution.
        if let Some(col) = first_code_match(
            line,
            &[
                "os.system(",
                "os.popen(",
                "subprocess.getoutput(",
                "commands.getoutput(",
                "commands.getstatusoutput(",
            ],
        )
        .or_else(|| find_code_match(line, "subprocess.").filter(|_| line.contains("shell=True")))
        {
            push_pattern(findings, root, path, i, col + 1, "GF-404", "python", "command-injection-nonliteral-arg",
                "OS command execution API in Python (os.system/subprocess shell=True/popen)",
                "call", "The call runs an OS command; with shell=True or a built command it enables command injection.", t);
        }
        // CWE-94: dynamic code evaluation (builtin eval/exec, not method .eval).
        if let Some(col) = python_dynamic_eval_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-420",
                "python",
                "code-injection-dynamic-eval",
                "Dynamic eval/exec of a Python expression",
                "call",
                "eval()/exec() on runtime data executes arbitrary code.",
                t,
            );
        }
        // CWE-502: unsafe deserialization.
        if let Some(col) = first_code_match(
            line,
            &[
                "pickle.loads(",
                "pickle.load(",
                "cPickle.loads(",
                "cPickle.load(",
                "_pickle.loads(",
                "marshal.loads(",
                "marshal.load(",
            ],
        )
        .or_else(|| {
            find_code_match(line, "yaml.load(")
                .filter(|_| !line.contains("SafeLoader") && !line.contains("CSafeLoader"))
        }) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-421",
                "python",
                "unsafe-deserialization",
                "Unsafe deserialization (pickle/marshal/yaml.load)",
                "deserialization",
                "Deserializing untrusted data can execute arbitrary code; use a safe loader.",
                t,
            );
        }
        // CWE-22: tar archive extraction without a safe extraction filter.
        if let Some(col) = python_tarfile_unsafe_extraction_column(
            line,
            &tarfile_module_aliases,
            &tarfile_open_aliases,
            &tarfile_handle_aliases,
            &tarfile_safe_filter_handles,
            &tarfile_validated_member_aliases,
        ) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-542",
                "python",
                "tarfile-extraction-without-safe-filter",
                "Python tarfile extraction omits a safe filter",
                "archive-path",
                "tarfile extract/extractall can write attacker-controlled archive member paths outside the destination unless a safe extraction filter or equivalent validation is used.",
                t,
            );
        }
        // CWE-1336: request-controlled data used as server-side template source.
        if let Some(col) = python_template_injection_column(
            line,
            &template_render_string_aliases,
            &jinja_template_aliases,
            &jinja_environment_handle_aliases,
            &untrusted_template_aliases,
        ) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-543",
                "python",
                "python-server-side-template-injection",
                "Python request data is used as a template source",
                "template",
                "Request-controlled data reaches a Flask/Jinja template-source API; pass it as template context instead.",
                t,
            );
        }
        // CWE-89: SQL built dynamically and executed.
        if first_code_match(line, &[".execute(", ".executemany("]).is_some()
            && has_dynamic_string(line)
            && line_has_sql_keyword(line)
        {
            let col = find_code_match(line, ".execute").unwrap_or(0) + 1;
            push_pattern(
                findings,
                root,
                path,
                i,
                col,
                "GF-419",
                "python",
                "sql-injection-dynamic-query",
                "SQL query built from non-literal input",
                "sql",
                "A dynamically-built SQL string is executed; use bound parameters.",
                t,
            );
        }
        // CWE-943: GraphQL operation document parsed via gql() from a dynamically-
        // built string. gql() is graphql-core's query parser, so a non-literal
        // operation string carrying GraphQL syntax is the documented injection
        // anti-pattern — bind request data as variables instead.
        if let Some(col) = find_code_call(line, "gql(")
            .filter(|_| has_dynamic_string(line) && line_has_graphql_operation(line))
        {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-545",
                "python",
                "graphql-injection-dynamic-query",
                "GraphQL query built from non-literal input",
                "graphql",
                "A dynamically-built GraphQL operation string is parsed via gql(); interpolating request data enables GraphQL injection. Keep the document literal and pass user data through query variables.",
                t,
            );
        }
        // CWE-327: weak crypto.
        if let Some(col) = python_weak_crypto_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-422",
                "python",
                "weak-cryptography",
                "Weak cryptographic primitive (md5/sha1/DES/RC4/ECB)",
                "crypto",
                "Broken/weak primitive; use SHA-256+/AES-GCM.",
                t,
            );
        }
        // CWE-798: hardcoded secret.
        if !suppress_generic_hardcoded_secret {
            if let Some(col) = hardcoded_secret_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-423",
                    "python",
                    "hardcoded-credential",
                    "Hardcoded credential/secret",
                    "secret",
                    "A secret is assigned a string literal; load it at runtime instead.",
                    t,
                );
            }
        }
    }
}

/// Column of a Python builtin `eval(`/`exec(` call (not a method `.eval(`) whose
/// argument is not a pure string literal.
fn python_dynamic_eval_column(line: &str) -> Option<usize> {
    for kw in ["eval(", "exec("] {
        if let Some(at) = find_code_match(line, kw) {
            let prev = line[..at].chars().next_back();
            let is_call = prev.is_none_or(|c| !c.is_alphanumeric() && c != '_' && c != '.');
            // Skip a DEFINITION of a method/function named eval/exec (`def eval(`),
            // not a call to the builtin.
            let is_definition = line[..at].trim_end().ends_with("def");
            // Skip a pure-literal arg: eval("...") / exec('...').
            let arg = &line[at + kw.len()..];
            let literal_only =
                arg.trim_start().starts_with('"') || arg.trim_start().starts_with('\'');
            if is_call && !is_definition && !literal_only {
                return Some(at);
            }
        }
    }
    None
}

fn python_tarfile_module_aliases(source: &str) -> BTreeSet<String> {
    let mut aliases = BTreeSet::from(["tarfile".to_owned()]);
    for line in source.lines().map(str::trim) {
        if let Some(alias) = line.strip_prefix("import tarfile as ") {
            if let Some(identifier) = python_first_identifier(alias) {
                aliases.insert(identifier);
            }
        }
    }
    aliases
}

fn python_tarfile_open_aliases(
    source: &str,
    module_aliases: &BTreeSet<String>,
) -> BTreeSet<String> {
    let mut aliases = BTreeSet::new();
    for module in module_aliases {
        aliases.insert(format!("{module}.open"));
    }
    for line in source.lines().map(str::trim) {
        let Some(rest) = line.strip_prefix("from tarfile import ") else {
            continue;
        };
        for imported in split_top_level_commas(rest) {
            let imported = imported.trim();
            if imported == "open" {
                aliases.insert("open".to_owned());
            } else if let Some(alias) = imported.strip_prefix("open as ") {
                if let Some(identifier) = python_first_identifier(alias) {
                    aliases.insert(identifier);
                }
            }
        }
    }
    aliases
}

fn python_tarfile_handle_aliases(
    source: &str,
    module_aliases: &BTreeSet<String>,
    open_aliases: &BTreeSet<String>,
) -> BTreeSet<String> {
    let mut aliases = BTreeSet::new();
    let zip_aliases = python_zipfile_handle_aliases(source);
    for line in source.lines().map(str::trim) {
        if let Some(alias) = python_tarfile_with_alias(line, module_aliases, open_aliases) {
            if !zip_aliases.contains(&alias) {
                aliases.insert(alias);
            }
            continue;
        }
        if python_line_is_comparison(line) {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        let right = right.trim();
        if !python_expr_starts_tarfile_open_call(right, module_aliases, open_aliases)
            || python_tarfile_open_expr_uses_trusted_archive(right, open_aliases)
        {
            continue;
        }
        if let Some(alias) = python_assignment_lhs_identifier(left) {
            if !zip_aliases.contains(&alias) {
                aliases.insert(alias);
            }
        }
    }
    aliases
}

fn python_zipfile_handle_aliases(source: &str) -> BTreeSet<String> {
    let mut module_aliases = BTreeSet::from(["zipfile".to_owned()]);
    let mut zipfile_class_aliases = BTreeSet::new();
    for module in &module_aliases {
        zipfile_class_aliases.insert(format!("{module}.ZipFile"));
    }
    for line in source.lines().map(str::trim) {
        if let Some(alias) = line.strip_prefix("import zipfile as ") {
            if let Some(identifier) = python_first_identifier(alias) {
                module_aliases.insert(identifier.clone());
                zipfile_class_aliases.insert(format!("{identifier}.ZipFile"));
            }
        }
        if let Some(rest) = line.strip_prefix("from zipfile import ") {
            for imported in split_top_level_commas(rest) {
                let imported = imported.trim();
                if imported == "ZipFile" {
                    zipfile_class_aliases.insert("ZipFile".to_owned());
                } else if let Some(alias) = imported.strip_prefix("ZipFile as ") {
                    if let Some(identifier) = python_first_identifier(alias) {
                        zipfile_class_aliases.insert(identifier);
                    }
                }
            }
        }
    }
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if let Some(alias) = python_archive_with_alias(line, &zipfile_class_aliases) {
            aliases.insert(alias);
            continue;
        }
        if python_line_is_comparison(line) {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        if python_expr_starts_any_call(right.trim(), &zipfile_class_aliases) {
            if let Some(alias) = python_assignment_lhs_identifier(left) {
                aliases.insert(alias);
            }
        }
    }
    aliases
}

fn python_tarfile_with_alias(
    line: &str,
    module_aliases: &BTreeSet<String>,
    open_aliases: &BTreeSet<String>,
) -> Option<String> {
    let trimmed = line.strip_prefix("with ")?;
    let as_column = trimmed.find(" as ")?;
    let expr = trimmed[..as_column].trim();
    if !python_expr_starts_tarfile_open_call(expr, module_aliases, open_aliases) {
        return None;
    }
    if python_tarfile_open_expr_uses_trusted_archive(expr, open_aliases) {
        return None;
    }
    python_first_identifier(
        trimmed[as_column + " as ".len()..]
            .trim()
            .trim_end_matches(':'),
    )
}

fn python_expr_starts_tarfile_open_call(
    expr: &str,
    module_aliases: &BTreeSet<String>,
    open_aliases: &BTreeSet<String>,
) -> bool {
    python_expr_starts_any_call(expr, open_aliases)
        || module_aliases.iter().any(|module| {
            let needle = format!("{module}.open(");
            expr.trim_start().starts_with(&needle)
        })
}

fn python_expr_starts_any_call(expr: &str, call_aliases: &BTreeSet<String>) -> bool {
    call_aliases.iter().any(|alias| {
        let needle = format!("{alias}(");
        expr.trim_start().starts_with(&needle)
    })
}

fn python_archive_with_alias(line: &str, call_aliases: &BTreeSet<String>) -> Option<String> {
    let trimmed = line.strip_prefix("with ")?;
    let as_column = trimmed.find(" as ")?;
    let expr = trimmed[..as_column].trim();
    if !python_expr_starts_any_call(expr, call_aliases) {
        return None;
    }
    python_first_identifier(
        trimmed[as_column + " as ".len()..]
            .trim()
            .trim_end_matches(':'),
    )
}

fn python_tarfile_open_expr_uses_trusted_archive(
    expr: &str,
    open_aliases: &BTreeSet<String>,
) -> bool {
    for opener in open_aliases {
        let needle = format!("{opener}(");
        let Some(open_column) = expr.find(&needle) else {
            continue;
        };
        let args_text = &expr[open_column + needle.len()..];
        if let Some(args) = javascript_call_arguments(args_text) {
            if args
                .first()
                .is_some_and(|arg| arg.contains("get_arch_name("))
            {
                return true;
            }
        }
    }
    false
}

fn python_tarfile_unsafe_extraction_column(
    line: &str,
    module_aliases: &BTreeSet<String>,
    open_aliases: &BTreeSet<String>,
    handle_aliases: &BTreeSet<String>,
    safe_filter_handles: &BTreeSet<String>,
    validated_member_aliases: &BTreeSet<String>,
) -> Option<usize> {
    let mut columns = Vec::new();
    for handle in handle_aliases {
        for method in ["extractall", "extract"] {
            if let Some((column, args_start)) = python_member_call_start(line, handle, method) {
                if !safe_filter_handles.contains(handle)
                    && python_tarfile_extraction_args_are_unsafe(
                        &line[args_start..],
                        validated_member_aliases,
                    )
                {
                    columns.push(column);
                }
            }
        }
    }
    for opener in open_aliases {
        columns.extend(python_direct_tarfile_extraction_columns(
            line,
            opener,
            validated_member_aliases,
        ));
    }
    for module in module_aliases {
        columns.extend(python_direct_tarfile_extraction_columns(
            line,
            &format!("{module}.open"),
            validated_member_aliases,
        ));
    }
    columns.into_iter().min()
}

fn python_member_call_start(line: &str, receiver: &str, method: &str) -> Option<(usize, usize)> {
    let needle = format!("{receiver}.{method}(");
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], &needle) {
        let column = offset + relative;
        let before = line[..column].chars().next_back();
        if !before.is_some_and(python_identifier_char) {
            return Some((column, column + needle.len()));
        }
        offset = column + needle.len();
    }
    None
}

fn python_direct_tarfile_extraction_columns(
    line: &str,
    opener: &str,
    validated_member_aliases: &BTreeSet<String>,
) -> Vec<usize> {
    let mut columns = Vec::new();
    let needle = format!("{opener}(");
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], &needle) {
        let open_column = offset + relative;
        let before = line[..open_column].chars().next_back();
        if before.is_some_and(|ch| python_identifier_char(ch) || ch == '.') {
            offset = open_column + needle.len();
            continue;
        }
        let after_open_args = &line[open_column + needle.len()..];
        let Some(open_args_end) = javascript_call_end_index(after_open_args) else {
            break;
        };
        if let Some(args) = javascript_call_arguments(after_open_args) {
            if args
                .first()
                .is_some_and(|arg| arg.contains("get_arch_name("))
            {
                offset = open_column + needle.len();
                continue;
            }
        }
        let after_open_call = open_column + needle.len() + open_args_end + 1;
        let rest = &line[after_open_call..];
        for method in ["extractall", "extract"] {
            let method_needle = format!(".{method}(");
            if rest.starts_with(&method_needle) {
                let column = after_open_call + 1;
                let args_start = after_open_call + method_needle.len();
                if python_tarfile_extraction_args_are_unsafe(
                    &line[args_start..],
                    validated_member_aliases,
                ) {
                    columns.push(column);
                }
            }
        }
        offset = after_open_call;
    }
    columns
}

fn python_tarfile_extraction_args_are_unsafe(
    args_text: &str,
    validated_member_aliases: &BTreeSet<String>,
) -> bool {
    let Some(args) = javascript_call_arguments(args_text) else {
        return true;
    };
    if args
        .iter()
        .any(|arg| python_tarfile_members_arg_is_validated(arg, validated_member_aliases))
    {
        return false;
    }
    let Some(filter_arg) = args
        .iter()
        .find(|arg| compact_ascii_lower(arg).starts_with("filter="))
    else {
        return true;
    };
    python_tarfile_filter_arg_is_unsafe(filter_arg)
}

fn python_tarfile_safe_filter_handles(source: &str) -> BTreeSet<String> {
    let mut handles = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if python_line_is_comparison(line) {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        let left = left.trim();
        let Some(receiver) = left.strip_suffix(".extraction_filter") else {
            continue;
        };
        if !python_tarfile_filter_value_is_unsafe(right.trim()) {
            handles.insert(receiver.trim().to_owned());
        }
    }
    handles
}

fn python_tarfile_validated_member_aliases(source: &str) -> BTreeSet<String> {
    let lower = source.to_ascii_lowercase();
    let has_member_path_guard = lower.contains("is_relative_to(")
        || lower.contains("commonpath(")
        || lower.contains("check_path(")
        || lower.contains("startswith(os.path.abspath")
        || lower.contains("startswith(dest")
        || lower.contains("..\" in member.name")
        || lower.contains("\"..\" in member.name")
        || lower.contains("isabs(member.name");
    if !has_member_path_guard {
        return BTreeSet::new();
    }
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        let Some(append_column) = find_code_match(line, ".append(") else {
            continue;
        };
        let alias = line[..append_column].trim();
        if alias.to_ascii_lowercase().contains("safe") {
            if let Some(identifier) = python_first_identifier(alias) {
                aliases.insert(identifier);
            }
        }
    }
    aliases
}

fn python_tarfile_members_arg_is_validated(arg: &str, aliases: &BTreeSet<String>) -> bool {
    let compact = compact_ascii_lower(arg);
    let Some(value) = compact.strip_prefix("members=") else {
        return false;
    };
    aliases.contains(value)
}

fn python_tarfile_filter_arg_is_unsafe(arg: &str) -> bool {
    let compact = compact_ascii_lower(arg);
    let value = compact.strip_prefix("filter=").unwrap_or(compact.as_str());
    python_tarfile_filter_value_is_unsafe(value)
}

fn python_tarfile_filter_value_is_unsafe(value: &str) -> bool {
    let value = compact_ascii_lower(value);
    matches!(
        value.as_str(),
        "none" | "'fully_trusted'" | "\"fully_trusted\""
    ) || value.ends_with(".fully_trusted_filter")
        || value == "fully_trusted_filter"
}

fn python_line_is_comparison(line: &str) -> bool {
    ["==", "!=", ">=", "<="]
        .iter()
        .any(|operator| line.contains(operator))
}

fn python_assignment_lhs_identifier(left: &str) -> Option<String> {
    let left = left.trim();
    if left.contains('.') {
        return None;
    }
    python_first_identifier(left)
}

fn python_first_identifier(input: &str) -> Option<String> {
    let identifier: String = input
        .trim()
        .chars()
        .take_while(|ch| python_identifier_char(*ch))
        .collect();
    (!identifier.is_empty()
        && identifier
            .chars()
            .next()
            .is_some_and(|ch| ch == '_' || ch.is_ascii_alphabetic()))
    .then_some(identifier)
}

fn python_identifier_char(ch: char) -> bool {
    ch == '_' || ch.is_ascii_alphanumeric()
}

fn python_template_render_string_aliases(source: &str) -> BTreeSet<String> {
    let mut aliases = BTreeSet::from(["render_template_string".to_owned()]);
    let mut flask_modules = BTreeSet::from(["flask".to_owned()]);
    for line in source.lines().map(str::trim) {
        if let Some(alias) = line.strip_prefix("import flask as ") {
            if let Some(identifier) = python_first_identifier(alias) {
                flask_modules.insert(identifier);
            }
        }
        if let Some(rest) = line.strip_prefix("from flask import ") {
            for imported in split_top_level_commas(rest) {
                let imported = imported.trim();
                if imported == "render_template_string" {
                    aliases.insert("render_template_string".to_owned());
                } else if let Some(alias) = imported.strip_prefix("render_template_string as ") {
                    if let Some(identifier) = python_first_identifier(alias) {
                        aliases.insert(identifier);
                    }
                }
            }
        }
    }
    aliases.extend(
        flask_modules
            .into_iter()
            .map(|module| format!("{module}.render_template_string")),
    );
    aliases
}

fn python_jinja_template_aliases(source: &str) -> BTreeSet<String> {
    let mut modules = BTreeSet::from(["jinja2".to_owned()]);
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if let Some(alias) = line.strip_prefix("import jinja2 as ") {
            if let Some(identifier) = python_first_identifier(alias) {
                modules.insert(identifier);
            }
        }
        if let Some(rest) = line.strip_prefix("from jinja2 import ") {
            for imported in split_top_level_commas(rest) {
                let imported = imported.trim();
                if imported == "Template" {
                    aliases.insert("Template".to_owned());
                } else if let Some(alias) = imported.strip_prefix("Template as ") {
                    if let Some(identifier) = python_first_identifier(alias) {
                        aliases.insert(identifier);
                    }
                }
            }
        }
    }
    aliases.extend(modules.iter().map(|module| format!("{module}.Template")));
    aliases.insert("Template".to_owned());
    aliases
}

fn python_jinja_environment_aliases(source: &str) -> BTreeSet<String> {
    let mut modules = BTreeSet::from(["jinja2".to_owned()]);
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if let Some(alias) = line.strip_prefix("import jinja2 as ") {
            if let Some(identifier) = python_first_identifier(alias) {
                modules.insert(identifier);
            }
        }
        if let Some(rest) = line.strip_prefix("from jinja2 import ") {
            for imported in split_top_level_commas(rest) {
                let imported = imported.trim();
                if imported == "Environment" {
                    aliases.insert("Environment".to_owned());
                } else if let Some(alias) = imported.strip_prefix("Environment as ") {
                    if let Some(identifier) = python_first_identifier(alias) {
                        aliases.insert(identifier);
                    }
                }
            }
        }
    }
    aliases.extend(
        modules
            .into_iter()
            .map(|module| format!("{module}.Environment")),
    );
    aliases.insert("Environment".to_owned());
    aliases
}

fn python_jinja_environment_handle_aliases(
    source: &str,
    environment_aliases: &BTreeSet<String>,
) -> BTreeSet<String> {
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if python_line_is_comparison(line) {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        if python_expr_starts_any_call(right.trim(), environment_aliases) {
            if let Some(alias) = python_assignment_lhs_identifier(left) {
                aliases.insert(alias);
            }
        }
    }
    aliases
}

fn python_untrusted_template_aliases(source: &str) -> BTreeSet<String> {
    let mut aliases = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if python_line_is_comparison(line) {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        if python_template_source_expression_is_untrusted(right, &aliases) {
            if let Some(alias) = python_assignment_lhs_identifier(left) {
                aliases.insert(alias);
            }
        }
    }
    aliases
}

fn python_template_injection_column(
    line: &str,
    render_string_aliases: &BTreeSet<String>,
    template_aliases: &BTreeSet<String>,
    environment_handle_aliases: &BTreeSet<String>,
    untrusted_aliases: &BTreeSet<String>,
) -> Option<usize> {
    let mut columns = Vec::new();
    for alias in render_string_aliases {
        if let Some((column, args_start)) = python_function_call_start(line, alias) {
            if python_first_arg_is_untrusted_template_source(&line[args_start..], untrusted_aliases)
            {
                columns.push(column);
            }
        }
    }
    for alias in template_aliases {
        if let Some((column, args_start)) = python_function_call_start(line, alias) {
            if python_first_arg_is_untrusted_template_source(&line[args_start..], untrusted_aliases)
            {
                columns.push(column);
            }
        }
    }
    for env in environment_handle_aliases {
        if let Some((column, args_start)) = python_member_call_start(line, env, "from_string") {
            if python_first_arg_is_untrusted_template_source(&line[args_start..], untrusted_aliases)
            {
                columns.push(column);
            }
        }
    }
    columns.into_iter().min()
}

fn python_first_arg_is_untrusted_template_source(
    args_text: &str,
    aliases: &BTreeSet<String>,
) -> bool {
    javascript_call_arguments(args_text).is_some_and(|args| {
        args.first()
            .is_some_and(|arg| python_template_source_expression_is_untrusted(arg, aliases))
    })
}

fn python_template_source_expression_is_untrusted(arg: &str, aliases: &BTreeSet<String>) -> bool {
    let arg = arg.trim();
    if arg.is_empty()
        || python_static_template_source(arg)
        || python_template_source_expression_is_sanitized(arg)
    {
        return false;
    }
    aliases.contains(arg)
        || python_request_value_reference(arg)
        || python_template_source_uses_untrusted_alias(arg, aliases)
        || python_template_builder_uses_request_value(arg, aliases)
}

fn python_static_template_source(arg: &str) -> bool {
    let trimmed = arg.trim();
    ((trimmed.starts_with('"') && trimmed.ends_with('"'))
        || (trimmed.starts_with('\'') && trimmed.ends_with('\'')))
        && !has_dynamic_string(trimmed)
        && !trimmed.starts_with("f\"")
        && !trimmed.starts_with("f'")
}

fn python_template_source_expression_is_sanitized(arg: &str) -> bool {
    let lower = arg.to_ascii_lowercase();
    lower.contains("validatetemplate")
        || lower.contains("validate_template")
        || lower.contains("trustedtemplate")
        || lower.contains("trusted_template")
        || lower.contains("approvedtemplate")
        || lower.contains("approved_template")
        || lower.contains("allowlistedtemplate")
        || lower.contains("allowlisted_template")
        || lower == "trusted_template"
        || lower == "template_source"
}

fn python_template_source_uses_untrusted_alias(arg: &str, aliases: &BTreeSet<String>) -> bool {
    let without_string_literals = strip_simple_quoted_strings(arg);
    aliases
        .iter()
        .any(|alias| token_in_text(&without_string_literals, alias))
        || python_f_string_uses_untrusted_alias(arg, aliases)
}

fn python_f_string_uses_untrusted_alias(arg: &str, aliases: &BTreeSet<String>) -> bool {
    let bytes = arg.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let quote = bytes[i];
        if quote != b'\'' && quote != b'"' {
            i += 1;
            continue;
        }
        let mut prefix_start = i;
        while prefix_start > 0 && bytes[prefix_start - 1].is_ascii_alphabetic() {
            prefix_start -= 1;
        }
        let prefix = &arg[prefix_start..i];
        let is_f_string = !prefix.is_empty()
            && prefix
                .chars()
                .all(|ch| matches!(ch, 'f' | 'F' | 'r' | 'R' | 'u' | 'U' | 'b' | 'B'))
            && prefix.chars().any(|ch| matches!(ch, 'f' | 'F'));

        let mut j = i + 1;
        let mut escaped = false;
        while j < bytes.len() {
            let ch = bytes[j];
            if ch == quote && !escaped {
                break;
            }
            escaped = ch == b'\\' && !escaped;
            if ch != b'\\' {
                escaped = false;
            }
            j += 1;
        }
        if is_f_string && python_f_string_content_uses_untrusted_alias(&arg[i + 1..j], aliases) {
            return true;
        }
        i = j.saturating_add(1);
    }
    false
}

fn python_f_string_content_uses_untrusted_alias(content: &str, aliases: &BTreeSet<String>) -> bool {
    let bytes = content.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] != b'{' {
            i += 1;
            continue;
        }
        if i + 1 < bytes.len() && bytes[i + 1] == b'{' {
            i += 2;
            continue;
        }
        let start = i + 1;
        let mut depth = 1usize;
        i += 1;
        while i < bytes.len() {
            match bytes[i] {
                b'{' => depth += 1,
                b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        let expr = &content[start..i];
                        if aliases.iter().any(|alias| token_in_text(expr, alias)) {
                            return true;
                        }
                        break;
                    }
                }
                _ => {}
            }
            i += 1;
        }
    }
    false
}

fn python_template_builder_uses_request_value(arg: &str, aliases: &BTreeSet<String>) -> bool {
    if has_dynamic_string(arg) && python_request_value_reference(arg) {
        return true;
    }
    let Some(open) = arg.find('(') else {
        return false;
    };
    let callee = arg[..open].trim();
    if !matches!(callee, "str" | "Markup" | "format" | "TemplateSource") {
        return false;
    }
    javascript_call_arguments(&arg[open + 1..]).is_some_and(|args| {
        args.iter()
            .any(|arg| python_template_source_expression_is_untrusted(arg, aliases))
    })
}

fn python_request_value_reference(arg: &str) -> bool {
    [
        "request.args.",
        "request.args[",
        "request.form.",
        "request.form[",
        "request.values.",
        "request.values[",
        "request.json",
        "request.get_json(",
        "request.data",
        "request.GET.",
        "request.GET[",
        "request.POST.",
        "request.POST[",
        "request.body",
        "request.query_params.",
        "request.query_params[",
        "flask.request.",
        "self.request.GET.",
        "self.request.POST.",
        "self.request.body",
    ]
    .iter()
    .any(|needle| find_code_match(arg, needle).is_some())
}

fn python_function_call_start(line: &str, alias: &str) -> Option<(usize, usize)> {
    let needle = format!("{alias}(");
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], &needle) {
        let column = offset + relative;
        let before = line[..column].chars().next_back();
        if !before.is_some_and(|ch| python_identifier_char(ch) || ch == '.') {
            return Some((column, column + needle.len()));
        }
        offset = column + needle.len();
    }
    None
}

/// Column of a weak Rust crypto primitive (CWE-327) from the RustCrypto ecosystem:
/// `Md5`/`Sha1` digests, `Des`/`TdesEde3`/`Rc4`/`Blowfish` ciphers, and the
/// `md5::compute` / `md5::Md5` convenience API. Call/type-boundary aware so a
/// substring inside a longer identifier (`address_of!`, `Sha256`) never matches.
fn rust_weak_crypto_column(line: &str) -> Option<usize> {
    // Word-bounded type/call needles. `find_code_call` requires a non-identifier
    // char before the needle, so `Sha1` does not match inside `Sha1Sum` and
    // `Md5` does not match inside `Cmd5`.
    const NEEDLES: &[&str] = &[
        "Md5::",
        "Md4::",
        "Md2::",
        "Sha1::",
        "Des::",
        "TdesEde3::",
        "TdesEde2::",
        "DesEde3::",
        "Rc4::",
        "Rc2::",
        "Blowfish::",
        "md5::compute(",
        "Ecb::",
    ];
    first_rust_crypto_needle(line, NEEDLES)
}

/// Earliest word-bounded, string-literal-free occurrence of any needle. A needle
/// ending in `::` is matched as a path segment (boundary before, `::` after is
/// implicit in the needle); a `(` needle is a call.
fn first_rust_crypto_needle(line: &str, needles: &[&str]) -> Option<usize> {
    needles.iter().filter_map(|n| find_code_call(line, n)).min()
}

/// Column of a weak Go crypto primitive (CWE-327): MD5/SHA1 hashing, DES/3DES,
/// RC4, Blowfish ciphers, and ECB mode. String-literal aware via `first_code_match`.
fn go_weak_crypto_column(line: &str) -> Option<usize> {
    first_code_match(
        line,
        &[
            "md5.New(",
            "md5.Sum(",
            "sha1.New(",
            "sha1.Sum(",
            "des.NewCipher(",
            "des.NewTripleDESCipher(",
            "rc4.NewCipher(",
            "blowfish.NewCipher(",
            "blowfish.NewSaltedCipher(",
            "cipher.NewECBEncrypter(",
            "cipher.NewECBDecrypter(",
        ],
    )
}

fn python_weak_crypto_column(line: &str) -> Option<usize> {
    // Python 3.9+ `usedforsecurity=False` is an explicit non-security use (a
    // checksum / cache key), not a weak-crypto finding.
    if line.contains("usedforsecurity=False") || line.contains("usedforsecurity = False") {
        return None;
    }
    first_code_match(
        line,
        &[
            "hashlib.md5(",
            "hashlib.sha1(",
            "MD5.new(",
            "MD4.new(",
            "MD2.new(",
            "SHA.new(",
            "SHA1.new(",
            "DES.new(",
            "DES3.new(",
            "ARC4.new(",
            "ARC2.new(",
            "Blowfish.new(",
            "MODE_ECB",
        ],
    )
}

/// Column of a hardcoded-secret assignment: a `password`/`secret`/`api_key`/
/// `token`/`passwd`-named lvalue assigned a non-trivial string literal. Low
/// confidence by rule default (name heuristics are noisy).
fn hardcoded_secret_column(line: &str) -> Option<usize> {
    if detect_secret(line).is_some() {
        return None;
    }
    // A doctest / REPL example (`>>> f(password='x')`) is illustrative, not code.
    let trimmed = line.trim_start();
    if trimmed.starts_with(">>>") || trimmed.starts_with("... ") {
        return None;
    }
    // The secret NAME must be on the lvalue (left of `=`), not inside the value
    // string — a value like "AKIAsecret..." must not be mistaken for the name.
    let eq = find_code_match(line, "=")?;
    // Skip comparisons (`==`, `!=`, `<=`, `>=`) — this is an assignment rule.
    if line[eq..].starts_with("==") || line[..eq].ends_with(['!', '<', '>', '=']) {
        return None;
    }
    // A secret-looking name to the LEFT of the `=` that sits inside an unclosed
    // call/def parenthesis is a keyword argument or a parameter DEFAULT
    // (`connect(password="x")`, `def h(token, digestmod="sha256")`) — the name is
    // a formal parameter, not a variable being assigned a literal secret.
    let before = &line[..eq];
    if before.matches('(').count() > before.matches(')').count() {
        return None;
    }
    if before.contains(',') {
        return None;
    }
    let lhs = line[..eq].to_ascii_lowercase();
    let names = [
        "password",
        "passwd",
        "secret",
        "api_key",
        "apikey",
        "access_key",
        "token",
        "private_key",
    ];
    let name_at = names.iter().find_map(|n| lhs.find(n))?;
    // The name holds a REFERENCE to where the secret lives — the env-var name, a
    // config key, a header/field name — not the secret itself. Assigning an env-var
    // NAME to `nvd_api_key_env_var` is the CORRECT, safe pattern, not a leak.
    const REFERENCE_MARKERS: &[&str] = &[
        "env_var", "envvar", "_env", "_name", "_field", "_header", "_setting", "key_name",
        "keyname", "_id", "_url", "_label",
    ];
    if REFERENCE_MARKERS.iter().any(|marker| lhs.contains(marker))
        || hardcoded_secret_lhs_is_metadata(&lhs)
    {
        return None;
    }
    // Assigned a non-trivial, non-placeholder string literal.
    let rhs = line[eq + 1..].trim_start();
    let quote = rhs.chars().next()?;
    if !matches!(quote, '"' | '\'') {
        return None;
    }
    let literal = &rhs[quote.len_utf8()..];
    let end = literal.find(quote)?;
    let value = &literal[..end];
    let after_literal = literal[end + quote.len_utf8()..].trim_start();
    // A value that is itself an ENV-VAR NAME (all uppercase + `_`/digits, e.g.
    // "NVD_API_KEY") references a secret, it is not the secret.
    let looks_like_env_name = value.len() >= 6
        && value
            .chars()
            .all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
        && value.chars().any(|c| c.is_ascii_uppercase());
    if end >= 6
        && !value.contains("${")
        && !hardcoded_secret_literal_is_placeholder(value)
        && !hardcoded_secret_literal_is_non_secret(value, after_literal)
        && !looks_like_env_name
    {
        Some(name_at)
    } else {
        None
    }
}

fn hardcoded_secret_lhs_is_metadata(lhs: &str) -> bool {
    [
        "_prefix",
        "prefix_",
        "_file",
        "file_",
        "_type",
        "type_",
        "_msg",
        "msg_",
        "_message",
        "message_",
        "_reason",
        "reason_",
        "passwordfile",
        "passwdfile",
    ]
    .iter()
    .any(|marker| lhs.contains(marker))
}

fn hardcoded_secret_literal_is_non_secret(value: &str, after_literal: &str) -> bool {
    let trimmed = value.trim();
    let lower = trimmed.to_ascii_lowercase();
    if trimmed.contains("%(")
        || trimmed.contains("${")
        || trimmed.contains('[') && trimmed.contains(']')
        || trimmed.starts_with('/')
        || trimmed.contains('\\')
        || after_literal.starts_with('+')
        || after_literal.starts_with('%')
    {
        return true;
    }
    if trimmed.starts_with('_')
        && (lower.contains("token") || lower.contains("password") || lower.contains("secret"))
    {
        return true;
    }
    if trimmed.chars().any(char::is_whitespace) {
        return true;
    }
    matches!(
        lower.as_str(),
        "bearer"
            | "scrypt"
            | "bcrypt"
            | "argon2"
            | "pbkdf2"
            | "sha1"
            | "sha224"
            | "sha256"
            | "sha384"
            | "sha512"
            | "md5"
            | "make.bat"
    ) || lower.ends_with(".bat")
        || lower.ends_with(".cmd")
        || lower.ends_with(".exe")
        || lower.ends_with(".sh")
}

fn hardcoded_secret_literal_is_placeholder(value: &str) -> bool {
    let trimmed = value.trim();
    if trimmed.eq_ignore_ascii_case("changeme") {
        return true;
    }
    if let Some(inner) = trimmed
        .strip_prefix('<')
        .and_then(|value| value.strip_suffix('>'))
    {
        return !inner.trim().is_empty()
            && inner
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | ' '));
    }
    false
}

/// CWE-295: TLS certificate/hostname verification disabled. Cross-language, very
/// low FP — the constructs below have no legitimate production use. Returns the
/// 1-based column of the disabling construct.
fn insecure_tls_column(line: &str, language: &str) -> Option<usize> {
    if language == "cpp" {
        return cpp_qt_ignore_ssl_errors_column(line).map(|column| column + 1);
    }
    if language == "qml" {
        return qml_webengine_accept_certificate_column(line).map(|column| column + 1);
    }
    let markers: &[&str] = match language {
        "python" => &[
            "verify=False",
            "ssl.CERT_NONE",
            "_create_unverified_context",
            "check_hostname = False",
            "check_hostname=False",
        ],
        "go" => &["InsecureSkipVerify: true", "InsecureSkipVerify:true"],
        "java" => &[
            "ALLOW_ALL_HOSTNAME_VERIFIER",
            "NoopHostnameVerifier",
            "TrustAllCerts",
            "setHostnameVerifier(null",
        ],
        "rust" => &[
            "danger_accept_invalid_certs(true",
            "danger_accept_invalid_hostnames(true",
            "accept_invalid_certs(true",
        ],
        "javascript" => &[
            "rejectUnauthorized: false",
            "rejectUnauthorized:false",
            "NODE_TLS_REJECT_UNAUTHORIZED",
            "checkServerIdentity",
        ],
        _ => return None,
    };
    let trimmed = line.trim_start();
    if trimmed.starts_with('#') || trimmed.starts_with("//") || trimmed.starts_with('*') {
        return None;
    }
    if language == "javascript" {
        return javascript_insecure_tls_column(line);
    }
    // A marker starting with a letter must sit at a word boundary — the char before
    // it may not be an identifier char — so `verify=False` matches a `verify=False`
    // keyword arg but NOT the suffix of `delete_after_verify=False`. Markers that
    // start with `_`/`.` (method-accessed) are matched verbatim.
    markers.iter().find_map(|marker| {
        let bare = marker
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_alphabetic());
        let mut offset = 0usize;
        while let Some(relative) = find_code_match(&line[offset..], marker) {
            let index = offset + relative;
            let boundary = !bare
                || line[..index]
                    .chars()
                    .next_back()
                    .is_none_or(|c| !(c.is_ascii_alphanumeric() || c == '_'));
            if boundary {
                return Some(index + 1);
            }
            offset = index + marker.len();
        }
        None
    })
}

fn cpp_qt_ignore_ssl_errors_column(line: &str) -> Option<usize> {
    let trimmed = line.trim_start();
    if trimmed.starts_with("//") || trimmed.starts_with('*') {
        return None;
    }
    let compact = compact_ascii_lower(line);
    let direct_ignore = compact.contains("->ignoresslerrors(")
        || compact.contains(".ignoresslerrors(")
        || compact.contains("slot(ignoresslerrors(");
    let connected_ignore = [
        "&QNetworkReply::ignoreSslErrors",
        "&QSslSocket::ignoreSslErrors",
        "&QWebSocket::ignoreSslErrors",
    ]
    .iter()
    .any(|marker| find_code_match(line, marker).is_some());

    (direct_ignore || connected_ignore)
        .then(|| find_code_match(line, "ignoreSslErrors"))
        .flatten()
}

fn qml_webengine_accept_certificate_column(line: &str) -> Option<usize> {
    let trimmed = line.trim_start();
    if trimmed.starts_with("//") || trimmed.starts_with('*') {
        return None;
    }
    find_code_match(line, ".acceptCertificate(")
}

