fn push_python_qt_webengine_local_file_access_findings(
    root: &Path,
    path: &Path,
    source: &str,
    findings: &mut Vec<StaticFinding>,
) {
    let lines: Vec<&str> = source.lines().collect();
    for index in 0..lines.len() {
        if let Some(col) = python_qt_webengine_local_content_file_access_column(&lines, index) {
            push_pattern(
                findings,
                root,
                path,
                index,
                col + 1,
                "GF-539",
                "python",
                "qt-webengine-local-content-file-access",
                "Qt WebEngine local content can access local files",
                "webengine_origin",
                "Qt WebEngine is configured to let locally loaded documents access other local URLs.",
                lines[index].trim(),
            );
        }
    }
}

fn python_qt_webengine_local_content_file_access_column(
    lines: &[&str],
    index: usize,
) -> Option<usize> {
    let line = lines[index];
    let column = first_code_match(
        line,
        &[
            "QWebEngineSettings.WebAttribute.LocalContentCanAccessFileUrls",
            "QWebEngineSettings.LocalContentCanAccessFileUrls",
        ],
    )?;
    let end = (index + 4).min(lines.len());
    let window = lines[index..end].join("\n");
    let compact = compact_ascii_lower(&window);
    let attr_index = compact.find("localcontentcanaccessfileurls")?;
    let value = &compact[attr_index + "localcontentcanaccessfileurls".len()..];
    if value.starts_with(",true")
        || value.contains("['allow_file_urls']")
        || value.contains("[\"allow_file_urls\"]")
    {
        Some(column)
    } else {
        None
    }
}

fn cpp_qt_webengine_attribute_true_column(attribute: &str, line: &str) -> Option<usize> {
    cpp_qt_webengine_attribute_bool_column(attribute, line, true)
}

fn cpp_qt_webengine_attribute_bool_column(
    attribute: &str,
    line: &str,
    expected: bool,
) -> Option<usize> {
    let marker = format!("QWebEngineSettings::{attribute}");
    let column = find_code_match(line, &marker)?;
    let after_marker = &line[column + marker.len()..];
    let value = after_marker.trim_start().strip_prefix(',')?.trim_start();
    code_bool_literal_prefix(value, expected).then_some(column)
}

fn cpp_qt_webengine_attribute_settings_default_true_column(
    attribute: &str,
    line: &str,
) -> Option<usize> {
    cpp_qt_webengine_attribute_settings_default_bool_column(attribute, line, true)
}

fn cpp_qt_webengine_attribute_settings_default_bool_column(
    attribute: &str,
    line: &str,
    expected: bool,
) -> Option<usize> {
    let marker = format!("QWebEngineSettings::{attribute}");
    let column = find_code_match(line, &marker)?;
    let after_marker = &line[column + marker.len()..];
    let value = after_marker.trim_start().strip_prefix(',')?.trim_start();
    let compact = compact_ascii_lower(&strip_simple_quoted_strings(value));
    let uses_qsettings_value = compact.starts_with("value(") || compact.contains(".value(");
    let literal = if expected { "true" } else { "false" };
    (uses_qsettings_value && compact.contains(&format!(",{literal}).tobool("))).then_some(column)
}

fn config_qt_webengine_sandbox_disabled_column(line: &str) -> Option<usize> {
    if qt_webengine_disable_sandbox_truthy(line)
        && config_line_sets_qt_webengine_env(line, "qtwebengine_disable_sandbox")
    {
        return find_ascii_case_insensitive(line, "QTWEBENGINE_DISABLE_SANDBOX");
    }
    if qt_webengine_chromium_flags_no_sandbox(line)
        && config_line_sets_qt_webengine_env(line, "qtwebengine_chromium_flags")
    {
        return find_ascii_case_insensitive(line, "QTWEBENGINE_CHROMIUM_FLAGS");
    }
    if config_line_passes_qt_webengine_no_sandbox_arg(line) {
        return find_ascii_case_insensitive(line, "--no-sandbox");
    }
    None
}

fn config_line_sets_qt_webengine_env(line: &str, marker: &str) -> bool {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    lower.starts_with(marker)
        || lower.starts_with(&format!("-{marker}"))
        || lower.starts_with(&format!("env {marker}"))
        || lower.starts_with(&format!("arg {marker}"))
        || lower.starts_with(&format!("environment: {marker}"))
        || lower.starts_with(&format!("environment={marker}"))
}

fn config_line_passes_qt_webengine_no_sandbox_arg(line: &str) -> bool {
    let lower = line.trim_start().to_ascii_lowercase();
    lower.contains("--webengineargs")
        && lower.contains("--no-sandbox")
        && (lower.starts_with("cmd ")
            || lower.starts_with("cmd:")
            || lower.starts_with("entrypoint ")
            || lower.starts_with("entrypoint:")
            || lower.starts_with("command:")
            || lower.starts_with("args:")
            || lower.starts_with("-"))
}

fn qt_webengine_disable_sandbox_truthy(line: &str) -> bool {
    qt_webengine_env_value_truthy(line, "qtwebengine_disable_sandbox")
}

fn qt_webengine_env_value_truthy(line: &str, marker: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    let Some(marker_index) = lower.find(marker) else {
        return false;
    };
    let mut value = &lower[marker_index + marker.len()..];
    value = value.trim_start_matches(|ch: char| {
        ch.is_ascii_whitespace()
            || matches!(ch, '=' | ':' | ',' | '"' | '\'' | '(' | '[' | ']' | '{')
    });
    truthy_literal_prefix(value)
}

fn truthy_literal_prefix(value: &str) -> bool {
    value.strip_prefix('1').is_some_and(|rest| {
        rest.chars()
            .next()
            .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'))
    }) || value.strip_prefix("true").is_some_and(|rest| {
        rest.chars()
            .next()
            .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'))
    })
}

fn qt_webengine_chromium_flags_no_sandbox(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    lower.contains("qtwebengine_chromium_flags") && lower.contains("--no-sandbox")
}

fn find_ascii_case_insensitive(line: &str, needle: &str) -> Option<usize> {
    line.to_ascii_lowercase().find(&needle.to_ascii_lowercase())
}

fn code_bool_assignment_column(line: &str, setting: &str, expected: bool) -> Option<usize> {
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], setting) {
        let index = offset + relative;
        let before_boundary = line[..index]
            .chars()
            .next_back()
            .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'));
        let after = &line[index + setting.len()..];
        let after_boundary = after
            .chars()
            .next()
            .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'));
        if before_boundary && after_boundary {
            let value = after
                .trim_start()
                .strip_prefix(':')
                .or_else(|| after.trim_start().strip_prefix('='))?
                .trim_start();
            if code_bool_literal_prefix(value, expected) {
                return Some(index);
            }
        }
        offset = index + setting.len();
    }
    None
}

fn code_bool_literal_prefix(value: &str, expected: bool) -> bool {
    let literal = if expected { "true" } else { "false" };
    let Some(rest) = value.trim_start().strip_prefix(literal) else {
        return false;
    };
    rest.chars()
        .next()
        .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'))
}

fn javascript_line_contains_electron_browser_window_start(line: &str) -> bool {
    javascript_electron_browser_window_call_column(line).is_some()
}

fn javascript_electron_web_security_disabled_column(line: &str) -> Option<usize> {
    javascript_electron_web_preference_bool_column(line, "webSecurity", false)
}

fn javascript_electron_allow_running_insecure_content_column(line: &str) -> Option<usize> {
    javascript_electron_web_preference_bool_column(line, "allowRunningInsecureContent", true)
}

fn javascript_electron_context_isolation_disabled_column(line: &str) -> Option<usize> {
    javascript_electron_web_preference_bool_column(line, "contextIsolation", false)
}

fn javascript_electron_node_integration_enabled_column(line: &str) -> Option<usize> {
    [
        "nodeIntegration",
        "nodeIntegrationInWorker",
        "nodeIntegrationInSubFrames",
    ]
    .iter()
    .find_map(|setting| javascript_electron_web_preference_bool_column(line, setting, true))
}

fn javascript_electron_web_preference_bool_column(
    line: &str,
    setting: &str,
    expected: bool,
) -> Option<usize> {
    let browser_column = javascript_electron_browser_window_call_column(line)?;
    let web_preferences_column = find_code_match(line, "webPreferences")?;
    let setting_column = code_bool_assignment_column(line, setting, expected)?;

    (browser_column < setting_column && web_preferences_column < setting_column)
        .then_some(browser_column)
}

fn javascript_electron_browser_window_call_column(line: &str) -> Option<usize> {
    let needle = "BrowserWindow";
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], needle) {
        let column = offset + relative;
        let before = line[..column].chars().next_back();
        let after = line[column + needle.len()..].trim_start();
        if !before.is_some_and(javascript_identifier_char) && after.starts_with('(') {
            return Some(column);
        }
        offset = column + needle.len();
    }
    None
}

fn javascript_insecure_tls_column(line: &str) -> Option<usize> {
    let trimmed = line.trim_start();
    if javascript_tls_line_is_test_only(line) {
        return None;
    }
    if let Some(column) = javascript_reject_unauthorized_false_column(line) {
        return Some(column + 1);
    }
    if let Some(column) = javascript_node_tls_reject_unauthorized_zero_column(line) {
        return Some(column + 1);
    }
    if let Some(column) = javascript_check_server_identity_disabled_column(line) {
        return Some(column + 1);
    }
    if trimmed.contains("NODE_TLS_REJECT_UNAUTHORIZED") {
        return None;
    }
    None
}

fn javascript_tls_line_is_test_only(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    lower.contains("node_env")
        && (lower.contains("'test'")
            || lower.contains("\"test\"")
            || lower.contains("'development'")
            || lower.contains("\"development\"")
            || lower.contains("'dev'")
            || lower.contains("\"dev\""))
}

fn javascript_reject_unauthorized_false_column(line: &str) -> Option<usize> {
    for marker in ["rejectUnauthorized: false", "rejectUnauthorized:false"] {
        let mut offset = 0usize;
        while let Some(relative) = find_code_match(&line[offset..], marker) {
            let column = offset + relative;
            let before = line[..column].chars().next_back();
            if !before.is_some_and(javascript_identifier_char) {
                return Some(column);
            }
            offset = column + marker.len();
        }
    }
    None
}

fn javascript_node_tls_reject_unauthorized_zero_column(line: &str) -> Option<usize> {
    let needles = [
        "process.env.NODE_TLS_REJECT_UNAUTHORIZED",
        "process.env['NODE_TLS_REJECT_UNAUTHORIZED']",
        "process.env[\"NODE_TLS_REJECT_UNAUTHORIZED\"]",
    ];
    for needle in needles {
        let Some(column) = find_code_match(line, needle) else {
            continue;
        };
        let after = &line[column + needle.len()..];
        let Some(eq) = javascript_assignment_equals_column(after) else {
            continue;
        };
        let value = javascript_trim_expression_wrappers(&after[eq + 1..]);
        let value = value.trim_end_matches(';').trim();
        if matches!(value, "0" | "'0'" | "\"0\"" | "`0`") {
            return Some(column);
        }
    }
    None
}

fn javascript_check_server_identity_disabled_column(line: &str) -> Option<usize> {
    let marker = "checkServerIdentity";
    let mut offset = 0usize;
    while let Some(relative) = find_code_match(&line[offset..], marker) {
        let column = offset + relative;
        let after = &line[column + marker.len()..];
        if javascript_check_server_identity_value_disables_verification(after) {
            return Some(column);
        }
        offset = column + marker.len();
    }
    None
}

fn javascript_check_server_identity_value_disables_verification(after_marker: &str) -> bool {
    let after = after_marker.trim_start();
    let value = after
        .strip_prefix(':')
        .or_else(|| after.strip_prefix('='))
        .unwrap_or(after)
        .trim_start();
    let compact: String = value.chars().filter(|ch| !ch.is_whitespace()).collect();
    compact.starts_with("()=>undefined")
        || compact.starts_with("()=>null")
        || compact.starts_with("(host,cert)=>undefined")
        || compact.starts_with("(host,cert)=>null")
        || compact.starts_with("function(") && compact.contains("returnnull")
        || compact.starts_with("function") && compact.contains("returnundefined")
        || compact.starts_with("(host,cert){returnnull")
        || compact.starts_with("(host,cert){returnundefined")
}

/// A security-sensitive noun on the line — the value being generated is a secret,
/// so a weak PRNG feeding it is a real CWE-338 issue (not the countless benign
/// `random()` uses for jitter, sampling, or test data that a blanket rule flags).
fn line_has_security_context(line: &str) -> bool {
    let l = line.to_ascii_lowercase();
    const NOUNS: &[&str] = &[
        "token",
        "secret",
        "password",
        "passwd",
        "nonce",
        "salt",
        "session_id",
        "sessionid",
        "csrf",
        "otp",
        "apikey",
        "api_key",
        "private_key",
        "credential",
        "session_key",
        "session_token",
    ];
    NOUNS.iter().any(|n| l.contains(n))
}

/// GF-428 (CWE-338): the column of a non-cryptographic PRNG call used where a
/// secret is being produced. Gated on [`line_has_security_context`] for precision
/// — this is the security-relevant subset of a blanket weak-random rule — and
/// skips the cryptographically-secure variants outright.
fn insecure_random_column(line: &str, language: &str) -> Option<usize> {
    if language == "javascript" && line.len() > 1200 {
        return None;
    }
    if line.contains("secrets.")
        || line.contains("SystemRandom")
        || line.contains("crypto/rand")
        || line.contains("rand.Reader")
        || line.contains("SecureRandom")
        || line.contains("getrandom")
        || line.contains("urandom")
        || line.contains("crypto.randomBytes")
        || line.contains("crypto.getRandomValues")
        || line.contains("getRandomValues")
        || line.contains("randomUUID")
    {
        return None;
    }
    if !line_has_security_context(line) {
        return None;
    }
    let apis: &[&str] = match language {
        "python" => &[
            "random.random(",
            "random.randint(",
            "random.randrange(",
            "random.choice(",
            "random.getrandbits(",
            "random.sample(",
            "random.uniform(",
        ],
        "go" => &[
            "rand.Int(",
            "rand.Intn(",
            "rand.Int31(",
            "rand.Int63(",
            "rand.Float64(",
            "rand.Float32(",
        ],
        "java" => &[
            "new Random(",
            "Math.random(",
            ".nextInt(",
            ".nextLong(",
            ".nextBytes(",
        ],
        "c" | "cpp" => &["rand(", "random(", "srand(", "srandom("],
        "perl" => &["rand("],
        "javascript" => &["Math.random(", "random("],
        _ => return None,
    };
    first_code_call(line, apis)
}

/// GF-422 (CWE-327) for C/C++: a broken/weak cryptographic primitive from a
/// common crypto library (OpenSSL one-shot MD5/SHA1/MD4, DES/RC4, `crypt`). Word
/// boundaries keep `crypt(` off `encrypt(`/`decrypt(` and `MD5(` off `CMD5(`.
fn c_weak_crypto_column(line: &str) -> Option<usize> {
    if line.trim_start().starts_with('#') {
        return None;
    }
    let column = first_code_call(
        line,
        &[
            "MD5(",
            "MD5_Init(",
            "MD4(",
            "SHA1(",
            "SHA1_Init(",
            "DES_set_key",
            "DES_ecb_encrypt",
            "DES_ecb3_encrypt",
            "DES_ede3_cbc_encrypt",
            "RC4(",
            "RC4_set_key",
            "BF_set_key",
            "BF_ecb_encrypt",
            "BF_cbc_encrypt",
            "EVP_md5(",
            "EVP_sha1(",
            "EVP_md4(",
            "EVP_des_ecb(",
            "EVP_des_cbc(",
            "EVP_des_ede3(",
            "EVP_des_ede3_cbc(",
            "EVP_rc4(",
            "EVP_bf_ecb(",
            "EVP_bf_cbc(",
            "crypt(",
        ],
    )?;
    if line[..column].trim_start().starts_with("extern ")
        || c_weak_crypto_declaration_context(line, column)
    {
        return None;
    }
    Some(column)
}

fn c_weak_crypto_declaration_context(line: &str, column: usize) -> bool {
    let before = line[..column].trim_end();
    if before.is_empty()
        || before.contains('{')
        || before.contains('=')
        || before.ends_with('.')
        || before.ends_with("->")
        || before.ends_with(')')
        || before.ends_with(']')
    {
        return false;
    }
    let type_like = before.split_whitespace().any(|token| {
        let token = token
            .trim_matches(|ch: char| ch == '*' || ch == '&' || ch == ':' || ch == '<' || ch == '>');
        matches!(
            token,
            "auto"
                | "bool"
                | "char"
                | "const"
                | "extern"
                | "inline"
                | "int"
                | "long"
                | "short"
                | "signed"
                | "static"
                | "unsigned"
                | "virtual"
                | "void"
                | "uint8_t"
                | "uint16_t"
                | "uint32_t"
                | "uint64_t"
                | "size_t"
        )
    });
    if !type_like {
        return false;
    }
    let Some(close) = call_close_offset(&line[column..]) else {
        return false;
    };
    let rest = line[column + close + 1..].trim_start();
    rest.starts_with(';')
        || rest.starts_with('{')
        || rest.starts_with("const")
        || rest.starts_with("noexcept")
        || rest.starts_with("override")
}

fn call_close_offset(text: &str) -> Option<usize> {
    let (mut in_single, mut in_double, mut escaped) = (false, false, false);
    let mut depth = 0usize;
    let mut saw_open = false;
    for (index, ch) in text.char_indices() {
        if in_single {
            if ch == '\'' && !escaped {
                in_single = false;
            }
            escaped = ch == '\\' && !escaped;
            continue;
        }
        if in_double {
            if ch == '"' && !escaped {
                in_double = false;
            }
            escaped = ch == '\\' && !escaped;
            continue;
        }
        match ch {
            '\'' => in_single = true,
            '"' => in_double = true,
            '(' => {
                saw_open = true;
                depth += 1;
            }
            ')' if saw_open => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(index);
                }
            }
            _ => {}
        }
        escaped = false;
    }
    None
}

/// Emit GF-428 (insecure randomness) if `line` uses a weak PRNG in a secret context.
fn push_insecure_random(
    findings: &mut Vec<StaticFinding>,
    root: &Path,
    path: &Path,
    i: usize,
    line: &str,
    language: &str,
) {
    if let Some(col) = insecure_random_column(line, language) {
        push_pattern(
            findings,
            root,
            path,
            i,
            col + 1,
            "GF-428",
            language,
            "insecure-randomness",
            "Insecure randomness in a security context",
            "crypto",
            "A non-cryptographic PRNG produces a secret (token/key/nonce/salt); use a CSPRNG.",
            line.trim(),
        );
    }
}

/// Emit GF-426 (insecure TLS) if `line` disables TLS verification.
/// GF-548 (CWE-319): column of an insecure `ws://` websocket scheme LITERAL. We
/// require the scheme to open a string literal (`"ws://..."` / `'ws://...'`) so we
/// never fire on an identifier, a `wss://` (TLS) URL — `"wss://"` starts with
/// `"ws` but not `"ws://` because `s` follows — or a URL mentioned in a comment
/// (comments are stripped upstream). Deliberately `ws://`-only: `http://` collides
/// with XML namespaces, schema URLs, and `xmlns` and is too FP-prone to ship.
fn insecure_transport_scheme_column(line: &str) -> Option<usize> {
    line.find("\"ws://")
        .or_else(|| line.find("'ws://"))
        .map(|idx| idx + 2)
}

fn push_insecure_transport(
    findings: &mut Vec<StaticFinding>,
    root: &Path,
    path: &Path,
    i: usize,
    line: &str,
    language: &str,
) {
    if let Some(col) = insecure_transport_scheme_column(line) {
        push_pattern(
            findings,
            root,
            path,
            i,
            col,
            "GF-548",
            language,
            "insecure-transport-scheme",
            "Cleartext transport scheme in a connection endpoint",
            "transport",
            "A ws:// websocket endpoint sends data in cleartext; use wss:// (TLS).",
            line.trim(),
        );
    }
}

fn push_insecure_tls(
    findings: &mut Vec<StaticFinding>,
    root: &Path,
    path: &Path,
    i: usize,
    line: &str,
    language: &str,
) {
    if let Some(col) = insecure_tls_column(line, language) {
        push_pattern(
            findings,
            root,
            path,
            i,
            col,
            "GF-426",
            language,
            "insecure-tls-verification",
            "TLS certificate/hostname verification disabled",
            "tls",
            "Disabling certificate/hostname checks defeats TLS; verify against a trusted CA.",
            line.trim(),
        );
    }
}

fn scan_perl(root: &Path, path: &Path, source: &str, findings: &mut Vec<StaticFinding>) {
    let suppress_generic_hardcoded_secret = generic_hardcoded_secret_fixture_path(path);
    for (i, line) in source.lines().enumerate() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        push_insecure_random(findings, root, path, i, line, "perl");
        push_insecure_transport(findings, root, path, i, line, "perl");
        // CWE-78: shell execution. Backticks, system/exec with a string, qx//,
        // and a piped 2-arg open (`open(FH, "cmd|")` / `open(FH, "|cmd")`).
        if let Some(col) = perl_backtick_command_column(line)
            .or_else(|| perl_shell_call_column(line))
            .or_else(|| perl_piped_open_shell_column(line))
        {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-404",
                "perl",
                "command-injection-nonliteral-arg",
                "Shell execution in Perl (backticks/system/exec/qx/piped open)",
                "call",
                "The construct runs a shell command; interpolated input enables command injection.",
                t,
            );
        }
        // CWE-94: string eval (not block eval `eval {`).
        if let Some(col) = perl_string_eval_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-420",
                "perl",
                "code-injection-dynamic-eval",
                "String eval of Perl code",
                "call",
                "eval on a string executes arbitrary code.",
                t,
            );
        }
        // CWE-327: weak crypto (Digest::MD5 / Digest::SHA1 and their functional
        // shortcuts md5_hex/sha1_hex).
        if let Some(col) = first_code_match(
            line,
            &[
                "Digest::MD5",
                "Digest::SHA1",
                "Digest::HMAC_MD5",
                "md5_hex(",
                "md5_base64(",
                "sha1_hex(",
                "sha1_base64(",
            ],
        ) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-422",
                "perl",
                "weak-cryptography",
                "Weak cryptographic primitive in Perl (MD5/SHA1)",
                "crypto",
                "Broken/weak digest; use Digest::SHA (SHA-256+).",
                t,
            );
        }
        // CWE-798: hardcoded secret.
        if !suppress_generic_hardcoded_secret {
            if let Some(col) = hardcoded_secret_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-423",
                    "perl",
                    "hardcoded-credential",
                    "Hardcoded credential/secret",
                    "secret",
                    "A secret is a string literal; load it at runtime.",
                    t,
                );
            }
        }
    }
}

/// `system(`/`exec(`/`qx{|/|(` shell call whose argument is not a pure literal
/// list of separate args.
fn perl_shell_call_column(line: &str) -> Option<usize> {
    for kw in ["system(", "exec("] {
        if let Some(at) = find_code_match(line, kw) {
            let prev = line[..at].chars().next_back();
            if prev.is_none_or(|c| !c.is_alphanumeric() && c != '_')
                && perl_system_exec_args_are_shell_string(&line[at + kw.len()..])
            {
                return Some(at);
            }
        }
    }
    // Unambiguous quote-like forms.
    for kw in ["qx(", "qx{", "qx/", "qx|"] {
        if let Some(at) = find_code_match(line, kw) {
            let prev = line[..at].chars().next_back();
            if prev.is_none_or(|c| !c.is_alphanumeric() && c != '_') {
                return Some(at);
            }
        }
    }
    // The space forms `system `/`exec ` must be followed by a genuine argument
    // starter — a quote, variable, list, block, or backtick — not an English
    // word, so heredoc/comment prose ("uses a system call", "exec path") is not
    // mistaken for a shell invocation.
    for kw in ["system ", "exec "] {
        if let Some(at) = find_code_match(line, kw) {
            let prev = line[..at].chars().next_back();
            let is_word_boundary = prev.is_none_or(|c| !c.is_alphanumeric() && c != '_');
            let arg = line[at + kw.len()..].trim_start();
            if is_word_boundary && arg.starts_with(['"', '\'', '$', '(', '@', '{', '`']) {
                return Some(at);
            }
        }
    }
    None
}

fn perl_system_exec_args_are_shell_string(text: &str) -> bool {
    let args = split_perl_call_args(text);
    if args.len() != 1 {
        return false;
    }
    let arg = args[0].trim();
    !perl_arg_is_plain_literal(arg) || perl_double_quoted_arg_interpolates(arg)
}

fn perl_arg_is_plain_literal(arg: &str) -> bool {
    trim_perl_string_literal(arg).is_some()
}

fn perl_double_quoted_arg_interpolates(arg: &str) -> bool {
    arg.strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .is_some_and(|value| value.contains('$') || value.contains('@') || value.contains('`'))
}

fn perl_piped_open_shell_column(line: &str) -> Option<usize> {
    let at = find_code_match(line, "open(")?;
    let previous = line[..at].chars().next_back();
    if previous.is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == '_') {
        return None;
    }
    let args = split_perl_call_args(&line[at + "open(".len()..]);
    if args.len() != 2 {
        return None;
    }
    let mode = trim_perl_string_literal(args[1].trim())?;
    if mode == "-|" || mode == "|-" {
        return None;
    }
    (mode.starts_with('|') || mode.ends_with('|')).then_some(at)
}

fn split_perl_call_args(text: &str) -> Vec<String> {
    let mut args = Vec::new();
    let mut current = String::new();
    let mut depth = 0i32;
    let (mut in_single, mut in_double, mut escaped) = (false, false, false);
    for ch in text.chars() {
        if in_single {
            current.push(ch);
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '\'' {
                in_single = false;
            }
            continue;
        }
        if in_double {
            current.push(ch);
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_double = false;
            }
            continue;
        }
        match ch {
            '\'' => {
                in_single = true;
                current.push(ch);
            }
            '"' => {
                in_double = true;
                current.push(ch);
            }
            '(' | '[' | '{' => {
                depth += 1;
                current.push(ch);
            }
            ')' if depth == 0 => {
                args.push(current.trim().to_owned());
                return args;
            }
            ')' | ']' | '}' => {
                depth = (depth - 1).max(0);
                current.push(ch);
            }
            ',' if depth == 0 => {
                args.push(current.trim().to_owned());
                current.clear();
            }
            _ => current.push(ch),
        }
    }
    if !current.trim().is_empty() {
        args.push(current.trim().to_owned());
    }
    args
}

fn trim_perl_string_literal(text: &str) -> Option<&str> {
    text.strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .or_else(|| {
            text.strip_prefix('\'')
                .and_then(|value| value.strip_suffix('\''))
        })
}

/// The column of a Perl backtick command substitution, ignoring a backtick that
/// appears inside a single- or double-quoted string (`croak "name `$x'"`), which
/// is not command execution.
fn perl_backtick_command_column(line: &str) -> Option<usize> {
    let mut in_single = false;
    let mut in_double = false;
    let mut prev_backslash = false;
    for (i, ch) in line.char_indices() {
        match ch {
            '\'' if !in_double && !prev_backslash => in_single = !in_single,
            '"' if !in_single && !prev_backslash => in_double = !in_double,
            '`' if !in_single && !in_double && !perl_backtick_inside_regex_literal(line, i) => {
                return Some(i);
            }
            _ => {}
        }
        prev_backslash = ch == '\\' && !prev_backslash;
    }
    None
}

fn perl_backtick_inside_regex_literal(line: &str, index: usize) -> bool {
    let before = &line[..index];
    let op = [before.rfind("=~"), before.rfind("!~")]
        .into_iter()
        .flatten()
        .max();
    let Some(op) = op else {
        return false;
    };
    if line[op + 2..index].contains(';') {
        return false;
    }
    let tail = &line[op + 2..];
    let expr_start = op + 2 + tail.len() - tail.trim_start().len();
    let expr = &line[expr_start..];

    if expr.starts_with("qr") {
        return perl_regex_body_contains(line, index, expr_start + 2);
    }
    if expr.starts_with('s') {
        let open = expr_start + 1;
        let Some((pattern_start, after_pattern)) = perl_regex_delimited_span(line, open) else {
            return false;
        };
        if pattern_start <= index && index < after_pattern {
            return true;
        }
        return perl_regex_body_contains(line, index, after_pattern - 1);
    }
    if expr.starts_with('m') {
        return perl_regex_body_contains(line, index, expr_start + 1);
    }
    perl_regex_body_contains(line, index, expr_start)
}

fn perl_regex_body_contains(line: &str, index: usize, open: usize) -> bool {
    perl_regex_delimited_span(line, open).is_some_and(|(start, end)| start <= index && index < end)
}

fn perl_regex_delimited_span(line: &str, open: usize) -> Option<(usize, usize)> {
    let delimiter = line[open..].chars().next()?;
    if delimiter.is_ascii_alphanumeric() || delimiter.is_ascii_whitespace() {
        return None;
    }
    let mut escaped = false;
    for (relative, ch) in line[open + delimiter.len_utf8()..].char_indices() {
        let absolute = open + delimiter.len_utf8() + relative;
        if ch == delimiter && !escaped {
            return Some((open, absolute + delimiter.len_utf8()));
        }
        escaped = ch == '\\' && !escaped;
        if ch != '\\' {
            escaped = false;
        }
    }
    None
}

fn perl_string_eval_column(line: &str) -> Option<usize> {
    let at = find_code_match(line, "eval")?;
    let after = line[at + 4..].trim_start();
    // Block eval `eval { ... }` is exception handling, not code injection.
    if after.starts_with('{') {
        return None;
    }
    (after.starts_with('"')
        || after.starts_with('\'')
        || after.starts_with('$')
        || after.starts_with('('))
    .then_some(at)
}

fn scan_go(root: &Path, path: &Path, source: &str, findings: &mut Vec<StaticFinding>) {
    let suppress_generic_hardcoded_secret = generic_hardcoded_secret_fixture_path(path);
    for (i, line) in source.lines().enumerate() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        push_insecure_tls(findings, root, path, i, line, "go");
        push_insecure_transport(findings, root, path, i, line, "go");
        push_insecure_random(findings, root, path, i, line, "go");
        for cookie in insecure_sensitive_cookie_flag_matches(line, "go") {
            push_pattern(
                findings,
                root,
                path,
                i,
                cookie.column,
                cookie.rule_id,
                "go",
                cookie.slug,
                cookie.message,
                "cookie",
                cookie.detail,
                t,
            );
        }
        // CWE-78: exec a shell.
        if let Some(col) = first_code_match(line, &["exec.Command", "exec.CommandContext"]) {
            if line.contains("\"sh\"")
                || line.contains("\"bash\"")
                || line.contains("\"-c\"")
                || line.contains("\"cmd\"")
            {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-404",
                    "go",
                    "command-injection-nonliteral-arg",
                    "Shell command execution in Go (exec.Command with a shell)",
                    "call",
                    "Running a shell with a built argument enables command injection.",
                    t,
                );
            }
        }
        // CWE-89: SQL query built from non-literal input (database/sql).
        if first_code_match(
            line,
            &[
                ".Query(",
                ".QueryRow(",
                ".QueryContext(",
                ".Exec(",
                ".ExecContext(",
            ],
        )
        .is_some()
            && has_dynamic_string(line)
            && line_has_sql_keyword(line)
        {
            let col = find_code_match(line, ".Query")
                .or_else(|| find_code_match(line, ".Exec"))
                .unwrap_or(0)
                + 1;
            push_pattern(
                findings,
                root,
                path,
                i,
                col,
                "GF-419",
                "go",
                "sql-injection-dynamic-query",
                "SQL query built from non-literal input in Go",
                "sql",
                "A concatenated SQL string is executed; use parameterized queries ($1, ?).",
                t,
            );
        }
        // CWE-22: file open on a non-literal path.
        if let Some(col) = first_code_match(
            line,
            &[
                "os.Open(",
                "os.OpenFile(",
                "os.ReadFile(",
                "ioutil.ReadFile(",
                "os.Create(",
            ],
        ) {
            let arg = &line[col..];
            let literal = arg
                .split('(')
                .nth(1)
                .is_some_and(|a| a.trim_start().starts_with('"'));
            if !literal {
                push_pattern(findings, root, path, i, col + 1, "GF-405", "go", "path-controlled-file-open",
                    "File opened from a non-literal path in Go", "file_open",
                    "A non-literal path reaches a file API; treat as path traversal until sanitized.", t);
            }
        }
        // CWE-327: weak crypto.
        if let Some(col) = go_weak_crypto_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-422",
                "go",
                "weak-cryptography",
                "Weak cryptographic primitive in Go (md5/sha1/DES/3DES/RC4/Blowfish)",
                "crypto",
                "Broken/weak primitive; use sha256/AES-GCM.",
                t,
            );
        }
        // CWE-798: hardcoded secret.
        if !suppress_generic_hardcoded_secret {
            if let Some(col) = hardcoded_secret_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-423",
                    "go",
                    "hardcoded-credential",
                    "Hardcoded credential/secret",
                    "secret",
                    "A secret is a string literal; load it at runtime.",
                    t,
                );
            }
        }
    }
}

/// GF-552 (CWE-843): the column of an `std::mem::transmute`/`transmute_copy`
/// call, matched string- and comment-free so a mention in a doc-comment or a
/// string literal never fires. `transmute` reinterprets one type's bits as
/// another — a type-confusion primitive that is near-always review-worthy, so a
/// call-site hit is high-signal and rare (low false-positive). Matches the
/// path-qualified forms (`std::mem::transmute`, `mem::transmute`), the
/// turbofish (`transmute::<`), and `transmute_copy`, requiring a word boundary
/// so it never fires inside a longer identifier.
fn rust_transmute_column(line: &str) -> Option<usize> {
    for needle in ["transmute::<", "transmute_copy(", "transmute("] {
        if let Some(col) = find_code_call(line, needle) {
            return Some(col);
        }
    }
    None
}

/// True for Rust source that is not library code — test/example/benchmark
/// trees, or `build.rs`. GF-553 (panic-in-library) is scoped to library source
/// only, because a panic in a test or a build script is not an attacker-facing
/// denial-of-service.
fn rust_non_library_path(path: &Path) -> bool {
    let is_test_dir = path.components().any(|component| {
        let part = component.as_os_str().to_string_lossy().to_ascii_lowercase();
        matches!(
            part.as_str(),
            "tests" | "test" | "examples" | "example" | "benches" | "benchmark" | "benchmarks"
        )
    });
    let file = path
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| name.to_ascii_lowercase())
        .unwrap_or_default();
    is_test_dir
        || file == "build.rs"
        || file.ends_with("_test.rs")
        || file.ends_with("_tests.rs")
        || file.ends_with("_bench.rs")
}

/// GF-553 (CWE-248): the column of an `.unwrap()`/`.expect(...)` that is
/// applied to the result of a fallible boundary — a lock, a parse, an IO/channel
/// read/write, or an env lookup. Scoping to these receivers (rather than every
/// `.unwrap()`) is what keeps the finding precise: a blanket unwrap rule
/// FP-storms, which is exactly why clippy's `unwrap_used` is allow-by-default.
/// The receiver token must appear string-free before the terminal
/// `.unwrap()`/`.expect(`.
fn rust_fallible_unwrap_column(line: &str) -> Option<usize> {
    // The fallible boundaries whose failure is genuinely runtime-dependent
    // (poison, malformed input, short read, missing var) rather than a
    // developer-established invariant.
    const BOUNDARIES: &[&str] = &[
        ".lock()",
        ".read()",
        ".write()",
        ".try_lock()",
        ".recv()",
        ".send(",
        ".parse()",
        ".parse::<",
        "::from_str(",
        ".read_to_string(",
        ".read_to_end(",
        ".read_line(",
        "::var(",
        "::var_os(",
    ];
    let terminal = first_code_match(line, &[".unwrap()", ".expect("])?;
    // The boundary call must precede the terminal unwrap/expect on the line.
    let boundary = BOUNDARIES
        .iter()
        .filter_map(|b| find_code_match(line, b))
        .filter(|&col| col < terminal)
        .min()?;
    // Suppress `"literal".parse().unwrap()` / `.parse::<T>()` on a constant string
    // literal: the parsed value is developer-controlled and cannot fail from
    // attacker input, so it is not the runtime-DoS boundary the rule targets.
    let boundary_is_parse = line[boundary..].starts_with(".parse()")
        || line[boundary..].starts_with(".parse::<")
        || line[boundary..].starts_with("::from_str(");
    if boundary_is_parse && line[..boundary].trim_end().ends_with('"') {
        return None;
    }
    Some(boundary)
}

fn scan_rust(root: &Path, path: &Path, source: &str, findings: &mut Vec<StaticFinding>) {
    // Deliberately thin — clippy covers most Rust; defer breadth to the clippy
    // adapter. Flag only high-signal shell exec + hardcoded secrets.
    let suppress_generic_hardcoded_secret = generic_hardcoded_secret_fixture_path(path);
    // GF-553 fires only in library source, and only outside `#[cfg(test)]`
    // modules / `#[test]` functions (tracked by brace depth below).
    let scan_panic_in_library = !rust_non_library_path(path);
    let mut cfg_test_depth: Option<usize> = None;
    let mut brace_depth: usize = 0;
    for (i, line) in source.lines().enumerate() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        if scan_panic_in_library {
            // Enter a test region when a `#[cfg(test)]`/`#[test]` attribute is
            // seen; leave it once the brace depth returns below the entry depth.
            if cfg_test_depth.is_none()
                && (t.contains("#[cfg(test)]")
                    || t.starts_with("#[test]")
                    || t.contains("#[tokio::test")
                    || t.contains("#[rstest"))
            {
                cfg_test_depth = Some(brace_depth);
            }
            let opens = line.matches('{').count();
            let closes = line.matches('}').count();
            let in_test_region = cfg_test_depth.is_some();
            if !in_test_region && !line.contains("fn main(") {
                if let Some(col) = rust_fallible_unwrap_column(line) {
                    push_pattern(
                        findings,
                        root,
                        path,
                        i,
                        col + 1,
                        "GF-553",
                        "rust",
                        "rust-panic-in-library",
                        "unwrap/expect panics on a fallible boundary in library code",
                        "call",
                        "A fallible boundary (lock/parse/IO/env) is unwrapped in library code; failure panics as a denial-of-service.",
                        t,
                    );
                }
            }
            brace_depth = brace_depth.saturating_add(opens);
            brace_depth = brace_depth.saturating_sub(closes.min(brace_depth));
            if let Some(entry) = cfg_test_depth {
                if brace_depth <= entry && closes > 0 {
                    cfg_test_depth = None;
                }
            }
        }
        push_insecure_tls(findings, root, path, i, line, "rust");
        if let Some(col) = rust_weak_crypto_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-422",
                "rust",
                "weak-cryptography",
                "Weak cryptographic primitive in Rust (md5/sha1/DES/RC4/Blowfish/ECB)",
                "crypto",
                "Broken/weak primitive; use sha2/AES-GCM or a modern KDF.",
                t,
            );
        }
        if let Some(col) = rust_transmute_column(line) {
            push_pattern(
                findings,
                root,
                path,
                i,
                col + 1,
                "GF-552",
                "rust",
                "unsafe-transmute",
                "Unsafe transmute reinterprets one type's bits as another",
                "call",
                "transmute is a type-confusion primitive; verify the layouts are identical and the reinterpretation is sound.",
                t,
            );
        }
        if let Some(col) = find_code_match(line, "Command::new(") {
            // Only the shell interpreters `sh`/`bash` — NOT `"cmd"`, which collides
            // with clap's `Command::new("cmd")` app builder (a CLI arg parser, not
            // std::process) and produced a false-positive storm on clap-based CLIs.
            if line.contains("\"sh\"") || line.contains("\"bash\"") {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-404",
                    "rust",
                    "command-injection-nonliteral-arg",
                    "Shell process spawn in Rust (Command::new(\"sh\"/\"bash\"))",
                    "call",
                    "Spawning a shell with a built argument enables command injection.",
                    t,
                );
            }
        }
        if !suppress_generic_hardcoded_secret {
            if let Some(col) = hardcoded_secret_column(line) {
                push_pattern(
                    findings,
                    root,
                    path,
                    i,
                    col + 1,
                    "GF-423",
                    "rust",
                    "hardcoded-credential",
                    "Hardcoded credential/secret",
                    "secret",
                    "A secret is a string literal; load it at runtime.",
                    t,
                );
            }
        }
    }
}

