    #[test]
    fn insecure_ws_transport_scheme_is_flagged() {
        // Positive: a ws:// endpoint literal in each supported language.
        for lang in ["python", "go", "javascript", "java", "perl"] {
            let pos = scan_lang_rules(lang, "url = \"ws://example.com/socket\"\n");
            assert_eq!(pos, vec!["GF-548"], "no ws:// finding for {lang}");
        }
        // Negatives: wss:// (TLS), an http:// namespace/URL (we ship ws://-only),
        // a ws:// in a comment (stripped), and the substring `ws` not as a scheme.
        let neg = scan_lang_rules(
            "python",
            "a = \"wss://example.com/socket\"\n\
             ns = \"http://www.w3.org/2001/XMLSchema\"\n\
             note = \"connect ws later\"\n\
             draws = compute()\n\
             # ws://commented.example.com\n",
        );
        assert!(neg.is_empty(), "ws:// transport false positives: {neg:?}");
    }

    #[test]
    fn c_unbounded_scanf_gets_is_flagged() {
        // Positives: bare %s, %[ class, suppression-then-real %s, fscanf/sscanf
        // format at arg index 1, and getwd (no size bound).
        let pos = scan_c_family_path_rules(
            "/t/read.c",
            "scanf(\"%s\", buf);\n\
             scanf(\"%[^\\n]\", buf);\n\
             fscanf(f, \"%d %s\", &n, buf);\n\
             sscanf(s, \"%s\", buf);\n\
             getwd(cwd);\n",
            "c",
        );
        assert_eq!(pos, vec!["GF-547", "GF-547", "GF-547", "GF-547", "GF-547"]);

        // Negatives: width-bounded %s and %[, suppressed conversion (%*s stores
        // nothing), no string conversion at all, a scanf mentioned in a string
        // literal, and getcwd (the safe replacement — must not match getwd needle).
        let neg = scan_c_family_path_rules(
            "/t/read.c",
            "scanf(\"%31s\", buf);\n\
             scanf(\"%15[^\\n]\", buf);\n\
             scanf(\"%*s\", );\n\
             scanf(\"%d\", &n);\n\
             const char *doc = \"call scanf(\\\"%s\\\") is unsafe\";\n\
             getcwd(cwd, sizeof(cwd));\n",
            "c",
        );
        assert!(neg.is_empty(), "scanf/gets false positives: {neg:?}");
    }

    #[test]
    fn c_printf_arg_type_mismatch_is_flagged() {
        // Positives: %s paired with a numeric literal (decimal/hex/char), and an
        // integer conversion (%d/%u/%i/%x/%ld) paired with a string literal.
        // Every pairing is provably wrong regardless of any surrounding types.
        let pos = scan_c_family_path_rules(
            "/t/fmt.c",
            "printf(\"%s\", 5);\n\
             printf(\"val=%s\", 0x10);\n\
             printf(\"%d\", \"hello\");\n\
             fprintf(stderr, \"%u\", \"x\");\n\
             snprintf(buf, n, \"%ld\", \"y\");\n\
             printf(\"%s\", 'a');\n",
            "c",
        );
        let pos: Vec<&String> = pos.iter().filter(|id| *id == "GF-554").collect();
        assert_eq!(pos, vec!["GF-554"; 6]);

        // Negatives that MUST NOT fire: a variable/expression arg (unknown type),
        // matching numeric conversion + numeric arg, a `%%` literal percent, a
        // string conversion + string literal, a `%*d` width consuming the int arg,
        // a `%.*s` precision arg, and a call inside a string literal.
        let neg = scan_c_family_path_rules(
            "/t/fmt.c",
            "printf(\"%s\", name);\n\
             printf(\"%d\", n);\n\
             printf(\"%d%%\", n);\n\
             printf(\"%s\", \"literal\");\n\
             printf(\"%*d\", width, n);\n\
             printf(\"%.*s\", len, p);\n\
             printf(\"%s\", get_name());\n\
             const char *doc = \"printf(\\\"%s\\\", 5) is an example\";\n",
            "c",
        );
        let neg: Vec<&String> = neg.iter().filter(|id| *id == "GF-554").collect();
        assert!(neg.is_empty(), "printf arg-type false positives: {neg:?}");
    }

