    #[test]
    fn javascript_rule_pack_flags_child_process_exec_dynamic_commands() {
        let pos = scan_lang_rules(
            "javascript",
            "const cp = require('child_process');\nconst child_process = require('node:child_process');\nconst { execSync, exec: run } = require('child_process');\nimport { exec as importedExec } from 'node:child_process';\ncp.exec(`convert ${req.query.file}`);\nexecSync('git checkout ' + branch);\nchild_process.exec(command);\nrun(command);\nimportedExec(command);\nchild_process.execFile('git', ['status']);\n",
        );
        assert_eq!(pos, vec!["GF-505", "GF-505", "GF-505", "GF-505", "GF-505"]);
        let neg = scan_lang_rules(
            "javascript",
            "exec('git status');\nchild_process.exec(command);\nconst m = /^perm:(allow|deny):([a-z]{5})$/.exec(interaction.customId);\nconst result = pattern.exec(content);\nconst execFile = require('child_process').execFile;\nexecFile(cmd, args);\nconst execSync = require('child_process').execSync;\nexecSync(path.join(__dirname, 'whitespace-async.js'));\nimport { execFile as runFile } from 'child_process';\nrunFile(cmd, args);\nexecFile('git', ['status']);\nspawn('git', ['status']);\nconst text = 'child_process.exec(userInput)';\n",
        );
        assert!(neg.is_empty(), "javascript false positives: {neg:?}");
    }

