    #[test]
    fn javascript_rule_pack_flags_hapi_protoaction_ignore() {
        let pos = scan_lang_rules(
            "javascript",
            "const Hapi = require('@hapi/hapi');\n\
             import * as HapiNs from '@hapi/hapi';\n\
             const server = Hapi.server({ routes: { payload: { protoAction: 'ignore' } } });\n\
             const app = HapiNs.server();\n\
             const unsafePayload = { protoAction: 'ignore' };\n\
             const unsafeRouteOptions = { payload: unsafePayload };\n\
             server.route({ method: 'POST', path: '/a', options: { payload: { protoAction: 'ignore' }, handler } });\n\
             server.route({ method: 'POST', path: '/b', config: unsafeRouteOptions, handler });\n\
             app.route([{ method: 'POST', path: '/c', options: { payload: unsafePayload, handler } }]);\n\
             new Hapi.Server({ routes: { payload: { protoAction: 'ignore' } } });\n",
        );
        assert_eq!(pos, vec!["GF-509", "GF-509", "GF-509", "GF-509", "GF-509"]);

        let neg = scan_lang_rules(
            "javascript",
            "const Hapi = require('@hapi/hapi');\n\
             const server = Hapi.server({ routes: { payload: { protoAction: 'error' } } });\n\
             Hapi.server({ routes: { payload: { protoAction: 'remove' } } });\n\
             server.route({ method: 'POST', path: '/a', options: { payload: { protoAction: 'remove' }, handler } });\n\
             const safePayload = { protoAction: 'error' };\n\
             server.route({ method: 'POST', path: '/b', options: { payload: safePayload, handler } });\n\
             notHapi.server({ routes: { payload: { protoAction: 'ignore' } } });\n\
             const text = \"payload: { protoAction: 'ignore' }\";\n",
        );
        assert!(neg.is_empty(), "hapi protoAction false positives: {neg:?}");
    }

