    #[test]
    fn javascript_rule_pack_scans_vue_and_svelte_raw_html_templates() {
        let root = temp_dir("javascript-framework-raw-html");
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(
            root.join("src/Profile.vue"),
            "<template><section v-html=\"req.query.bio\"></section></template>\n",
        )
        .unwrap();
        fs::write(
            root.join("src/Post.svelte"),
            "<script>export let req;</script>\n<article>{@html req.body.post}</article>\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::from(["GF-512".to_owned()]),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let ids: Vec<_> = report.findings.iter().map(|f| f.rule_id.as_str()).collect();
        assert_eq!(
            ids,
            vec!["GF-512", "GF-512"],
            "Vue v-html and Svelte @html should be scanned as JavaScript XSS sinks"
        );
    }

