    #[test]
    fn javascript_rule_pack_flags_multer_memory_uploads_without_limits() {
        let pos = scan_lang_rules(
            "javascript",
            "const multer = require('multer');\n\
             import multerDefault from 'multer';\n\
             const upload = multer();\n\
             const uploadMemory = multer({ storage: multer.memoryStorage() });\n\
             const memoryStorage = multer.memoryStorage();\n\
             const uploadAlias = multer({ storage: memoryStorage });\n\
             const storage = multer.memoryStorage();\n\
             const shorthandStorageUpload = multer({ storage });\n\
             const unsafeOptions = { storage: multer.memoryStorage() };\n\
             const uploadFromOptions = multer(unsafeOptions);\n\
             upload.single('avatar');\n\
             uploadMemory.array('photos', 5);\n\
             uploadAlias.fields([{ name: 'avatar', maxCount: 1 }]);\n\
             shorthandStorageUpload.single('avatar');\n\
             uploadFromOptions.any();\n\
             multerDefault().single('document');\n\
             require('multer')({ storage: require('multer').memoryStorage() }).single('file');\n",
        );
        assert_eq!(
            pos,
            vec!["GF-436", "GF-436", "GF-436", "GF-436", "GF-436", "GF-436", "GF-436"]
        );

        let neg = scan_lang_rules(
            "javascript",
            "const multer = require('multer');\n\
             import multerDefault from 'multer';\n\
             const safeMemory = multer({ storage: multer.memoryStorage(), limits: { fileSize: 1024 * 1024 } });\n\
             const safeOptions = { storage: multer.memoryStorage(), limits: { fileSize: MAX_UPLOAD_BYTES } };\n\
             const safeFromOptions = multer(safeOptions);\n\
             const fileSize = maxBytes;\n\
             const shorthandLimits = { fileSize };\n\
             const safeShorthandLimits = multer({ storage: multer.memoryStorage(), limits: shorthandLimits });\n\
             const limits = { fileSize: maxBytes };\n\
             const safeLimitsShorthand = multer({ storage: multer.memoryStorage(), limits });\n\
             const diskUpload = multer({ dest: 'uploads/' });\n\
             const dest = 'uploads/';\n\
             const destShorthandUpload = multer({ dest });\n\
             const diskStorage = multer.diskStorage({ destination: '/tmp' });\n\
             const diskStorageUpload = multer({ storage: diskStorage });\n\
             const storage = multer.diskStorage({ destination: '/tmp' });\n\
             const shorthandDiskStorageUpload = multer({ storage });\n\
             const customStorageUpload = multer({ storage: customStorage });\n\
             const inlineDiskStorageUpload = multer({ storage: multer.diskStorage({ filename: cb }) });\n\
             const textOnly = multer();\n\
             safeMemory.single('avatar');\n\
             safeFromOptions.array('photos', 5);\n\
             safeShorthandLimits.single('avatar');\n\
             safeLimitsShorthand.single('avatar');\n\
             diskUpload.single('avatar');\n\
             destShorthandUpload.single('avatar');\n\
             diskStorageUpload.single('avatar');\n\
             shorthandDiskStorageUpload.single('avatar');\n\
             customStorageUpload.single('avatar');\n\
             inlineDiskStorageUpload.single('avatar');\n\
             textOnly.none();\n\
             notMulter({ storage: multer.memoryStorage() }).single('avatar');\n\
             multerDefault({ limits: { fileSize: maxBytes } }).single('avatar');\n\
             const text = \"multer({ storage: multer.memoryStorage() }).single('file')\";\n",
        );
        assert!(
            neg.is_empty(),
            "javascript multer memory upload false positives: {neg:?}"
        );
    }

    #[test]
    fn javascript_rule_pack_flags_static_dotfiles_allow() {
        let pos = scan_lang_rules(
            "javascript",
            "const express = require('express');\n\
             const serveStatic = require('serve-static');\n\
             import expressDefault from 'express';\n\
             import staticFiles from 'serve-static';\n\
             const allowDotfiles = { dotfiles: 'allow' };\n\
             const legacyHidden = { hidden: true };\n\
             app.use(express.static('public', { dotfiles: 'allow' }));\n\
             app.use(expressDefault.static('assets', allowDotfiles));\n\
             app.use(serveStatic('public', { dotfiles: \"allow\" }));\n\
             app.use(staticFiles('public', legacyHidden));\n\
             app.use(require('serve-static')('public', { dotfiles: `allow` }));\n\
             app.use(require('express').static('public', { hidden: true }));\n",
        );
        assert_eq!(
            pos,
            vec!["GF-519", "GF-519", "GF-519", "GF-519", "GF-519", "GF-519"]
        );

        let neg = scan_lang_rules(
            "javascript",
            "const express = require('express');\n\
             const serveStatic = require('serve-static');\n\
             app.use(express.static('public'));\n\
             app.use(express.static('public', { dotfiles: 'ignore' }));\n\
             app.use(serveStatic('public', { dotfiles: 'deny' }));\n\
             app.use(express.static('public', { hidden: false }));\n\
             app.use(notExpress.static('public', { dotfiles: 'allow' }));\n\
             const text = \"express.static('public', { dotfiles: 'allow' })\";\n",
        );
        assert!(
            neg.is_empty(),
            "javascript static dotfile false positives: {neg:?}"
        );
    }

