    #[test]
    fn java_rule_pack_flags_jndi_injection_nonliteral_lookup() {
        // Positives: a JNDI lookup whose name is NOT a string literal (the
        // Log4Shell class) — a variable, a concatenation, an inline
        // `new InitialContext()`/`new InitialDirContext(...)`, or a method call.
        let pos = scan_lang_rules(
            "java",
            "import javax.naming.InitialContext;\n\
             import javax.naming.directory.InitialDirContext;\n\
             class J {\n\
             \x20\x20void a(InitialContext ctx, String u) throws Exception { ctx.lookup(u); }\n\
             \x20\x20void b(String u) throws Exception { new InitialContext().lookup(u); }\n\
             \x20\x20void c(String p) throws Exception { new InitialDirContext(env).lookup(\"ldap://\" + p); }\n\
             \x20\x20void d(Context c, String u) throws Exception { c.lookup(\"java:\" + u); }\n\
             \x20\x20void e(DirContext c) throws Exception { c.lookup(req.getHeader(\"x\")); }\n\
             }\n",
        );
        assert_eq!(pos, vec!["GF-551", "GF-551", "GF-551", "GF-551", "GF-551"]);

        // Negatives: a lookup with a STRING-LITERAL name is the safe,
        // developer-controlled common case and must NOT fire; a `.lookup(` on a
        // non-Context type must not fire either.
        let neg = scan_lang_rules(
            "java",
            "import javax.naming.InitialContext;\n\
             class J {\n\
             \x20\x20void a(InitialContext ctx) throws Exception { ctx.lookup(\"java:comp/env/jdbc/DB\"); }\n\
             \x20\x20void b() throws Exception { new InitialContext().lookup(\"java:comp/env/x\"); }\n\
             \x20\x20Object c(java.util.Map<String,Object> map, String u) { return map.lookup(u); }\n\
             }\n",
        );
        assert!(neg.is_empty(), "java JNDI false positives: {neg:?}");
    }

