    #[test]
    fn config_files_are_supported_static_scan_inputs() {
        for name in [
            "application.properties",
            "application.yml",
            "application.yaml",
            "Dockerfile",
            "build.Dockerfile",
            "main.tf",
            "app.js",
            "app.ts",
            "component.jsx",
            "component.tsx",
            "Profile.vue",
            "Post.svelte",
            "Main.qml",
        ] {
            let path = Path::new(name);
            assert!(is_supported_file(path), "{name} should be walked");
            let expected_language = if matches!(
                path.extension().and_then(|ext| ext.to_str()),
                Some("js" | "jsx" | "ts" | "tsx" | "vue" | "svelte")
            ) {
                Some("javascript")
            } else if matches!(path.extension().and_then(|ext| ext.to_str()), Some("qml")) {
                Some("qml")
            } else {
                Some("config")
            };
            assert_eq!(
                language_for_path_and_source(path, ""),
                expected_language,
                "{name} should use expected scanner"
            );
        }
    }

    #[test]
    fn cors_wildcard_with_credentials_is_flagged() {
        let python = scan_lang_rules(
            "python",
            "CORS(app, origins=\"*\", supports_credentials=True)\napp.add_middleware(CORSMiddleware, allow_origins=[\"*\"], allow_credentials=True)\nCORS_ALLOW_ALL_ORIGINS = True\nCORS_ALLOW_CREDENTIALS = True\n",
        );
        assert_eq!(python, vec!["GF-439", "GF-439", "GF-439"]);

        let python_neg = scan_lang_rules(
            "python",
            "CORS(app, origins=[\"https://app.example\"], supports_credentials=True)\napp.add_middleware(CORSMiddleware, allow_origins=[\"*\"], allow_credentials=False)\nCORS_ALLOW_ALL_ORIGINS = False\nCORS_ALLOW_CREDENTIALS = True\n",
        );
        assert!(
            python_neg.is_empty(),
            "python cors false positives: {python_neg:?}"
        );

        let java = scan_lang_rules(
            "java",
            "@CrossOrigin(origins = \"*\", allowCredentials = \"true\")\nregistry.addMapping(\"/**\").allowedOrigins(\"*\").allowCredentials(true);\n",
        );
        assert_eq!(java, vec!["GF-439", "GF-439"]);

        let java_neg = scan_lang_rules(
            "java",
            "@CrossOrigin(origins = \"https://app.example\", allowCredentials = \"true\")\nregistry.addMapping(\"/**\").allowedOrigins(\"*\");\n",
        );
        assert!(
            java_neg.is_empty(),
            "java cors false positives: {java_neg:?}"
        );

        let javascript = scan_lang_rules(
            "javascript",
            "app.use(cors({ origin: '*', credentials: true }));\napp.use(cors({ origin: true, credentials: true }));\nfastify.register(cors, { origin: /.*/, credentials: true });\nres.setHeader('Access-Control-Allow-Origin', '*'); res.setHeader('Access-Control-Allow-Credentials', 'true');\nresponse.header('Access-Control-Allow-Origin', req.headers.origin); response.header('Access-Control-Allow-Credentials', true);\nres.set('Access-Control-Allow-Origin', '*');\nres.set('Access-Control-Allow-Credentials', 'true');\n",
        );
        assert_eq!(
            javascript,
            vec!["GF-439", "GF-439", "GF-439", "GF-439", "GF-439", "GF-439"]
        );

        let javascript_neg = scan_lang_rules(
            "javascript",
            "app.use(cors({ origin: ['https://app.example'], credentials: true }));\napp.use(cors({ origin: '*', credentials: false }));\nfastify.register(cors, { origin: /^https:\\/\\/app\\.example$/, credentials: true });\nres.setHeader('Access-Control-Allow-Origin', '*'); res.setHeader('Access-Control-Allow-Credentials', 'false');\nres.setHeader('Access-Control-Allow-Origin', 'https://app.example'); res.setHeader('Access-Control-Allow-Credentials', 'true');\nconst text = \"app.use(cors({ origin: '*', credentials: true }))\";\n",
        );
        assert!(
            javascript_neg.is_empty(),
            "javascript cors false positives: {javascript_neg:?}"
        );

        let root = temp_dir("javascript-cors-test-fixture-suppression");
        fs::create_dir_all(root.join("src/middleware/cors")).unwrap();
        fs::write(
            root.join("src/server.ts"),
            "app.use(cors({ origin: '*', credentials: true }));\n",
        )
        .unwrap();
        fs::write(
            root.join("src/middleware/cors/index.test.ts"),
            "app.use(cors({ origin: '*', credentials: true }));\n",
        )
        .unwrap();
        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::from(["GF-439".to_owned()]),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();
        assert_eq!(
            report
                .findings
                .iter()
                .map(|finding| finding.location.path.as_str())
                .collect::<Vec<_>>(),
            vec!["src/server.ts"]
        );
    }

    #[test]
    fn sensitive_cookie_flags_are_flagged_when_explicitly_disabled() {
        let python = scan_lang_rules(
            "python",
            "response.set_cookie('sessionid', token, secure=False)\nresponse.set_cookie('auth_token', token, httponly=False)\nresponse.set_cookie('theme', value, secure=False, httponly=False)\nresponse.set_cookie('sessionid', token, secure=True, httponly=True)\n",
        );
        assert_eq!(python, vec!["GF-443", "GF-444"]);

        let go = scan_lang_rules(
            "go",
            "http.SetCookie(w, &http.Cookie{Name: \"session\", Value: tok, Secure: false})\nhttp.SetCookie(w, &http.Cookie{Name: \"auth_token\", Value: tok, HttpOnly: false})\nhttp.SetCookie(w, &http.Cookie{Name: \"theme\", Value: theme, Secure: false, HttpOnly: false})\n",
        );
        assert_eq!(go, vec!["GF-443", "GF-444"]);

        let java = scan_lang_rules(
            "java",
            "ResponseCookie.from(\"session\", value).secure(false).build();\nResponseCookie.from(\"auth_token\", value).httpOnly(false).build();\nResponseCookie.from(\"theme\", value).secure(false).httpOnly(false).build();\n",
        );
        assert_eq!(java, vec!["GF-443", "GF-444"]);

        let javascript = scan_lang_rules(
            "javascript",
            "res.cookie('sessionid', token, { secure: false });\nres.cookie('auth_token', token, { httpOnly: false });\nreply.setCookie('sid', token, { secure: false });\nsetCookie(c, 'access_token', token, { httpOnly: false });\nres.cookie('theme', value, { secure: false, httpOnly: false });\nres.cookie('sessionid', token, { secure: true, httpOnly: true });\n",
        );
        assert_eq!(javascript, vec!["GF-443", "GF-443", "GF-444", "GF-444"]);
    }

    #[test]
    fn samesite_none_sensitive_cookie_requires_secure() {
        let python = scan_lang_rules(
            "python",
            "response.set_cookie('sessionid', token, samesite='None')\nresponse.set_cookie('sessionid', token, samesite='None', secure=True)\nresponse.set_cookie('theme', value, samesite='None')\nresponse.set_cookie('sessionid', token, samesite='Lax')\n",
        );
        assert_eq!(python, vec!["GF-445"]);

        let go = scan_lang_rules(
            "go",
            "http.SetCookie(w, &http.Cookie{Name: \"session\", Value: tok, SameSite: http.SameSiteNoneMode})\nhttp.SetCookie(w, &http.Cookie{Name: \"session\", Value: tok, SameSite: http.SameSiteNoneMode, Secure: true})\nhttp.SetCookie(w, &http.Cookie{Name: \"theme\", Value: theme, SameSite: http.SameSiteNoneMode})\n",
        );
        assert_eq!(go, vec!["GF-445"]);

        let java = scan_lang_rules(
            "java",
            "ResponseCookie.from(\"session\", value).sameSite(\"None\").build();\nResponseCookie.from(\"session\", value).sameSite(\"None\").secure(true).build();\nResponseCookie.from(\"theme\", value).sameSite(\"None\").build();\n",
        );
        assert_eq!(java, vec!["GF-445"]);

        let javascript = scan_lang_rules(
            "javascript",
            "res.cookie('sessionid', token, { sameSite: 'None' });\nsetCookie(c, 'sessionid', token, { sameSite: 'None' });\nres.cookie('sessionid', token, { sameSite: 'None', secure: true });\nres.cookie('theme', value, { sameSite: 'None' });\nres.cookie('sessionid', token, { sameSite: 'Lax' });\n",
        );
        assert_eq!(javascript, vec!["GF-445", "GF-445"]);
    }

