    #[test]
    fn javascript_session_middleware_cookie_flags_are_flagged() {
        let pos = scan_lang_rules(
            "javascript",
            "const session = require('express-session');\n\
             const cookieSession = require('cookie-session');\n\
             import expressSession from 'express-session';\n\
             import clientSession from 'cookie-session';\n\
             const unsafeExpressCookie = { secure: false, httpOnly: false };\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { secure: false } });\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { httpOnly: false } });\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { sameSite: 'none' } });\n\
             expressSession({ secret: process.env.SESSION_SECRET, cookie: unsafeExpressCookie });\n\
             cookieSession({ keys: keygripKeys, secure: false });\n\
             cookieSession({ keys: keygripKeys, httpOnly: false });\n\
             cookieSession({ keys: keygripKeys, sameSite: 'none' });\n\
             clientSession({ keys: keygripKeys, sameSite: 'none', secure: false });\n\
             require('express-session')({ secret: process.env.SESSION_SECRET, cookie: { sameSite: 'none', secure: false } });\n",
        );
        assert_eq!(
            pos,
            vec![
                "GF-443", "GF-443", "GF-443", "GF-443", "GF-443", "GF-444", "GF-444", "GF-444",
                "GF-445", "GF-445", "GF-445", "GF-445"
            ]
        );

        let neg = scan_lang_rules(
            "javascript",
            "const session = require('express-session');\n\
             const cookieSession = require('cookie-session');\n\
             import expressSession from 'express-session';\n\
             session({ secret: process.env.SESSION_SECRET });\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { secure: true, httpOnly: true } });\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { sameSite: 'none', secure: true } });\n\
             session({ secret: process.env.SESSION_SECRET, cookie: { sameSite: 'none', secure: 'auto' } });\n\
             expressSession({ secret: process.env.SESSION_SECRET, cookie: { sameSite: 'lax' } });\n\
             cookieSession({ keys: keygripKeys, secure: true, httpOnly: true, sameSite: 'none' });\n\
             cookieSession({ keys: keygripKeys, sameSite: 'lax' });\n\
             notSession({ cookie: { secure: false, httpOnly: false, sameSite: 'none' } });\n\
             const text = \"session({ cookie: { secure: false } })\";\n",
        );
        assert!(
            neg.is_empty(),
            "javascript session cookie flag false positives: {neg:?}"
        );
    }

    #[test]
    fn csrf_protection_disabled_is_flagged() {
        let python = scan_lang_rules(
            "python",
            "@csrf_exempt\ndef webhook(request):\n    return ok\n@csrf.exempt\ndef flask_webhook():\n    return ok\napp = csrf_exempt(app)\ncsrf.exempt(api_view)\nWTF_CSRF_ENABLED = False\nWTF_CSRF_CHECK_DEFAULT = False\napp.config['WTF_CSRF_ENABLED'] = False\napp.config.update(WTF_CSRF_CHECK_DEFAULT=False)\napp.config.update({'WTF_CSRF_ENABLED': False})\nWTF_CSRF_ENABLED = True\n",
        );
        assert_eq!(
            python,
            vec![
                "GF-446", "GF-446", "GF-446", "GF-446", "GF-446", "GF-446", "GF-446", "GF-446",
                "GF-446"
            ]
        );

        let java = scan_lang_rules(
            "java",
            "http.csrf().disable();\nhttp.csrf(csrf -> csrf.disable());\nhttp.csrf(AbstractHttpConfigurer::disable);\nhttp.csrf(Customizer.withDefaults());\n",
        );
        assert_eq!(java, vec!["GF-446", "GF-446", "GF-446"]);

        let javascript = scan_lang_rules(
            "javascript",
            "const csrf = require('csurf');\n\
             const csrfProtection = require('csurf');\n\
             import csrfMiddleware from 'csurf';\n\
             const unsafeCsrfOptions = { ignoreMethods: ['GET', 'HEAD', 'OPTIONS', 'POST'] };\n\
             app.use(csrf({ ignoreMethods: ['GET', 'POST'] }));\n\
             app.use(csrfProtection({ ignoreMethods: ['PUT'] }));\n\
             app.use(csrfMiddleware({ ignoreMethods: ['PATCH'] }));\n\
             app.use(csrf(unsafeCsrfOptions));\n\
             app.use(require('csurf')({ ignoreMethods: ['DELETE'] }));\n",
        );
        assert_eq!(
            javascript,
            vec!["GF-446", "GF-446", "GF-446", "GF-446", "GF-446"]
        );

        let python_neg = scan_lang_rules(
            "python",
            "def csrf_exempt(view_func):\n    return decorator(view_func)\nfrom django.views.decorators.csrf import csrf_exempt\n\"\"\"\n@csrf_exempt\n@csrf.exempt\n\"\"\"\nWTF_CSRF_ENABLED = True\nWTF_CSRF_CHECK_DEFAULT = True\napp.config['WTF_CSRF_ENABLED'] = True\napp.config.update(WTF_CSRF_CHECK_DEFAULT=True)\ntext = \"WTF_CSRF_ENABLED = False\"\nlabel = \"@csrf.exempt\"\n",
        );
        assert!(
            python_neg.is_empty(),
            "python csrf false positives: {python_neg:?}"
        );

        let javascript_neg = scan_lang_rules(
            "javascript",
            "const csrf = require('csurf');\n\
             import csrfMiddleware from 'csurf';\n\
             app.use(csrf());\n\
             app.use(csrf({ ignoreMethods: ['GET', 'HEAD', 'OPTIONS'] }));\n\
             app.use(csrfMiddleware({ ignoreMethods: ['GET'] }));\n\
             const safeCsrfOptions = { ignoreMethods: ['GET', 'HEAD', 'OPTIONS'] };\n\
             app.use(csrf(safeCsrfOptions));\n\
             notCsrf({ ignoreMethods: ['POST'] });\n\
             const text = \"csrf({ ignoreMethods: ['POST'] })\";\n",
        );
        assert!(
            javascript_neg.is_empty(),
            "javascript csrf false positives: {javascript_neg:?}"
        );
    }

