    #[test]
    fn clickjacking_protection_disabled_is_flagged() {
        let python = scan_lang_rules(
            "python",
            "@xframe_options_exempt\ndef embedded(request):\n    return ok\nwrapped = xframe_options_exempt(view)\nX_FRAME_OPTIONS = 'ALLOWALL'\nX_FRAME_OPTIONS = \"ALLOW-FROM https://partner.example\"\ndef xframe_options_exempt(view_func):\n    return decorator(view_func)\n\"\"\"\n@xframe_options_exempt\n\"\"\"\nX_FRAME_OPTIONS = 'DENY'\nX_FRAME_OPTIONS = 'SAMEORIGIN'\ntext = \"X_FRAME_OPTIONS = 'ALLOWALL'\"\n",
        );
        assert_eq!(python, vec!["GF-447", "GF-447", "GF-447", "GF-447"]);

        let java = scan_lang_rules(
            "java",
            "http.headers().frameOptions().disable();\nhttp.headers(headers -> headers.frameOptions(frameOptions -> frameOptions.disable()));\nhttp.headers(headers -> headers.frameOptions(frameOptions -> frameOptions.sameOrigin()));\n",
        );
        assert_eq!(java, vec!["GF-447", "GF-447"]);

        let javascript = scan_lang_rules(
            "javascript",
            "const helmet = require('helmet');\n\
             import secureHeaders from 'helmet';\n\
             const disabledFrameHeaders = { xFrameOptions: false };\n\
             app.use(helmet({ xFrameOptions: false }));\n\
             app.use(helmet({ frameguard: false }));\n\
             app.use(secureHeaders({ xFrameOptions: false, contentSecurityPolicy: false }));\n\
             app.use(helmet(disabledFrameHeaders));\n\
             app.use(helmet({ xFrameOptions: false, contentSecurityPolicy: { directives: { frameAncestors: ['*'] } } }));\n\
             app.use(helmet({ xFrameOptions: false, contentSecurityPolicy: { directives: { frameAncestors: ['*', \"'self'\"] } } }));\n\
             app.use(helmet({ xFrameOptions: false, contentSecurityPolicy: { directives: { frameAncestors: null } } }));\n\
             require('helmet')({ xFrameOptions: false });\n",
        );
        assert_eq!(
            javascript,
            vec!["GF-447", "GF-447", "GF-447", "GF-447", "GF-447", "GF-447", "GF-447", "GF-447"]
        );

        let javascript_neg = scan_lang_rules(
            "javascript",
            "const helmet = require('helmet');\n\
             const safeFrameHeaders = { xFrameOptions: false, contentSecurityPolicy: { directives: { frameAncestors: [\"'self'\"] } } };\n\
             helmet();\n\
             helmet({ xFrameOptions: { action: 'sameorigin' } });\n\
             helmet.xFrameOptions();\n\
             helmet.frameguard({ action: 'deny' });\n\
             helmet({ xFrameOptions: false, contentSecurityPolicy: { directives: { frameAncestors: [\"'self'\"] } } });\n\
             helmet({ frameguard: false, contentSecurityPolicy: { directives: { frameAncestors: [\"'none'\"] } } });\n\
             helmet(safeFrameHeaders);\n\
             const notHelmet = require('not-helmet');\n\
             notHelmet({ xFrameOptions: false });\n\
             const text = 'helmet({ xFrameOptions: false })';\n",
        );
        assert!(
            javascript_neg.is_empty(),
            "javascript clickjacking false positives: {javascript_neg:?}"
        );

        let hono = scan_lang_rules(
            "javascript",
            "import { secureHeaders } from 'hono/secure-headers';\n\
             import { secureHeaders as headers } from 'hono/secure-headers';\n\
             import * as honoHeaders from 'hono/secure-headers';\n\
             const honoSecure = require('hono/secure-headers');\n\
             const { secureHeaders: cjsHeaders } = require('hono/secure-headers');\n\
             const disabledHonoHeaders = { xFrameOptions: false };\n\
             app.use(secureHeaders({ xFrameOptions: false }));\n\
             app.use(headers({ xFrameOptions: false, contentSecurityPolicy: false }));\n\
             app.use(honoHeaders.secureHeaders({ xFrameOptions: false }));\n\
             app.use(honoSecure.secureHeaders({ xFrameOptions: false }));\n\
             app.use(cjsHeaders(disabledHonoHeaders));\n\
             require('hono/secure-headers').secureHeaders({ xFrameOptions: false });\n",
        );
        assert_eq!(
            hono,
            vec!["GF-447", "GF-447", "GF-447", "GF-447", "GF-447", "GF-447"]
        );

        let hono_neg = scan_lang_rules(
            "javascript",
            "import { secureHeaders } from 'hono/secure-headers';\n\
             const safeHonoHeaders = { xFrameOptions: false, contentSecurityPolicy: { frameAncestors: [\"'self'\"] } };\n\
             secureHeaders();\n\
             secureHeaders({ xFrameOptions: 'DENY' });\n\
             secureHeaders({ xFrameOptions: false, contentSecurityPolicy: { frameAncestors: [\"'self'\"] } });\n\
             secureHeaders({ xFrameOptions: false, contentSecurityPolicy: { frameAncestors: [\"'none'\"] } });\n\
             secureHeaders(safeHonoHeaders);\n\
             const notHono = require('not-hono/secure-headers');\n\
             notHono.secureHeaders({ xFrameOptions: false });\n\
             const text = 'secureHeaders({ xFrameOptions: false })';\n",
        );
        assert!(
            hono_neg.is_empty(),
            "hono secure headers clickjacking false positives: {hono_neg:?}"
        );
    }

