    #[test]
    fn jwt_signature_verification_disabled_is_flagged() {
        let python = scan_lang_rules(
            "python",
            "jwt.decode(token, key, options={'verify_signature': False})\njwt.decode(token, key, options={\"verify_signature\": False})\njwt.decode(token, key, algorithms=['none'])\njwt.decode(token, key, algorithms=['HS256'])\njwt.decode(token, key, options={'verify_signature': True})\n",
        );
        assert_eq!(python, vec!["GF-448", "GF-448", "GF-448"]);

        let java = scan_lang_rules(
            "java",
            "JWT.require(Algorithm.none()).build().verify(token);\nJWT.require(Algorithm.HMAC256(secret)).build().verify(token);\nJWT.decode(token);\n",
        );
        assert_eq!(java, vec!["GF-448"]);

        let javascript = scan_lang_rules(
            "javascript",
            "const token = req.headers.authorization.split(' ')[1];\nconst claims = jwt.decode(token);\nconst decoded = jsonwebtoken.decode(req.cookies.session);\nreq.user = decodeJwt(request.headers.authorization);\nconst payload = jose.decodeJwt(ctx.request.headers.authorization);\njwt.verify(token, secret, { algorithms: ['none', 'HS256'] });\njsonwebtoken.verify(req.headers.authorization, null, { algorithms: ['none'] });\n",
        );
        assert_eq!(
            javascript,
            vec!["GF-448", "GF-448", "GF-448", "GF-448", "GF-448", "GF-448"]
        );

        let javascript_neg = scan_lang_rules(
            "javascript",
            "const claims = jwt.verify(token, secret, { algorithms: ['HS256'] });\nconst token = req.headers.authorization;\njwt.verify(token, secret);\nconst header = jwt.decode(token, { complete: true });\nconst decoded = jwt.decode(staticFixtureToken);\njose.jwtVerify(token, key);\nconst text = 'jwt.decode(req.headers.authorization)';\n",
        );
        assert!(
            javascript_neg.is_empty(),
            "javascript jwt false positives: {javascript_neg:?}"
        );
    }

    #[test]
    fn jwt_expiration_verification_disabled_is_flagged() {
        let python = scan_lang_rules(
            "python",
            "jwt.decode(token, key, options={'verify_exp': False}, algorithms=['HS256'])\n\
             jwt.decode_complete(token, key, options={\"verify_exp\": False}, algorithms=[\"HS256\"])\n\
             jwt.decode(token, key, verify_exp=False)\n\
             from jwt import decode as read_jwt\n\
             read_jwt(token, key, options={'verify_exp': False}, algorithms=['HS256'])\n\
             import jwt as pyjwt\n\
             pyjwt.decode(token, key, options={'verify_exp': False}, algorithms=['HS256'])\n",
        );
        assert_eq!(
            python,
            vec!["GF-518", "GF-518", "GF-518", "GF-518", "GF-518"]
        );

        let python_neg = scan_lang_rules(
            "python",
            "jwt.decode(token, key, algorithms=['HS256'])\n\
             jwt.decode(token, key, options={'verify_exp': True}, algorithms=['HS256'])\n\
             jwt.decode(token, key, leeway=5, algorithms=['HS256'])\n\
             not_decode(token, key, options={'verify_exp': False})\n\
             text = \"jwt.decode(token, key, options={'verify_exp': False})\"\n",
        );
        assert!(
            python_neg.is_empty(),
            "python jwt expiration false positives: {python_neg:?}"
        );

        let javascript = scan_lang_rules(
            "javascript",
            "const jwt = require('jsonwebtoken');\n\
             const { verify } = require('jsonwebtoken');\n\
             import jsonwebtoken from 'jsonwebtoken';\n\
             import { verify as checkJwt } from 'jsonwebtoken';\n\
             const unsafeOptions = { ignoreExpiration: true };\n\
             jwt.verify(token, secret, { ignoreExpiration: true });\n\
             jsonwebtoken.verify(req.cookies.session, key, { ignoreExpiration: true });\n\
             verify(req.headers.authorization, secret, unsafeOptions);\n\
             checkJwt(token, secret, { \"ignoreExpiration\": true });\n\
             require('jsonwebtoken').verify(token, secret, { ignoreExpiration: true });\n",
        );
        assert_eq!(
            javascript,
            vec!["GF-518", "GF-518", "GF-518", "GF-518", "GF-518"]
        );

        let javascript_neg = scan_lang_rules(
            "javascript",
            "const jwt = require('jsonwebtoken');\n\
             jwt.verify(token, secret, { algorithms: ['HS256'] });\n\
             jwt.verify(token, secret, { ignoreExpiration: false });\n\
             jwt.verify(token, secret, { maxAge: '15m' });\n\
             notJwt.verify(token, secret, { ignoreExpiration: true });\n\
             const text = 'jwt.verify(token, secret, { ignoreExpiration: true })';\n",
        );
        assert!(
            javascript_neg.is_empty(),
            "javascript jwt expiration false positives: {javascript_neg:?}"
        );
    }

    #[test]
    fn javascript_rule_pack_flags_hardcoded_jwt_keys() {
        let pos = scan_lang_rules(
            "javascript",
            "const jwt = require('jsonwebtoken');\nconst { sign, verify: checkJwt } = require('jsonwebtoken');\nimport jsonwebtoken from 'jsonwebtoken';\nimport { sign as makeToken, verify } from 'jsonwebtoken';\nimport { SignJWT } from 'jose';\njwt.sign(payload, 'hardcoded-signing-secret');\njsonwebtoken.sign(payload, Buffer.from('another-static-secret'));\nsign(payload, new TextEncoder().encode('destructured-static-secret'));\nmakeToken(payload, crypto.createSecretKey(Buffer.from('imported-static-secret')));\njwt.verify(req.headers.authorization, 'hardcoded-hmac-secret');\ncheckJwt(token, Buffer.from('aliased-static-secret'));\nverify(token, new TextEncoder().encode('verify-static-secret'));\nrequire('jsonwebtoken').sign(payload, 'direct-require-static-secret');\nawait new SignJWT(claims).setProtectedHeader({ alg: 'HS256' }).sign(new TextEncoder().encode('jose-static-secret'));\n",
        );
        assert_eq!(
            pos,
            vec![
                "GF-423", "GF-423", "GF-423", "GF-423", "GF-423", "GF-423", "GF-423", "GF-423",
                "GF-423"
            ]
        );

        let neg = scan_lang_rules(
            "javascript",
            "const jwt = require('jsonwebtoken');\nconst { sign, verify } = require('jsonwebtoken');\nimport { SignJWT } from 'jose';\njwt.sign(payload, process.env.JWT_SECRET);\njwt.sign(payload, config.jwtSecret);\nsign(payload, await secrets.get('jwt-signing-key'));\nverify(token, getVerificationKey(header.kid), { algorithms: ['RS256'] });\njwt.verify(token, publicKeyPem, { algorithms: ['RS256'] });\njwt.verify(token, \"-----BEGIN RSA PUBLIC KEY-----\\nMIIB\\n-----END RSA PUBLIC KEY-----\", { algorithms: ['RS256'] });\nnew SignJWT(claims).setProtectedHeader({ alg: 'HS256' }).sign(secretKey);\nnotJwt.sign(payload, 'looks-static-but-not-jsonwebtoken');\nconst text = \"jwt.sign(payload, 'hardcoded-signing-secret')\";\n",
        );
        assert!(
            neg.is_empty(),
            "javascript jwt key false positives: {neg:?}"
        );
    }

