    #[test]
    fn javascript_rule_pack_flags_hardcoded_session_secrets() {
        let pos = scan_lang_rules(
            "javascript",
            "const session = require('express-session');\nconst cookieSession = require('cookie-session');\nconst cookieParser = require('cookie-parser');\nimport expressSession from 'express-session';\nimport signedCookies from 'cookie-parser';\nsession({ secret: 'keyboard cat', resave: false, saveUninitialized: false });\nexpressSession({ secret: ['primary-static-session-secret', process.env.OLD_SESSION_SECRET] });\ncookieSession({ keys: ['primary-cookie-signing-key', 'old-cookie-signing-key'] });\ncookieParser('hardcoded-cookie-signing-secret');\nsignedCookies(['primary-signed-cookie-secret']);\nrequire('express-session')({ secret: 'direct-require-session-secret' });\nconst sessionOptions = { secret: 'aliased-session-secret' };\nsession(sessionOptions);\n",
        );
        assert_eq!(
            pos,
            vec!["GF-423", "GF-423", "GF-423", "GF-423", "GF-423", "GF-423", "GF-423"]
        );

        let neg = scan_lang_rules(
            "javascript",
            "const session = require('express-session');\nconst cookieSession = require('cookie-session');\nconst cookieParser = require('cookie-parser');\nsession({ secret: process.env.SESSION_SECRET });\nsession({ secret: config.sessionSecret });\nsession({ secret: await secrets.get('session-secret') });\ncookieSession({ keys: keygripKeys });\ncookieSession({ keys: process.env.COOKIE_KEYS.split(',') });\ncookieParser(process.env.COOKIE_SECRET);\nnotSession({ secret: 'looks-static-but-not-session-middleware' });\nsession({ name: 'sid', resave: false });\nconst text = \"session({ secret: 'keyboard cat' })\";\n",
        );
        assert!(
            neg.is_empty(),
            "javascript session secret false positives: {neg:?}"
        );
    }

