    #[test]
    fn hardcoded_secret_ignores_angle_bracket_placeholders() {
        assert!(hardcoded_secret_column("const secretToken = \"<secret>\"").is_none());
        assert!(hardcoded_secret_column("API_TOKEN = \"<TOKEN>\"").is_none());
        assert!(hardcoded_secret_column("API_TOKEN = \"real-prod-token\"").is_some());
    }

    #[test]
    fn hardcoded_secret_ignores_common_non_secret_name_collisions() {
        for line in [
            "token_type = 'Bearer'",
            "PASSWORDFILE = '/etc/passwd'",
            "empty_password_msg = 'Invalid vault password was provided from script (%s)' % filename",
            "password: str, method: str = \"scrypt\", salt_length: int = 16",
            "INTERNAL_RESET_SESSION_TOKEN = \"_password_reset_token\"",
            "SECRET_KEY_INSECURE_PREFIX = \"django-insecure-\"",
            "REASON_CSRF_TOKEN_MISSING = \"CSRF token missing.\"",
            "token = \"is not\"",
            "token = \"not in\"",
            "token = \"%HOMEPATH%\\\\\" + token[2:]",
            "token = \"make.bat\"",
            "String token = \"[0-9A-Za-z!#$%&'*+.^_`|~-]+\";",
            "set_password = 'ALTER USER %(user)s IDENTIFIED BY \"%(password)s\"'",
        ] {
            assert!(
                hardcoded_secret_column(line).is_none(),
                "false positive for {line}"
            );
        }
        assert!(hardcoded_secret_column("API_TOKEN = \"real-prod-token\"").is_some());
        assert!(hardcoded_secret_column("password = \"hunter2xyz\"").is_some());
        assert!(hardcoded_secret_column("SECRET_KEY = \"prod-secret-value\"").is_some());
    }

