    /// Broadened Ada taint coverage: a command-line argument (source) flowing into
    /// an `Ada.Text_IO.Open` is path traversal (GF-405/CWE-22) — the Ada lane now
    /// feeds the same interprocedural taint engine as C/Java for file-open sinks, not
    /// just command spawn.
    #[test]
    fn ada_command_line_argument_to_file_open_is_path_traversal() {
        let root = temp_dir("ada-path-taint");
        // Stream_IO.Open is NOT matched by the syntactic scan_ada GF-405 (which keys
        // on `text_io.open`), so a finding here is proof the taint engine fired.
        fs::write(
            root.join("loader.adb"),
            "with Ada.Streams.Stream_IO;\n\
             procedure Loader (Input : String) is\n\
                F : Ada.Streams.Stream_IO.File_Type;\n\
             begin\n\
                Ada.Streams.Stream_IO.Open (F, Ada.Streams.Stream_IO.In_File, Input);\n\
             end Loader;\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        assert!(
            report
                .findings
                .iter()
                .any(|f| f.rule_id == "GF-405" && f.analysis.engine == "govfuzz.static.taint.v1"),
            "tainted Ada file-open should confirm path traversal, got: {:?}",
            report
                .findings
                .iter()
                .map(|f| (&f.rule_id, f.location.line))
                .collect::<Vec<_>>()
        );
    }

    /// Java dynamic code evaluation (CWE-94, GF-420): a request parameter (source)
