    /// Best-in-class: the taint engine confirms MORE than command injection — a
    /// source reaching a file-open is path traversal (GF-405, interprocedural), a
    /// source built into a SQL query is SQL injection (GF-419), and a parameterized
    /// query with a tainted bound argument is safe (no dynamic-string → no finding).
    #[test]
    fn multi_class_taint_confirms_path_and_sql() {
        let root = temp_dir("go-multisink-taint");
        fs::write(
            root.join("main.go"),
            "package p\n\
             import (\"os\"; \"database/sql\")\n\
             func readPath(userPath string) {\n\
                os.Open(userPath)\n\
             }\n\
             func dispatch(userInput string) {\n\
                readPath(userInput)\n\
             }\n\
             func sqlBuild(userQuery string, db *sql.DB) {\n\
                db.Query(\"SELECT * FROM t WHERE x=\" + userQuery)\n\
             }\n\
             func sqlSafe(userData string, db *sql.DB) {\n\
                db.Query(\"SELECT * FROM t WHERE x=?\", userData)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint = |rule: &str| -> Vec<u32> {
            report
                .findings
                .iter()
                .filter(|f| f.rule_id == rule && f.analysis.engine == "govfuzz.static.taint.v1")
                .map(|f| f.location.line)
                .collect()
        };
        // Interprocedural path traversal (dispatch → readPath → os.Open) at line 4.
        assert!(
            taint("GF-405").contains(&4),
            "path-traversal taint: {:?}",
            taint("GF-405")
        );
        // SQL injection built with concat at line 10.
        assert!(
            taint("GF-419").contains(&10),
            "sql-injection taint: {:?}",
            taint("GF-419")
        );
        // The parameterized query at line 13 is safe — no SQL finding there.
        assert!(
            !taint("GF-419").contains(&13),
            "a parameterized query must not fire SQL taint: {:?}",
            taint("GF-419")
        );
    }

    #[test]
    fn open_redirect_taint_confirms_redirect_sinks() {
        let root = temp_dir("open-redirect-taint");
        fs::write(
            root.join("app.py"),
            "from flask import request, redirect\n\
             def login():\n\
             \x20\x20\x20\x20next_url = request.args.get('next')\n\
             \x20\x20\x20\x20return redirect(next_url)\n\
             def safe():\n\
             \x20\x20\x20\x20return redirect('/home')\n",
        )
        .unwrap();
        fs::write(
            root.join("Handler.java"),
            "import jakarta.servlet.http.*;\n\
             class Handler {\n\
               void done(HttpServletRequest request, HttpServletResponse response) throws Exception {\n\
                 String next = request.getParameter(\"next\");\n\
                 response.sendRedirect(next);\n\
               }\n\
             }\n",
        )
        .unwrap();
        fs::write(
            root.join("main.go"),
            "package p\n\
             import \"net/http\"\n\
             func done(w http.ResponseWriter, r *http.Request) {\n\
                next := r.URL.Query().Get(\"next\")\n\
                http.Redirect(w, r, next, http.StatusFound)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint_lines = |path: &str| -> Vec<u32> {
            report
                .findings
                .iter()
                .filter(|f| {
                    f.rule_id == "GF-442"
                        && f.analysis.engine == "govfuzz.static.taint.v1"
                        && f.location.path == path
                })
                .map(|f| f.location.line)
                .collect()
        };
        assert_eq!(taint_lines("app.py"), vec![4]);
        assert_eq!(taint_lines("Handler.java"), vec![5]);
        assert_eq!(taint_lines("main.go"), vec![5]);
    }

    /// Best-in-class: taint from a real INPUT-SOURCE API — the function has NO
    /// source-named parameter, so the flow is caught only because
