    #[test]
    fn python_web_request_apis_seed_taint_and_do_not_create_analysis_gaps() {
        let root = temp_dir("python-web-request-source-taint");
        fs::write(
            root.join("views.py"),
            "import os\n\
             import requests\n\
             def django_sources():\n\
             \x20\x20\x20\x20cmd = request.GET.get(\"cmd\")\n\
             \x20\x20\x20\x20path = request.META.get(\"X_PATH\")\n\
             \x20\x20\x20\x20os.system(cmd)\n\
             \x20\x20\x20\x20open(path)\n\
             def starlette_sources():\n\
             \x20\x20\x20\x20url = request.query_params.get(\"next\")\n\
             \x20\x20\x20\x20header_cmd = request.headers.get(\"X-Cmd\")\n\
             \x20\x20\x20\x20body = request.json()\n\
             \x20\x20\x20\x20requests.get(url)\n\
             \x20\x20\x20\x20os.popen(header_cmd)\n\
             \x20\x20\x20\x20open(body[\"path\"])\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint_lines = |rule: &str| -> Vec<u32> {
            report
                .findings
                .iter()
                .filter(|finding| {
                    finding.rule_id == rule && finding.analysis.engine == "govfuzz.static.taint.v1"
                })
                .map(|finding| finding.location.line)
                .collect()
        };
        assert!(
            taint_lines("GF-304").contains(&6) && taint_lines("GF-304").contains(&13),
            "Django/Starlette request values reaching command sinks must be taint-confirmed: {report:#?}"
        );
        assert!(
            taint_lines("GF-405").contains(&7) && taint_lines("GF-405").contains(&14),
            "Django/Starlette request values reaching path sinks must be taint-confirmed: {report:#?}"
        );
        assert!(
            taint_lines("GF-427").contains(&12),
            "Starlette query parameter reaching HTTP client must be SSRF-taint-confirmed: {report:#?}"
        );
        for callee in [
            "request.GET.get",
            "request.META.get",
            "request.query_params.get",
            "request.headers.get",
            "request.json",
        ] {
            assert!(
                !report
                    .analysis_gaps
                    .iter()
                    .any(|gap| gap.callee.eq_ignore_ascii_case(callee)),
                "framework request source API {callee} must not remain an unresolved project-local gap: {report:#?}"
            );
        }
    }

