    #[test]
    fn python_append_taint_state_reaches_indexed_sink_argument() {
        let mut tainted = BTreeSet::from(["user_input".to_owned()]);
        let non_returning = BTreeSet::new();
        apply_local_taint_assignments("values = []", "python", &mut tainted, &non_returning);
        for alias in container_taint_propagators("values.append(user_input)", "python", &tainted) {
            tainted.insert(alias);
        }
        assert!(
            tainted.contains("values"),
            "append should taint the list base"
        );
        assert!(
            line_uses_taint("os.system(values[0])", &tainted),
            "indexed list read should use the tainted list base"
        );
    }

