    #[test]
    fn map_put_like_propagators_ignore_tainted_keys_with_safe_values() {
        let tainted = BTreeSet::from(["user_input".to_owned(), "userinput".to_owned()]);
        assert_eq!(
            container_taint_propagators("values.put(\"cmd\", userInput)", "java", &tainted),
            vec!["values".to_owned()]
        );
        assert!(
            container_taint_propagators("values.put(userInput, \"safe\")", "java", &tainted)
                .is_empty()
        );
        assert_eq!(
            container_taint_propagators("values.insert(\"cmd\", user_input)", "rust", &tainted),
            vec!["values".to_owned()]
        );
        assert!(container_taint_propagators(
            "values.insert(user_input, \"safe\")",
            "rust",
            &tainted
        )
        .is_empty());
        assert_eq!(
            container_taint_propagators("values.emplace(\"cmd\", user_input)", "cpp", &tainted),
            vec!["values".to_owned()]
        );
        assert!(container_taint_propagators(
            "values.emplace(user_input, \"safe\")",
            "cpp",
            &tainted
        )
        .is_empty());
    }

