    /// Best-in-class precision: a list-form command builder distinguishes a tainted
    /// PROGRAM (injection) from a tainted ARGUMENT to a fixed program (safe). Only
    /// the program-tainted and shell cases fire.
    #[test]
    fn list_form_exec_flags_tainted_program_not_tainted_argument() {
        let root = temp_dir("go-listform");
        fs::write(
            root.join("main.go"),
            "package p\n\
             import \"os/exec\"\n\
             func prog(userInput string) {\n\
                exec.Command(userInput)\n\
             }\n\
             func arg(userInput string) {\n\
                exec.Command(\"ls\", \"-l\", userInput)\n\
             }\n\
             func shell(userInput string) {\n\
                exec.Command(\"sh\", \"-c\", userInput)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let cmd_lines: Vec<u32> = report
            .findings
            .iter()
            .filter(|f| f.rule_id == "GF-304")
            .map(|f| f.location.line)
            .collect();
        assert!(
            cmd_lines.contains(&4),
            "tainted program is injection: {cmd_lines:?}"
        );
        assert!(
            cmd_lines.contains(&10),
            "shell form is injection: {cmd_lines:?}"
        );
        // A tainted ARGUMENT to a fixed program (line 7) is NOT command injection.
        assert!(
            !cmd_lines.contains(&7),
            "tainted arg to a fixed program must not fire: {cmd_lines:?}"
        );
    }

    /// M23 Phase 2: Go joins the interprocedural taint engine. A source-like
    /// parameter that reaches `exec.Command` directly AND across a project-local
    /// call is GF-304 (proven flow); a sanitized value is not.
    #[test]
    fn taint_finding_sarif_carries_code_flows_dataflow_path() {
        // A taint flow's source→sink trace must render as SARIF `codeFlows` so
        // GitHub code scanning / IDEs draw the dataflow path.
        let root = temp_dir("sarif-codeflows");
        fs::write(
            root.join("main.go"),
            "package main\n\
             import \"os/exec\"\n\
             func run(userInput string) {\n\
                exec.Command(userInput)\n\
             }\n",
        )
        .unwrap();
        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: true,
        })
        .unwrap();
        let sarif = render_sarif(&report);
        let results = sarif["runs"][0]["results"].as_array().expect("results");
        let taint = results
            .iter()
            .find(|r| {
                r["ruleId"] == "GF-304" && r["codeFlows"].as_array().is_some_and(|c| !c.is_empty())
            })
            .expect("a GF-304 taint result with codeFlows");
        let locations = taint["codeFlows"][0]["threadFlows"][0]["locations"]
            .as_array()
            .expect("threadFlow locations");
        assert!(
            !locations.is_empty(),
            "codeFlows path must have at least the sink step"
        );
        // Every step has a physical location + a human-readable message.
        for loc in locations {
            assert!(loc["location"]["physicalLocation"]["region"]["startLine"].is_number());
            assert!(loc["location"]["message"]["text"].is_string());
        }
    }

    /// Reporting parity: every emitted static finding carries a non-empty top-level
    /// CWE in the PRIMARY report (not only in SARIF tags / the auto CSV), and a Go
    /// command-exec finding resolves to CWE-78.
    #[test]
    fn go_findings_carry_top_level_cwe() {
        let root = temp_dir("go-cwe");
        fs::write(
            root.join("main.go"),
            "package main\n\
             import \"os/exec\"\n\
             func run(userInput string) {\n\
                exec.Command(userInput)\n\
             }\n",
        )
        .unwrap();
        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();
        assert!(!report.findings.is_empty(), "expected Go findings");
        for finding in &report.findings {
            assert!(
                finding.cwe.starts_with("CWE-"),
                "{} ({}) has a missing/invalid cwe: {:?}",
                finding.id,
                finding.rule_id,
                finding.cwe
            );
        }
        let cmd = report
            .findings
            .iter()
            .find(|f| f.rule_id == "GF-304" || f.rule_id == "GF-404")
            .expect("a command-exec finding");
        assert_eq!(cmd.cwe, "CWE-78", "command-exec finding must be CWE-78");

        // JSON serialization exposes cwe top-level (not only under actionability).
        let value = serde_json::to_value(&report).unwrap();
        assert!(
            value["findings"][0]["cwe"]
                .as_str()
                .is_some_and(|c| !c.is_empty()),
            "JSON finding must carry non-empty top-level cwe"
        );
    }

    /// Reporting richness: findings carry a non-empty `remediation` in the primary
    /// JSON, and SARIF exports per-result `help.text` (= remediation) plus per-rule
    /// `help` + `helpUri` (semgrep/bandit-style fix guidance).
    #[test]
    fn findings_carry_remediation_and_sarif_help() {
        let root = temp_dir("remediation-help");
        fs::write(
            root.join("main.go"),
            "package main\n\
             import \"os/exec\"\n\
             func run(userInput string) {\n\
                exec.Command(userInput)\n\
             }\n",
        )
        .unwrap();
        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: true,
        })
        .unwrap();
        assert!(!report.findings.is_empty(), "expected Go findings");
        for finding in &report.findings {
            assert!(
                !finding.remediation.is_empty(),
                "{} ({}) has empty remediation",
                finding.id,
                finding.rule_id
            );
        }
        let value = serde_json::to_value(&report).unwrap();
        assert!(
            value["findings"][0]["remediation"]
                .as_str()
                .is_some_and(|r| !r.is_empty()),
            "JSON finding must carry non-empty remediation"
        );

        let sarif = render_sarif(&report);
        let result = &sarif["runs"][0]["results"][0];
        assert!(
            result["help"]["text"]
                .as_str()
                .is_some_and(|t| !t.is_empty()),
            "SARIF result must carry help.text remediation"
        );
        let rule = &sarif["runs"][0]["tool"]["driver"]["rules"][0];
        assert!(
            rule["help"]["text"].as_str().is_some_and(|t| !t.is_empty()),
            "SARIF rule must carry help.text"
        );
        assert!(
            rule["helpUri"]
                .as_str()
                .is_some_and(|u| u.starts_with("http")),
            "SARIF rule must carry a helpUri: {:?}",
            rule["helpUri"]
        );
    }

