    #[test]
    fn go_taint_reaches_command_sink_directly_and_across_calls() {
        let root = temp_dir("go-taint");
        fs::write(
            root.join("main.go"),
            "package main\n\
             import \"os/exec\"\n\
             func run(userInput string) {\n\
                exec.Command(userInput)\n\
             }\n\
             func dispatch(userQuery string) {\n\
                forward(userQuery)\n\
             }\n\
             func forward(a string) {\n\
                exec.Command(a)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint: Vec<u32> = report
            .findings
            .iter()
            .filter(|f| f.rule_id == "GF-304" && f.analysis.engine == "govfuzz.static.taint.v1")
            .map(|f| f.location.line)
            .collect();
        // Direct sink (line 4) and the interprocedural sink (line 10).
        assert!(taint.contains(&4), "direct Go taint flow: {taint:?}");
        assert!(
            taint.contains(&10),
            "interprocedural Go taint flow: {taint:?}"
        );
    }

    /// A Go value sanitized before the sink clears taint (no GF-304); and the
    /// interprocedural taint finding supersedes the GF-404 shell-literal heuristic
    /// at the same site (one row, not a pattern+taint pair).
    #[test]
    fn go_taint_clears_on_sanitize_and_dedupes_pattern() {
        let root = temp_dir("go-taint-dedupe");
        fs::write(
            root.join("main.go"),
            "package main\n\
             import \"os/exec\"\n\
             func clean(userPath string) {\n\
                v := sanitize(userPath)\n\
                exec.Command(v)\n\
             }\n\
             func vuln(userInput string) {\n\
                exec.Command(\"sh\", \"-c\", userInput)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        // Sanitized value never reaches a taint sink.
        assert!(
            !report
                .findings
                .iter()
                .any(|f| f.rule_id == "GF-304" && f.location.line == 5),
            "sanitized Go value must not taint-fire"
        );
        // The shell-literal line (8) is confirmed by taint (GF-304); the GF-404
        // pattern heuristic at the same line is deduped away.
        let line8: Vec<&str> = report
            .findings
            .iter()
            .filter(|f| f.location.line == 8)
            .map(|f| f.rule_id.as_str())
            .collect();
        assert!(
            line8.contains(&"GF-304"),
            "taint confirms shell exec: {line8:?}"
        );
        assert!(
            !line8.contains(&"GF-404"),
            "pattern hit must be deduped under the taint finding: {line8:?}"
        );
    }

    /// M23 Phase 2 (return-value taint summary): `x = f(tainted)` where `f` is
    /// proven to never return its parameters' taint (a validator returning a bool)
    /// does NOT taint `x` — so a sink on `x` is not a false positive. A helper that
    /// returns its argument still propagates taint.
    #[test]
    fn return_value_summary_stops_non_propagating_call_from_tainting() {
        let root = temp_dir("go-return-summary");
        fs::write(
            root.join("main.go"),
            "package p\n\
             import \"os/exec\"\n\
             func validate(userInput string) bool {\n\
                check(userInput)\n\
                return true\n\
             }\n\
             func forward(userQuery string) string {\n\
                return userQuery\n\
             }\n\
             func safe(userData string) {\n\
                ok := validate(userData)\n\
                exec.Command(ok)\n\
             }\n\
             func vuln(userPath string) {\n\
                cmd := forward(userPath)\n\
                exec.Command(cmd)\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint: Vec<u32> = report
            .findings
            .iter()
            .filter(|f| f.rule_id == "GF-304")
            .map(|f| f.location.line)
            .collect();
        // `ok := validate(userData)` — validate returns a bool literal, so line 12
        // (exec.Command(ok)) must NOT fire.
        assert!(
            !taint.contains(&12),
            "a value from a non-taint-returning call must not be tainted: {taint:?}"
        );
        // `cmd := forward(userPath)` — forward returns its argument, so line 16 does.
        assert!(
            taint.contains(&16),
            "a value from a taint-returning call must still be tainted: {taint:?}"
        );
    }

    /// M23 Phase 2 (branch-aware taint): a tainted variable validated by a
    /// recognized guard (`if (validate(x)) {…}`) is clean inside the block, but
    /// tainted again after it (join-point) — so a post-guard sink still fires.
    #[test]
    fn guard_sanitization_clears_inside_block_and_restores_after() {
        let root = temp_dir("go-guard-taint");
        fs::write(
            root.join("main.go"),
            "package p\n\
             import \"os/exec\"\n\
             func guarded(userInput string) {\n\
                if validate(userInput) {\n\
                   exec.Command(userInput)\n\
                }\n\
                exec.Command(userInput)\n\
             }\n\
             func sameline(userQuery string) {\n\
                if validate(userQuery) { exec.Command(userQuery) }\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let taint: Vec<u32> = report
            .findings
            .iter()
            .filter(|f| f.rule_id == "GF-304")
            .map(|f| f.location.line)
            .collect();
        // Inside the guard block (line 5) and the same-line guard (line 10): clean.
        assert!(
            !taint.contains(&5),
            "sink inside a validating guard block must not fire: {taint:?}"
        );
        assert!(
            !taint.contains(&10),
            "sink in a same-line validating guard must not fire: {taint:?}"
        );
        // After the block (line 7): taint restored at the join point, so it fires.
        assert!(
            taint.contains(&7),
            "a sink after the guard block must still fire (join-point): {taint:?}"
        );
    }

    /// M23 Phase 3: intraprocedural def-use — an uninitialized local read is
    /// GF-457 (CWE-457, rule GF-424), a scalar assigned before use is clean, and a
    /// narrowing cast of a variable is GF-425 (CWE-197).
    #[test]
    fn defuse_flags_uninitialized_use_and_narrowing_cast() {
        let root = temp_dir("c-defuse");
        fs::write(
            root.join("a.c"),
            "int use_uninit(int flag) {\n\
                int x;\n\
                int y = 3;\n\
                return x + y;\n\
             }\n\
             int safe_init(void) {\n\
                int z;\n\
                z = 7;\n\
                return z;\n\
             }\n\
             short narrow(int big) {\n\
                return (short)big;\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let by_rule = |rule: &str| -> Vec<u32> {
            report
                .findings
                .iter()
                .filter(|f| f.rule_id == rule)
                .map(|f| f.location.line)
                .collect()
        };
        // Uninitialized `x` read at line 4; `z` (assigned at line 8) is NOT flagged.
        assert_eq!(by_rule("GF-424"), vec![4], "uninitialized-use def-use");
        // Narrowing cast at line 12.
        assert_eq!(by_rule("GF-425"), vec![12], "narrowing-cast truncation");
    }

    /// GF-549: returning the address/reference of a local automatic fires; returning
    /// a heap pointer, a static local, a parameter's address, or a member does not.
    #[test]
    fn dangling_return_flags_local_address_only() {
        let root = temp_dir("c-dangling");
        fs::write(
            root.join("a.c"),
            "int *bad_scalar(void) {\n\
                int x = 5;\n\
                return &x;\n\
             }\n\
             char *bad_array(void) {\n\
                char buf[64];\n\
                return buf;\n\
             }\n\
             int *good_heap(void) {\n\
                int *p = malloc(sizeof(int));\n\
                return p;\n\
             }\n\
             int *good_static(void) {\n\
                static int s;\n\
                return &s;\n\
             }\n\
             int *good_param(int *q) {\n\
                return q;\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        let mut lines: Vec<u32> = report
            .findings
            .iter()
            .filter(|f| f.rule_id == "GF-549")
            .map(|f| f.location.line)
            .collect();
        lines.sort();
        // Line 3 (`return &x;`) and line 7 (`return buf;`) only.
        assert_eq!(
            lines,
            vec![3, 7],
            "GF-549 fires on local address/array only"
        );
    }

