    /// M23 Phase 3 (loop-carried taint): a sink at the TOP of a loop body reads a
    /// value the loop taints at its BOTTOM — clean on iteration 1, tainted on the
    /// back-edge. The loop-carried closure catches it where a single linear pass
    /// would not.
    #[test]
    fn loop_carried_taint_reaches_sink_at_loop_top() {
        let root = temp_dir("go-loop-taint");
        fs::write(
            root.join("main.go"),
            "package p\n\
             import \"os/exec\"\n\
             func loopcarry(userInput string) {\n\
                var cmd string\n\
                for i := 0; i < 3; i++ {\n\
                   exec.Command(cmd)\n\
                   cmd = userInput\n\
                }\n\
             }\n",
        )
        .unwrap();

        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();

        // The sink at line 6 (before `cmd = userInput` at line 7) fires via the
        // loop back-edge.
        assert!(
            report
                .findings
                .iter()
                .any(|f| f.rule_id == "GF-304" && f.location.line == 6),
            "loop-carried taint must reach the sink at the loop top"
        );
    }

