    #[test]
    fn call_graph_resolves_direct_c_function_calls() {
        let root = temp_dir("call-graph");
        fs::write(
            root.join("parse.c"),
            "int parse_header(const unsigned char *data, unsigned long len) { return (int)len; }\n\
             int parse_packet(const unsigned char *data, unsigned long len) { return parse_header(data, len); }\n",
        )
        .unwrap();

        let graph = analyze_call_graph(&root).unwrap();

        assert!(graph
            .nodes
            .iter()
            .any(|node| node.name == "parse_packet" && node.language == "c"));
        assert!(graph.edges.iter().any(|edge| edge.caller == "parse_packet"
            && edge.callee == "parse_header"
            && edge.call == "parse_header"));
    }

    #[test]
    fn call_graph_resolves_ada_parameterless_procedure_calls() {
        let root = temp_dir("ada-call-graph");
        fs::write(
            root.join("helper.adb"),
            "procedure Helper is\n\
             begin\n\
                null;\n\
             end Helper;\n",
        )
        .unwrap();
        fs::write(
            root.join("parse.adb"),
            "procedure Parse (Input : in String) is\n\
             begin\n\
                Helper;\n\
                if Input'Length > 0 then\n\
                   null;\n\
                end if;\n\
             end Parse;\n",
        )
        .unwrap();

        let graph = analyze_call_graph(&root).unwrap();

        assert!(graph
            .nodes
            .iter()
            .any(|node| node.name == "parse" && node.language == "ada"));
        assert!(graph
            .nodes
            .iter()
            .any(|node| node.name == "helper" && node.language == "ada"));
        assert!(
            graph.edges.iter().any(|edge| edge.caller == "parse"
                && edge.callee == "helper"
                && edge.call == "helper"),
            "Ada call graph should resolve Parse -> Helper: {graph:#?}"
        );
    }

