    #[test]
    fn call_graph_resolves_call_to_ada_subprogram_renaming() {
        let root = temp_dir("ada-renaming-call-graph");
        // A package spec exposing a subprogram renaming (no body of its own).
        fs::write(
            root.join("text_utils.ads"),
            "package Text_Utils is\n\
             function Quote (S : String) return String renames Internal.Escape;\n\
             end Text_Utils;\n",
        )
        .unwrap();
        fs::write(
            root.join("driver.adb"),
            "with Text_Utils; use Text_Utils;\n\
             procedure Driver (Input : in String) is\n\
                Result : String := Quote (Input);\n\
             begin\n\
                null;\n\
             end Driver;\n",
        )
        .unwrap();

        let graph = analyze_call_graph(&root).unwrap();

        // The renaming is recorded as a reachable node...
        assert!(
            graph
                .nodes
                .iter()
                .any(|node| node.name == "quote" && node.language == "ada"),
            "subprogram renaming should be a call-graph node: {graph:#?}"
        );
        // ...so the call to it resolves instead of being reported as unresolved.
        assert!(
            graph
                .edges
                .iter()
                .any(|edge| edge.caller == "driver" && edge.callee == "quote"),
            "call to a renaming should resolve to it: {graph:#?}"
        );
        assert!(
            !graph
                .unresolved_calls
                .iter()
                .any(|call| call.call.to_ascii_lowercase().contains("quote")),
            "a resolved renaming call must not also be reported unresolved: {graph:#?}"
        );
    }

