    #[test]
    fn gf404_getenv_fed_system_is_flagged() {
        // getenv() result stored in a variable and then passed to system().
        let root = temp_dir("gf404-getenv-system");
        fs::write(
            root.join("bad.c"),
            "void vuln(void) { char *cmd = getenv(\"X\"); system(cmd); }\n",
        )
        .unwrap();
        let report = scan(&StaticScanOptions {
            root: root.clone(),
            out_dir: root.join("out"),
            suppressions_path: None,
            baseline_path: None,
            policy_path: None,
            enabled_rules: BTreeSet::new(),
            disabled_rules: BTreeSet::new(),
            emit_sarif: false,
        })
        .unwrap();
        // getenv() is a recognized input SOURCE, so `cmd` is tainted and the flow
        // to system() is now a taint-confirmed command injection (GF-304), which
        // supersedes the pattern hit (GF-404) at the same site. Either rule proves
        // the getenv-fed system() is flagged.
        assert!(
            report
                .findings
                .iter()
                .any(|f| matches!(f.rule_id.as_str(), "GF-304" | "GF-404")),
            "system(getenv-derived var) must be flagged: {report:#?}"
        );
        // Specifically, the source-API taint path fires.
        assert!(
            report
                .findings
                .iter()
                .any(|f| f.rule_id == "GF-304" && f.analysis.engine == "govfuzz.static.taint.v1"),
            "getenv->system should be a taint-confirmed GF-304: {report:#?}"
        );
    }

